<template>
  <q-tooltip
    anchor="bottom middle"
    self="top middle"
    max-width="440px"
    data-test="search-capability-tooltip"
  >
    <div class="search-capability-tooltip">
      <template v-if="isFulltextEnabled">
        <div class="search-capability-tooltip__title">{{ title }}</div>
        <div class="search-capability-tooltip__desc">{{ description }}</div>
      </template>

      <div
        v-else
        class="search-capability-tooltip__details"
        data-test="search-capability-tooltip-details"
      >
        <div
          class="search-capability-tooltip__row"
          data-test="search-capability-filename-hint"
        >
          {{ filenameHint }}
        </div>
        <div
          class="search-capability-tooltip__row search-capability-tooltip__row--muted"
          data-test="search-capability-more-options-hint"
        >
          {{ moreOptionsHint }}
        </div>
      </div>
    </div>
  </q-tooltip>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { i18n } from 'src/boot/i18n';
import { resolveCapabilityMode } from './search-help-capability';

const tf = (key: string, fallback: string): string => {
  const value = i18n.t(key);
  if (typeof value !== 'string' || !value || value === key) return fallback;
  return value;
};

export default defineComponent({
  name: 'SearchCapabilityTooltip',
  props: {
    isFulltextEnabled: { type: Boolean, required: true },
    isVectorEnabled: { type: Boolean, required: true },
  },
  setup(props) {
    const mode = computed(() =>
      resolveCapabilityMode(props.isFulltextEnabled, props.isVectorEnabled),
    );
    const title = computed(() =>
      i18n.t(`search_capability_mode_${mode.value}_title`),
    );
    const description = computed(() =>
      i18n.t(`search_capability_mode_${mode.value}_desc`),
    );

    const filenameHint = computed(() =>
      tf('search_inactive_filename_hint', 'Type any text to search by filename.'),
    );
    const moreOptionsHint = computed(() =>
      tf(
        'search_inactive_more_options_hint',
        'Press the icon or use autocomplete to search other fields.',
      ),
    );

    return {
      title,
      description,
      filenameHint,
      moreOptionsHint,
    };
  },
});
</script>

