export type CapabilityMode = 'full' | 'fulltext' | 'vector' | 'standard';

export type CapabilityRequirement = 'fulltext' | 'vector' | undefined;

export interface CapabilityStates {
  fulltext: boolean;
  vector: boolean;
}

// Vector is a SUB-SETTING of Fulltext — the OPENSEARCH_VECTOR_* flags
// live inside the Fulltext settings page and can only be toggled from
// there. An org with fulltext=off cannot manage vector and the routing
// requires fulltext infrastructure (OpenSearch). Therefore the
// (fulltext=false, vector=true) state is impossible-in-practice and
// resolves to 'standard' — the same mode the org would see if vector
// had never been enabled.
export function resolveCapabilityMode(
  isFulltextEnabled: boolean,
  isVectorEnabled: boolean,
): CapabilityMode {
  if (!isFulltextEnabled) return 'standard';
  return isVectorEnabled ? 'full' : 'fulltext';
}

export function formatDocumentsLine(
  indexed: number,
  total: number,
  formatNumber: (n: number) => string,
  template: (indexedStr: string, totalStr: string, pendingStr: string) => string,
  pendingTemplate: (pendingStr: string) => string,
): string {
  const pending = Math.max(0, total - indexed);
  const pendingSuffix = pending > 0 ? pendingTemplate(formatNumber(pending)) : '';
  return template(formatNumber(indexed), formatNumber(total), pendingSuffix);
}

export function formatVectorLine(
  isVectorEnabled: boolean,
  embedded: number,
  total: number,
  formatNumber: (n: number) => string,
  template: (embeddedStr: string, totalStr: string, pendingStr: string) => string,
  pendingTemplate: (pendingStr: string) => string,
): string | null {
  if (!isVectorEnabled) return null;
  const pending = Math.max(0, total - embedded);
  const pendingSuffix = pending > 0 ? pendingTemplate(formatNumber(pending)) : '';
  return template(formatNumber(embedded), formatNumber(total), pendingSuffix);
}

export function supportsCapability(
  requires: CapabilityRequirement,
  states: CapabilityStates,
): boolean {
  if (!requires) return true;
  if (requires === 'fulltext') return states.fulltext;
  if (requires === 'vector') return states.vector;
  return false;
}
