<template>
  <div class="restartFilter_wrapper">
    <q-checkbox
      v-model="restartFilter"
      @update:model-value="modelUpdatedCheckbox"
    />
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDashboardStore } from 'src/store/main';

export default defineComponent({
  watch: {
    tempFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadSavedFiler();
      },
    },
  },
  mounted() {
    this.loadSavedFiler();
  },
  methods: {
    modelUpdatedCheckbox() {
      if (!this.restartFilter) {
        this.tempFilterMap.delete('restart_filter');
      } else {
        this.tempFilterMap.set('restart_filter', true);
      }

      const reset_event = new CustomEvent('reset_pages', { detail: {} });
      document.dispatchEvent(reset_event);
    },
    loadSavedFiler() {
      this.restartFilter = this.tempFilterMap.get('restart_filter') ?? false;
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { tempFilterMap } = storeToRefs(dashboard_store);
    return {
      tempFilterMap,
      restartFilter: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped>
.restartFilter_wrapper {
  width: 227px;
  margin-right: 8px;
}
</style>
