<template>
  <div class="row q-gutter-md justify-start">
    <q-card
      id="all_invoices"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--primary"
      @click="filterTabSelected('all_invoices', $t('all_invoices'))"
      :class="selected_filter_status === 'all_invoices' ? 'selected-card' : ''"
    >
      <q-card-section>
        <div class="text-h6">{{ all_invoices }}</div>
        <div class="text-subtitle2">{{ $t('all_invoices') }}</div>
      </q-card-section>
      <q-tooltip>Click to Filter by {{ $t('all_invoices') }}</q-tooltip>
    </q-card>

    <q-card
      id="in_progress"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--blue"
      @click="filterTabSelected('in-progress', $t('in_progress'))"
      :class="selected_filter_status === 'in-progress' ? 'selected-card' : ''"
    >
      <q-card-section>
        <div class="text-h6">{{ in_progress }}</div>
        <div class="text-subtitle2">{{ $t('in_progress') }}</div>
      </q-card-section>
      <q-tooltip>Click to Filter by {{ $t('in_progress') }}</q-tooltip>
    </q-card>

    <q-card
      id="pending_user_input"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--yellow"
      @click="filterTabSelected('pending-user-input', $t('pending_user_input'))"
      :class="
        selected_filter_status === 'pending-user-input' ? 'selected-card' : ''
      "
    >
      <q-card-section>
        <div class="text-h6">{{ pending }}</div>
        <div class="text-subtitle2">{{ $t('pending_user_input') }}</div>
      </q-card-section>
      <q-tooltip>Click to Filter by {{ $t('pending_user_input') }}</q-tooltip>
    </q-card>

    <q-card
      id="validated_pending_approval"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--grey"
      @click="
        filterTabSelected(
          'validated_pending_approval',
          $t('validated_pending_approval'),
        )
      "
      :class="
        selected_filter_status === 'validated_pending_approval'
          ? 'selected-card'
          : ''
      "
    >
      <q-card-section>
        <div class="text-h6">
          {{ validated_pending_approval + approved_pending_second_approval }}
        </div>
        <div class="text-subtitle2">
          {{ $t('validated_pending_approval') }}
        </div>
      </q-card-section>
      <q-tooltip
        >Click to Filter by {{ $t('validated_pending_approval') }}</q-tooltip
      >
    </q-card>

    <q-card
      id="exported"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--green"
      @click="filterTabSelected('finished', $t('exported'))"
      :class="selected_filter_status === 'finished' ? 'selected-card' : ''"
    >
      <q-card-section>
        <div class="text-h6">{{ completed }}</div>
        <div class="text-subtitle2">{{ $t('exported') }}</div>
      </q-card-section>

      <q-tooltip>Click to Filter by {{ $t('exported') }}</q-tooltip>
    </q-card>

    <q-card
      id="error"
      class="analytic-card no-shadow cursor-pointer clickable dashboard-analytics-card dashboard-analytics-card--red"
      @click="filterTabSelected('error', $t('error'))"
      :class="selected_filter_status === 'error' ? 'selected-card' : ''"
    >
      <q-card-section>
        <div class="text-h6">{{ error }}</div>
        <div class="text-subtitle2">{{ $t('error') }}</div>
      </q-card-section>
      <q-tooltip>Click to Filter by {{ $t('error') }}</q-tooltip>
    </q-card>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';

export default defineComponent({
  mixins: [],
  props: {},
  watch: {
    quickFilterMap: {
      deep: true,
      immediate: true,
      handler: function () {
        this.syncSelectedFilterFromMap();
      },
    },
  },
  components: {},

  mounted() {
    document.addEventListener('dashboard_refresh', this.refreshFilters);
  },
  unmounted: function () {
    document.removeEventListener('dashboard_refresh', this.refreshFilters);
  },

  methods: {
    refreshFilters() {
      this.all_invoices = 0;
      this.automatically_processed = 0;
      this.manually_processed = 0;
      this.completed = 0;
      this.in_progress = 0;
      this.pending = 0;
      this.validated_pending_approval = 0;
      this.approved_pending_second_approval = 0;
      this.error = 0;
    },

    syncSelectedFilterFromMap() {
      const status = this.quickFilterMap.get('status');

      if (!status) {
        this.selected_filter_status = 'all_invoices';
        return;
      }

      // Handle combined status for pending approval
      if (
        status.includes('validated_pending_approval') &&
        status.includes('approved_pending_second_approval')
      ) {
        this.selected_filter_status = 'validated_pending_approval';
        return;
      }

      // Map status values to card IDs
      const statusToCard: Record<string, string> = {
        'in-progress': 'in-progress',
        'pending-user-input': 'pending-user-input',
        validated_pending_approval: 'validated_pending_approval',
        finished: 'finished',
        error: 'error',
        all_invoices: 'all_invoices',
      };

      // Clean up status string (remove trailing comma if present)
      const cleanStatus = status.replace(/,$/, '');

      if (statusToCard[cleanStatus]) {
        this.selected_filter_status = statusToCard[cleanStatus];
      } else {
        // If status doesn't match any card, default to all_invoices
        this.selected_filter_status = 'all_invoices';
      }
    },
    filterTabSelected(status: string, label: string) {
      this.selected_filter_status = status;
      const event = new CustomEvent('quick_filter_remove', {
        detail: 'status',
      });
      document.dispatchEvent(event);
      this.quickFilterMap.delete('tab_status');
      this.quickFilterMap.delete('status_list');
      this.quickFilterMap.delete('status');
      if (status === 'validated_pending_approval') {
        let status_str = 'validated_pending_approval' + ',' + 'approved_pending_second_approval' + ',';
        this.quickFilterMap.set('status', status_str);
        this.quickFilterMap.set('status_list', [
          {
            value: 'validated_pending_approval',
            label: 'Pending Approval',
          },
          {
            value: 'approved_pending_second_approval',
            label: 'Pending Second Approval',
          },
        ]);
      } else {
        this.quickFilterMap.set('status', status);
        this.quickFilterMap.set('status_list', [
          {
            value: status,
            label: label,
          },
        ]);
      }
      this.triggerApplyFilters();
    },
    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const {
      quickFilterMap,
      all_invoices,
      automatically_processed,
      manually_processed,
      completed,
      in_progress,
      pending,
      validated_pending_approval,
      approved_pending_second_approval,
      error,
    } = storeToRefs(dashboard_store);

    return {
      quickFilterMap,
      show_analytics: ref(false),
      selected_filter_status: ref('all_invoices'),
      all_invoices,
      automatically_processed,
      manually_processed,
      completed,
      in_progress,
      pending,
      validated_pending_approval,
      approved_pending_second_approval,
      error,
    };
  },
});
</script>

