<template>
  <node-view-wrapper as="span" class="qs-chip-wrapper" contenteditable="false">
    <!-- Connector (AND/OR) is its own ConnectorNode sibling in the
         document now; this view renders only the chip body. -->
    <span
      class="qs-chip"
      :class="[
        chipClass,
        {
          'qs-chip--presence': isPresence,
          'qs-chip--directive': isDirective,
          'qs-chip--bool': isBool,
          'qs-chip--bool-positive': isBool && boolPolarity === 'positive',
          'qs-chip--bool-negative': isBool && boolPolarity === 'negative',
        },
      ]"
      data-test="qs-chip"
      :data-test-field="node.attrs.field"
      :data-test-op="node.attrs.op"
      :data-test-kind="chipKind"
      @click.stop="onChipClick"
      :title="expandTitle"
    >
      <span class="key" data-test="qs-chip-key">
        <span v-if="isDirective" class="directive-icon" aria-hidden="true"
          >⌥</span
        >
        {{ displayLabel }}
      </span>
      <!-- Bug-2026-04-28: presence-check chips (op=`!=` or `=` with
           empty value) get a friendly "has a value" / "is empty" label
           instead of an em-dash placeholder. The raw `op + ""` form
           still serialises correctly for the backend; this just makes
           the chip readable. -->
      <template v-if="isPresence">
        <span class="presence-label" data-test="qs-chip-presence">{{ presenceLabel }}</span>
      </template>
      <template v-else-if="isDirective">
        <span class="op">:</span>
        <span class="value" data-test="qs-chip-value">{{ displayValue }}</span>
      </template>
      <template v-else-if="isBetween">
        <span class="op" data-test="qs-chip-op">{{ betweenLabel }}</span>
        <span class="value qs-chip-range" data-test="qs-chip-range">{{ displayValue }}</span>
      </template>
      <template v-else-if="isBool">
        <!-- Boolean chips: skip the operator (the prettified value
             "Edocs" / "Non-edocs" / "Yes" / "No" is self-explanatory)
             and render the value as a tinted pill with a polarity icon. -->
        <span class="bool-value" data-test="qs-chip-value">{{ displayValue }}</span>
      </template>
      <template v-else>
        <span class="op" data-test="qs-chip-op">{{ node.attrs.op }}</span>
        <span class="value" data-test="qs-chip-value">{{ displayValue }}</span>
      </template>
      <span class="x" @click.stop="onDelete" title="×" data-test="qs-chip-delete">×</span>
    </span>
  </node-view-wrapper>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { NodeViewWrapper } from '@tiptap/vue-3';
import { FIELD_CATALOG, customFieldsToFieldMetas } from '../searchQueryParser';
import { useFieldValueSource } from '../useFieldValueSource';
import { useDocTypeFieldsStore } from 'src/store/Settings/doc_type_fields.store';
import { i18n } from 'src/boot/i18n';

// Only bothered for fields whose value→label mapping is non-trivial;
// for priority / currency / free-text fields the value IS the display
// form, and doing the lookup would just add a store subscription for
// nothing.
const FIELDS_WITH_LABEL_LOOKUP = [
  'assigned_to',
  'created_by',
  'last_saved_by',
  'status',
  'doc_type',
  'sub_org_name',
];

// Directive value rendering: turn `supplier_name` → "Supplier Name",
// `supplier_name|month` → "Supplier Name (Month)". Reuses the i18n
// keys already pushed for the GroupByChips control above the table.
const DIRECTIVE_VALUE_KEYS: Record<string, string> = {
  status: 'dashboard_group_by_status',
  doc_type: 'dashboard_group_by_doc_type',
  supplier_name: 'supplier_name',
  vendor_name: 'dashboard_group_by_vendor',
  assigned_to: 'dashboard_group_by_assigned',
  created_on: 'dashboard_group_by_created_month',
  invoice_date: 'dashboard_group_by_invoice_month',
  delivery_date: 'dashboard_group_by_delivery_month',
};

// Boolean-style fields (is_edoc, future has_zugferd / has_peppol)
// get a friendly Yes/No label via Tolgee i18n keys instead of the
// raw "true" / "false". Field-specific keys (is_edoc → "Edocs" /
// "E-Dokumente") match the smart-filter card vocabulary.
const BOOL_VALUE_KEYS: Record<
  string,
  {
    trueKey: string;
    falseKey: string;
    trueFallback: string;
    falseFallback: string;
  }
> = {
  is_edoc: {
    trueKey: 'chip_value_yes',
    falseKey: 'chip_value_no',
    trueFallback: 'Yes',
    falseFallback: 'No',
  },
};

export default defineComponent({
  name: 'ChipNodeView',
  components: { NodeViewWrapper },

  // Injected by VueNodeViewRenderer:
  props: {
    editor: { type: Object, required: true },
    node: { type: Object, required: true },
    decorations: { type: Array, required: false, default: () => [] },
    selected: { type: Boolean, required: false, default: false },
    extension: { type: Object, required: true },
    getPos: { type: Function, required: true },
    updateAttributes: { type: Function, required: true },
    deleteNode: { type: Function, required: true },
  },

  setup() {
    // The DocTypeFields store is the only piece needed in setup —
    // pinia stores must be acquired with composable syntax. The rest
    // of the component lives in Options API blocks below.
    const docFieldsStore = useDocTypeFieldsStore();
    return { docFieldsStore };
  },

  data() {
    return {
      expandTitle: 'Click to edit',
    };
  },

  computed: {
    // The group-by directive lives in a pseudo-field "group_by" — it
    // is NOT a column the backend filters on, so the regular catalog
    // lookup would just render the raw token. Special-case here so
    // the chip body reads as a coherent sentence ("Group by · Vendor").
    isDirective(): boolean {
      return (this.node as any).attrs.field === 'group_by';
    },

    // Chips prefer the compact `labelKey` so a row of predicates
    // doesn't devolve into a wall of descriptive sentences. Fall back
    // to descriptionKey, then displayName, then the raw field name.
    displayLabel(): string {
      if (this.isDirective) {
        try {
          return (i18n as any).t('dashboard_group_by');
        } catch {
          return 'Group by';
        }
      }
      const field = (this.node as any).attrs.field as string;
      const meta = FIELD_CATALOG.find((f) => f.name === field);
      if (meta) {
        const tryI18n = (key: string | undefined): string | null => {
          if (!key) return null;
          try {
            const value = (i18n as any).t(key);
            return value && value !== key ? value : null;
          } catch {
            return null;
          }
        };
        return (
          tryI18n(meta.labelKey) ??
          tryI18n(meta.descriptionKey) ??
          meta.displayName ??
          field
        );
      }
      // DRFS-581: custom doc-type field fallback. The pinia store
      // hydrates lazily from /document/search/fields; computed re-runs
      // when it lands and replaces the raw snake_case identifier with
      // the configured title.
      try {
        const custom = customFieldsToFieldMetas(
          (this.docFieldsStore as any).getAllUniqueFieldsWithDocTypes,
        ).find((f) => f.name === field);
        if (custom?.displayName) return custom.displayName;
      } catch {
        /* store not yet ready — fall through */
      }
      return field;
    },

    // Prefer the explicit `label` attribute when the AC pick or the
    // tryCommit normaliser stored one. When absent — paste, reload-
    // rehydrate via buildDocContent, or a commit that ran before the
    // field's value source had loaded — fall back to looking up the
    // label reactively from the live value source. The computed
    // re-runs when the store populates, so "assigned_to=2" rendered
    // as "2" on mount becomes "Amier Haider" as soon as the users
    // list lands without any chip attrs needing to be mutated.
    displayValue(): string {
      const attrs = (this.node as any).attrs as {
        label?: string;
        field: string;
        value: string;
        op: string;
      };
      const { label, field, value } = attrs;
      if (attrs.op === 'between') {
        const [start, end] = String(value ?? '').split('..');
        return start && end ? `(${start}, ${end})` : label || value;
      }
      if (field === 'group_by') return this.directiveValueLabel(value);
      // Boolean values: i18n-translated. Per-field overrides
      // (is_edoc → "Edocs"/"Non-edocs") win over the generic
      // chip_bool_yes / _no fallback.
      const boolKeys = BOOL_VALUE_KEYS[field];
      const v = String(value ?? '').toLowerCase();
      if (boolKeys && (v === 'true' || v === 'false')) {
        return v === 'true'
          ? this.tBool(boolKeys.trueKey, boolKeys.trueFallback)
          : this.tBool(boolKeys.falseKey, boolKeys.falseFallback);
      }
      if (v === 'true') return this.tBool('chip_value_yes', 'Yes');
      if (v === 'false') return this.tBool('chip_value_no', 'No');
      if (label) return label;
      if (!FIELDS_WITH_LABEL_LOOKUP.includes(field)) return value;
      const { options } = useFieldValueSource(field);
      const list = options.value ?? [];
      const match = list.find(
        (o) => String(o.value ?? '') === String(value ?? ''),
      );
      return match?.label ?? value;
    },

    // Boolean-aware chip detection — true/false on a boolean-style
    // field gets its own visual treatment (positive/negative tint
    // plus value-only rendering — no operator literal, since `=Yes` /
    // `=No` reads strangely; the prettified value is self-explanatory).
    isBool(): boolean {
      const field = (this.node as any).attrs.field as string;
      const value = String((this.node as any).attrs.value ?? '').toLowerCase();
      return (
        field in BOOL_VALUE_KEYS && (value === 'true' || value === 'false')
      );
    },

    boolPolarity(): 'positive' | 'negative' {
      return String((this.node as any).attrs.value ?? '').toLowerCase() ===
        'true'
        ? 'positive'
        : 'negative';
    },

    // CSS class driven by category. Bug-2026-05-05: a fulltext field
    // could render with the standard chip colour because chip attrs
    // freeze at commit-time and a stale shipped catalog or saved-
    // filter restore baked in `category: 'standard'`. Resolution:
    //   1. Explicit non-standard attr wins (the user picked from a
    //      specific dropdown section).
    //   2. Otherwise consult the live FIELD_CATALOG to recover.
    //   3. Default to no modifier class (standard blue).
    chipClass(): string {
      const attrCat = (this.node as any).attrs.category;
      if (attrCat === 'extended') return 'qs-chip--extended';
      if (attrCat === 'fulltext') return 'qs-chip--fulltext';
      if (attrCat === 'vector') return 'qs-chip--vector';
      if (attrCat === 'ocr') return 'qs-chip--ocr';
      const meta = FIELD_CATALOG.find(
        (f) => f.name === (this.node as any).attrs.field,
      );
      if (meta?.category === 'extended') return 'qs-chip--extended';
      if (meta?.category === 'fulltext') return 'qs-chip--fulltext';
      if (meta?.category === 'vector') return 'qs-chip--vector';
      if (meta?.category === 'ocr') return 'qs-chip--ocr';
      return '';
    },

    // Bug-2026-04-28: a chip with op=`!=` or `=` and an empty value
    // is a presence check. Render with a clear label instead of an
    // em-dash placeholder.
    isPresence(): boolean {
      const { op, value } = (this.node as any).attrs as {
        op: string;
        value: string;
      };
      return (op === '!=' || op === '=') && value === '';
    },

    presenceLabel(): string {
      const op = (this.node as any).attrs.op as string;
      try {
        return op === '!='
          ? (i18n as any).t('search_op_preset_is_not_empty')
          : (i18n as any).t('search_op_preset_is_empty');
      } catch {
        return op === '!=' ? 'is not null' : 'is null';
      }
    },

    isBetween(): boolean {
      return (this.node as any).attrs.op === 'between';
    },

    betweenLabel(): string {
      try {
        return (i18n as any).t('search_op_between');
      } catch {
        return 'between';
      }
    },

    chipKind(): string {
      if (this.isPresence) return 'presence';
      if (this.isDirective) return 'directive';
      if (this.isBetween) return 'between';
      if (this.isBool) return 'bool';
      return 'predicate';
    },
  },

  methods: {
    tBool(key: string, fallback: string): string {
      try {
        const v = (i18n as any).t(key);
        return v && v !== key ? v : fallback;
      } catch {
        return fallback;
      }
    },

    // Directive value rendering helper used by displayValue.
    directiveValueLabel(raw: string): string {
      const [field, bucket] = raw.split('|');
      const key = DIRECTIVE_VALUE_KEYS[field];
      let baseLabel = field;
      if (key) {
        try {
          baseLabel = (i18n as any).t(key);
        } catch {
          baseLabel = field;
        }
      }
      if (!bucket) return baseLabel;
      try {
        const bucketLabel = (i18n as any).t(
          'dashboard_group_by_bucket_' + bucket,
        );
        return `${baseLabel} (${bucketLabel})`;
      } catch {
        return `${baseLabel} (${bucket})`;
      }
    },

    // Click-to-edit: serialise the chip back to the canonical text
    // form and replace the chip node with that text. Directive chips
    // round-trip via natural-language `group by …` so the chip-commit
    // pass recognises them on the next Enter.
    onChipClick() {
      const getPos = (this as any).getPos as () => number;
      const pos = getPos();
      const { field, op, value, quoted } = (this.node as any).attrs as {
        field: string;
        op: string;
        value: string;
        quoted?: boolean;
      };
      let text: string;
      if (field === 'group_by') {
        const [gbField, bucket] = value.split('|');
        text = `group by ${gbField}${bucket ? ' ' + bucket : ''}`;
      } else if (op === 'between') {
        text = `${field} between ${String(value).replace('..', ', ')}`;
      } else {
        const valuePart =
          value === ''
            ? '""'
            : quoted || /\s/.test(value)
              ? `"${value}"`
              : value;
        text = `${field}${op}${valuePart}`;
      }
      const editor = (this as any).editor;
      // Read nodeSize from the RAW node in the editor state, not from
      // props.node — Vue's reactive proxy over a ProseMirror Node
      // instance returns `content.size + 2` (fallback) instead of 1
      // for atomic inline nodes, which causes deleteRange to swallow
      // the adjacent chip.
      const rawNode = editor.state.doc.nodeAt(pos);
      const size = rawNode?.nodeSize ?? 1;
      editor
        .chain()
        .focus()
        .deleteRange({ from: pos, to: pos + size })
        .insertContentAt(pos, text)
        .setTextSelection(pos + text.length)
        .run();
    },

    onDelete() {
      (this as any).deleteNode();
    },
  },
});
</script>
