<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { defineComponent, ref } from 'vue';
import {
  useDashboardStore,
  useSettingStore,
  useDropdownStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';
import TimeFilter from 'src/pages/Dashboard/advancedSettings/time-filter.vue';
// import DocTypeFilter from './Filters/doc_type-filter.vue';
import advancedSettings from './advancedSettings/main.vue';
import quickSearch from './Filters/quick-search.vue';
// import StatusFilter from './Filters/status-filter.vue';
import savedFilterBadges from './Filters/saved-filter-badges.vue';
import ImportMultiInvoice from 'src/pages/import-multi-invoice.vue';
// import multipleListViewButton from 'src/pages/Dashboard/multipleListView/Button.vue';
import scanButton from './scanButton.vue';
import analytics from './analytics.vue';
import keyboardShortcutInfo from './ShortcutInfo.vue';
import keyboard from 'src/pages/Dashboard/keyboard';
import { importApiService } from 'src/services';
import { export_dashboard_data_setting } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import { dynamicObj } from '../assets';
import { documentListApiService } from 'src/services';
export default defineComponent({
  mixins: [keyboard],
  // props: {},
  watch: {},
  components: {
    savedFilterBadges,
    ImportMultiInvoice,
    // StatusFilter,
    // DocTypeFilter,
    advancedSettings,
    TimeFilter,
    quickSearch,
    scanButton,
    analytics,
    keyboardShortcutInfo,
    
    // multipleListViewButton
  },
  data() {
    return {
      selectedDocType: this.$t('all'),
      isDebugMode: false,
      isRefreshing: false,
    };
  },
  mounted: function () {
    document.addEventListener('keydown', this.keyDownEvent);
    document.addEventListener(
      'open_keyboard_shortcuts',
      this.openKeyboardShortcuts,
    );
    if (!this.user_settings[this.export_dashboard_data_setting]) {
      this.user_settings[this.export_dashboard_data_setting] = false;
    }
    this.export_active = this.user_settings[this.export_dashboard_data_setting];
    document.documentElement.style.setProperty(
      '--org-color',
      this.user_settings['ORG_COLOR_PREFERENCE'],
    );
    this.checkIfDebugMode();
  },
  unmounted: function () {
    document.removeEventListener('keydown', this.keyDownEvent);
    document.removeEventListener(
      'open_keyboard_shortcuts',
      this.openKeyboardShortcuts,
    );
  },
  computed: {
    validatedPercentage() {
      const total =
        Number(this.validated_pending_approval) + Number(this.pending);
      return total > 0 ? this.validated_pending_approval / total : 0;
    },
    pendingPercentage() {
      const total =
        Number(this.validated_pending_approval) + Number(this.pending);
      return total > 0 ? this.pending / total : 0;
    },
    // 2026-05-05: drives the v-if on the TimeFilter blocks above. The
    // date range buttons are a Postgres-performance crutch — when
    // OpenSearch is the routing engine we don't need them, so hiding
    // them frees the row for the search input to grow leftward.
    isFulltextEnabled(): boolean {
      // OPENSEARCH_ENABLED lives on the ORG-level config, not user-level.
      // Mirrors the same lookup in quick-search.vue's setup().
      const v = (this.org_based_settings as any)?.OPENSEARCH_ENABLED;
      return v === true || v === 'true' || v === 1 || v === '1';
    },
  },
  methods: {
    openKeyboardShortcuts() {
      this.showKeyboardShortcuts = true;
    },
    handleRefreshClick() {
      if (this.isRefreshing) {
        return;
      }
      this.isRefreshing = true;
      this.refreshFilters();

      // Re-enable button after 2 seconds to prevent rapid clicks
      setTimeout(() => {
        this.isRefreshing = false;
      }, 1000);
    },
    refreshFilters() {
      const event = new CustomEvent('dashboard_refresh_data', {
        detail: {
          show_shimmer_loader: true,
          refresh_cache: true,
          refresh_long_cache: true,
        },
      });
      document.dispatchEvent(event);
    },
    beforeShowKeyboard() {
      const event = new CustomEvent('advancedSettingsClose');
      document.dispatchEvent(event);
    },
    beforeHideKeyboard() {
      document.dispatchEvent(
        new CustomEvent('remove_advanced_settings_pop_up'),
      );
    },
    async startEmailImport() {
      try {
        const response = await importApiService.importAllEmails();

        if (response.success === false) {
          throw response;
        }

        notify.success(response.message);
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
    },

    exportDashboardData(type: string) {
      if (type === 'excel') {
        const event = new CustomEvent('export_data_as_excel', {
          detail: { show_shimmer_loader: true, refresh_cache: true },
        });
        document.dispatchEvent(event);
      } else if (type === 'csv') {
        const event = new CustomEvent('export_data_as_csv', {
          detail: { show_shimmer_loader: true, refresh_cache: true },
        });
        document.dispatchEvent(event);
      }
    },

    showStatisticsSection() {
      this.showMoreStats = this.showMoreStats == false ? true : false;
    },

    async changeLinearProgress(document_type: any) {
      if (document_type) {
        const queryParams = '?doc_type=' + document_type.value;
        const response = await documentListApiService.getList(queryParams);

        this.validated_pending_approval = response.documents.filter(
          (document: { status: string }) =>
            document.status === 'pending_approval',
        ).length;
        this.pending = response.documents.filter(
          (document: { status: string }) => document.status === 'pending',
        ).length;
      } else {
        this.validated_pending_approval = 0;
        this.pending = 0;
      }
    },

    applyDashboardFilter(filter_type: string) {
      const event = new CustomEvent('apply_counter_filter', {
        detail: { status: filter_type },
      });
      document.dispatchEvent(event);
    },
    checkIfDebugMode() {
      if (this.$route.query.debug === 'true') {
        this.isDebugMode = true;
      }
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const {
      quickFilterMap,
      all_invoices,
      completed,
      in_progress,
      pending,
      notifyUpdate,
      current_invoice_count,
      showKeyboardShortcuts,
      show_analytics,
      validated_pending_approval,
      show_loading_times,
      selected_dashboard,
    } = storeToRefs(dashboard_store);

    const settings_store = useSettingStore();
    const { user_settings, org_based_settings } = storeToRefs(settings_store);

    const dropdown_store = useDropdownStore();
    const { doc_type_list } = storeToRefs(dropdown_store);

    return {
      current_invoice_count,
      showKeyboardShortcuts,
      quickFilterMap,
      show_advanced_filters: ref(false),
      show_analytics,
      all_invoices,
      export_dashboard_data_setting,
      export_active: ref(false),
      user_settings,
      org_based_settings,
      completed,
      notifyUpdate,
      selected_dashboard,
      in_progress,
      pending,
      showMoreStats: ref(false),
      doc_type_list,
      validated_pending_approval,
      show_loading_times,
    };
  },
});
</script>
