import { Extension } from '@tiptap/vue-3';
import { Plugin, PluginKey, TextSelection } from '@tiptap/pm/state';
import { FIELD_CATALOG } from '../searchQueryParser';

const NON_QUOTABLE_VALUE_TYPES = new Set(['numeric', 'date', 'uuid']);

function countUnescapedQuotes(text: string): number {
  let n = 0;
  for (let i = 0; i < text.length; i += 1) {
    if (text[i] === '"' && text[i - 1] !== '\\') n += 1;
  }
  return n;
}

export function shouldAutoQuoteEquals(
  textBefore: string,
  charAfter: string,
): boolean {
  if (countUnescapedQuotes(textBefore) % 2 === 1) return false;
  if (charAfter === '"') return false;
  const prev = textBefore[textBefore.length - 1] ?? '';
  if (prev === '>' || prev === '<' || prev === '!') return false;
  return true;
}

export function hasDanglingQuote(text: string): boolean {
  return countUnescapedQuotes(text) % 2 === 1;
}

export function fieldAllowsAutoQuote(fieldName: string): boolean {
  if (!fieldName) return true;
  const lower = fieldName.toLowerCase();
  const meta = FIELD_CATALOG.find((f) => f.name.toLowerCase() === lower);
  if (!meta) return true;
  return !NON_QUOTABLE_VALUE_TYPES.has(meta.valueType);
}

export const AutoQuoteOnEquals = Extension.create({
  name: 'rawAutoQuoteOnEquals',

  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: new PluginKey('raw-auto-quote-on-equals'),
        props: {
          handleTextInput(view, from, to, text) {
            if (text !== '=') return false;
            const { state } = view;
            const $from = state.doc.resolve(from);
            const before = state.doc.textBetween($from.start(), from, '\0');
            const after = state.doc.textBetween(
              from,
              Math.min(from + 1, $from.end()),
              '\0',
            );
            if (!shouldAutoQuoteEquals(before, after)) return false;
            const fieldMatch = /([A-Za-z_][\w]*)\s*$/.exec(before);
            if (fieldMatch && !fieldAllowsAutoQuote(fieldMatch[1])) {
              return false;
            }
            const tr = state.tr.insertText('="', from, to);
            tr.setSelection(TextSelection.create(tr.doc, from + 2));
            view.dispatch(tr);
            return true;
          },
        },
      }),
    ];
  },
});
