<template>
  <q-btn-toggle
    toggle-color="primary"
    class="toggle_time dashboard-text-color back-white"
    v-model="selected_time"
    @click="TimeFilterSelected"
    :ripple="false"
    :options="time_options"
  >
    <template v-for="(option, index) in time_options" :key="index" #[index]>
      <q-tooltip>
        {{ option.tooltip }}
      </q-tooltip>
    </template>
  </q-btn-toggle>

  <q-menu
    v-if="open_date_picker"
    @before-show="isCustomSelected"
    anchor="bottom right"
    self="top right"
  >
    <div class="q-pa-md">
      <dateRangeFilter :start_date="startDate" :end_date="endDate" />
      <q-btn
        color="primary"
        unelevated
        class="q-mr-sm mt-10 float-right q-mb-md text-uppercase"
        :label="$t('apply')"
        @click="triggerApplyFilters()"
        v-close-popup
      />
    </div>
  </q-menu>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import dateRangeFilter from 'src/pages/Dashboard/advancedSettings/date-range-filter.vue';
import { useDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
export default defineComponent({
    props: {},
  components: {
    dateRangeFilter,
  },
  data() {
    return {
      open_date_picker: false,
    };
  },
  computed: {
    // Use computed property so translations update dynamically when language changes
    time_options() {
      return [
        {
          label: this.$t('30_days'),
          value: 'last_30_days',
          tooltip: this.$t('last_30_days'),
          slot: '0',
        },
        {
          label: this.$t('3_months'),
          value: 'last_90_days',
          tooltip: this.$t('last_90_days'),
          slot: '1',
        },
        {
          label: this.$t('6_months'),
          value: 'last_180_days',
          tooltip: this.$t('last_180_days'),
          slot: '2',
        },
        {
          label: this.$t('365_days'),
          value: 'last_365_days',
          tooltip: this.$t('last_365_days'),
          slot: '3',
        },
        {
          label: this.$t('all'),
          value: 'all',
          tooltip: this.$t('all_time'),
          slot: '4',
        },
        {
          label: this.$t('custom'),
          value: 'custom',
          tooltip: this.$t('select_date_range'),
          slot: '5',
        },
      ];
    },
  },
  watch: {
    quickFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadFilters();
      },
    },
  },
  mounted() {
    this.loadFilters();
    document.addEventListener('clear_custom_dates', this.clearDates);
  },
  unmounted() {
    document.removeEventListener('clear_custom_dates', this.clearDates);
  },
  methods: {
    isCustomSelected() {
      if (this.selected_time != 'custom') {
        this.open_date_picker = false;
      }
    },
    loadFilters() {
      if (this.quickFilterMap.has('date_range')) {
        this.selected_time = 'custom';
        const range = this.quickFilterMap.get('date_range');
        if (range) {
          const dates = range.split(' To ');
          this.startDate = dates[0];
          this.endDate = dates[1];
        }
        return;
      }
      const selected_time = this.quickFilterMap.get('filter');

      if (!selected_time || !selected_time.hasOwnProperty('value')) {
        this.resetFilters();
        return;
      }
      this.selected_time = selected_time.value;
    },

    resetFilters() {
      this.selected_time = '';
    },

    TimeFilterSelected(val: any) {
      if (this.open_date_picker && this.selected_time != 'custom') {
        this.tempFilterMap.delete('date_range');
        this.quickFilterMap.delete('date_range');
        this.open_date_picker = false;
      }
      if (this.selected_time === 'custom') {
        this.open_date_picker = true;
        return;
      }
      if (
        this.selected_time == 'last_365_days' ||
        this.selected_time == 'all'
      ) {
        notify.warning(this.$t('may_increase_loading_time'));
      }
      this.quickFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time,
      });
      this.tempFilterMap.set('filter', {
        value: this.selected_time,
        label: this.selected_time,
      });
      this.clearDates();
      this.triggerApplyFilters();
    },

    triggerApplyFilters() {
      if (this.tempFilterMap.has('date_range')) {
        this.quickFilterMap.set(
          'date_range',
          this.tempFilterMap.get('date_range'),
        );
      }
      if (this.quickFilterMap.has('date_range')) {
        this.quickFilterMap.delete('filter');
        this.selected_time = 'custom';
      }
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    clearDates() {
      this.startDate = '';
      this.endDate = '';
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { quickFilterMap, tempFilterMap } = storeToRefs(dashboard_store);

    return {
      quickFilterMap,
      tempFilterMap,
      selected_time: ref(''),
      startDate: ref(''),
      endDate: ref(''),
    };
  },
});
</script>

