<template>
  <div class="qs-toolbar" data-test="qs-toolbar">
    <!-- Copy raw query — only meaningful when the user is in raw view
         AND the string is non-empty. Hidden otherwise to keep the
         append area tight. -->
    <q-btn
      v-if="showRaw"
      flat
      dense
      round
      icon="content_copy"
      size="sm"
      :disable="!rawQueryText"
      class="qs-toolbar__btn"
      data-test="qs-toolbar-copy-raw"
      @click="onCopyRawQuery"
    >
      <q-tooltip>{{ $t('copy') }}</q-tooltip>
    </q-btn>

    <!-- Filter tune menu — the dashboard's saved filter panel. -->
    <q-btn
      flat
      dense
      round
      icon="tune"
      size="sm"
      id="btn_tune_filters"
      class="qs-toolbar__btn"
      data-test="qs-toolbar-tune"
    >
      <q-tooltip>{{ $t('filters') }}</q-tooltip>
      <q-menu
        style="width: 400px; min-height: 250px"
        anchor="bottom right"
        self="top right"
        @show="onFilterShow"
        @hide="onFilterHide"
        id="tune_filter_menu"
      >
        <div class="q-pa-md">
          <div class="row q-my-sm items-center capitalize">
            <span>{{ $t('status') }}</span>
            <q-space />
            <StatusFilter />
          </div>
          <div class="row q-my-sm items-center capitalize">
            <span>{{ $t('assigned_to') }}</span>
            <q-space />
            <UserFilter :include-groups="includeGroups" />
          </div>
          <div class="row q-my-sm items-center capitalize">
            <span>{{ $t('restart_required') }}</span>
            <q-space />
            <RestartFilter />
          </div>
          <div class="row justify-end q-mt-md">
            <q-btn
              flat
              color="negative"
              class="q-mr-sm text-uppercase"
              :label="$t('clear_filters')"
              id="clear_filters"
              data-test="qs-toolbar-clear-filters"
              @click="onResetFilters"
            />
            <q-btn
              color="primary"
              unelevated
              class="text-uppercase"
              :label="$t('apply')"
              data-test="qs-toolbar-apply-filters"
              @click="onApplyFilters"
              v-close-popup
            />
          </div>
        </div>
      </q-menu>
    </q-btn>

    <!-- Standard (chip) ↔ Raw (query string) view toggle. A single
         compact icon button (DOCB-13123) that sits with the other
         toolbar actions, just before the help button, so it reads as
         part of the search rather than a dashboard-level control. The
         icon shows the view you'll switch TO: `code` for raw, the
         stacked-cards `view_agenda` for the structured chip view.
         Disabled when the raw query has structural errors — we can't
         round-trip an invalid query through the chip builder without
         silently dropping content. -->
    <div class="qs-toolbar__view-toggle-wrap">
      <q-btn
        flat
        dense
        round
        size="sm"
        :icon="showRaw ? 'view_agenda' : 'code'"
        :disable="!canLeaveRawView"
        class="qs-toolbar__btn"
        :class="{ 'qs-toolbar__btn--active': showRaw }"
        data-test="qs-view-toggle"
        @click="onSetViewMode(showRaw ? 'standard' : 'raw')"
      >
        <q-tooltip v-if="canLeaveRawView">
          {{ showRaw ? $t('search_view_standard') : $t('search_view_raw') }}
        </q-tooltip>
      </q-btn>
      <q-tooltip
        v-if="!canLeaveRawView"
        anchor="bottom middle"
        self="top middle"
      >
        {{ $t('search_toggle_blocked_syntax') }}
      </q-tooltip>
    </div>

    <!-- Syntax help — opens the Fields & Syntax reference dialog. -->
    <q-btn
      flat
      dense
      round
      icon="help_outline"
      size="sm"
      class="qs-toolbar__btn"
      data-test="qs-toolbar-help"
      @click="onShowHelp"
    >
      <q-tooltip>{{ $t('search_help_tooltip') }}</q-tooltip>
    </q-btn>

    <q-circular-progress
      v-if="indexSyncPercent !== null"
      :value="indexSyncPercent"
      :min="0"
      :max="100"
      size="32px"
      :thickness="0.16"
      class="qs-toolbar__sync-ring"
      :style="{ '--qs-ring-color': syncRingColor }"
      show-value
    >
      <span class="qs-toolbar__sync-ring-label">{{ indexSyncPercent }}%</span>
      <q-tooltip anchor="bottom middle" self="top middle" max-width="320px">
        <div class="qs-toolbar__sync-tooltip">
          <div class="qs-toolbar__sync-tooltip-title">
            {{
              $t('fulltext_ring_header', { percent: String(indexSyncPercent) })
            }}
          </div>
          <div v-if="indexSyncDocumentsLine">{{ indexSyncDocumentsLine }}</div>
          <div v-if="indexSyncVectorLine">{{ indexSyncVectorLine }}</div>
        </div>
      </q-tooltip>
    </q-circular-progress>
  </div>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { group_permission_activated } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import StatusFilter from 'src/pages/Dashboard/Filters/status-filter.vue';
import UserFilter from 'src/pages/Dashboard/advancedSettings/user-filter.vue';
import RestartFilter from './restart-filter.vue';

export default defineComponent({
  name: 'QuickSearchToolbar',
  components: { StatusFilter, UserFilter, RestartFilter },
  props: {
    showRaw: { type: Boolean, default: false },
    rawQueryText: { type: String, default: '' },
    // View-mode toggle (DOCB-13123). canLeaveRawView gates the switch
    // when the raw query has structural errors; onSetViewMode applies it.
    canLeaveRawView: { type: Boolean, default: true },
    onSetViewMode: {
      type: Function as PropType<(value: string) => void>,
      required: true,
    },
    userSettings: {
      type: Object as PropType<Record<string, any>>,
      required: true,
    },
    onCopyRawQuery: { type: Function as PropType<() => void>, required: true },
    onShowHelp: { type: Function as PropType<() => void>, required: true },
    onFilterShow: { type: Function as PropType<() => void>, required: true },
    onFilterHide: { type: Function as PropType<() => void>, required: true },
    onResetFilters: { type: Function as PropType<() => void>, required: true },
    onApplyFilters: { type: Function as PropType<() => void>, required: true },
    // 0–100 integer percentage of documents in the slim documents index.
    // null = Fulltext disabled OR stats not loaded yet — badge is hidden.
    // Source: documentIndexStats.total_indexed / in_database from
    // quick-search.vue's SSE-fed index-sync ref (same data the
    // /settings/fulltext page renders).
    indexSyncPercent: {
      type: Number as PropType<number | null>,
      default: null,
    },
    indexSyncDocumentsLine: {
      type: String as PropType<string | null>,
      default: null,
    },
    indexSyncVectorLine: {
      type: String as PropType<string | null>,
      default: null,
    },
  },
  computed: {
    includeGroups(): boolean {
      return toBoolPreference(this.userSettings[group_permission_activated]);
    },
    syncRingColor(): string {
      const p = Math.max(0, Math.min(100, this.indexSyncPercent ?? 0));
      const hue = p * 1.2;
      return `hsl(${hue}, 70%, 42%)`;
    },
  },
});
</script>

