import {
  parseSearchQuery,
  FIELD_CATALOG,
  FieldMeta,
  SearchOperator,
  SUPPORTED_FIELDS,
  expandFieldPrefixes,
  expandStatusShortcuts,
  expandCurrencySuffixes,
  expandOverdueShortcut,
  expandBareDateKeywords,
  expandPeriodShortcuts,
  expandInList,
  expandNegationPrefix,
  expandNotBetween,
  expandBetween,
  expandOperatorAliases,
  normaliseSmartQuotes,
  extractGroupBy,
} from './searchQueryParser';
import { CONNECTOR_WORDS, canonicalConnectorWord } from './searchConnectors';

/** Apply the parser's pre-tokeniser shortcut expansions so typed text
 *  like `$50000+`, `@User`, `status in (open, error)`, `overdue`,
 *  `total_amount between 1000 and 5000` becomes canonical `field<op>value`
 *  form before shouldCommit's predicate regex runs. Without this pass the
 *  chip editor would refuse to commit any shortcut syntax, and the query
 *  would only materialise when the user toggled to raw view. */
function preprocessShortcuts(text: string): string {
  if (!text) return text;
  let s = normaliseSmartQuotes(text);
  s = expandFieldPrefixes(s);        // @/#/$
  s = expandOperatorAliases(s);       // gt/gte/lt/lte/eq/ne
  s = expandStatusShortcuts(s);       // status=open → status=ready_for_validation
  s = expandCurrencySuffixes(s);      // 5k → 5000
  s = expandOverdueShortcut(s);       // overdue → invoice_due_date<today() AND ...
  s = expandBareDateKeywords(s);      // today/yesterday/tomorrow → today()...
  s = expandPeriodShortcuts(s);       // this_week → >= AND <=
  s = expandInList(s);                // status in (a, b) → status=a OR status=b
  s = expandNegationPrefix(s);        // not field=X → field!=X
  s = expandNotBetween(s);
  s = expandBetween(s);               // between → >= AND <=
  return s;
}

export type Token =
  | {
      kind: 'chip';
      field: string;
      op: SearchOperator;
      value: string;
      connector?: 'AND' | 'OR';
    }
  | { kind: 'text'; content: string };

export interface ShouldCommitResult {
  commit: boolean;
  chip?: { field: string; op: SearchOperator; value: string; quoted?: boolean };
  remainder?: string;
}

const PREDICATE_RE = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)(.*)$/;

/**
 * Strip ONE balanced outer paren layer iff the entire trimmed string
 * is wrapped in a single group AND that group is a pure top-level
 * AND chain.  Used by the chip-commit path to unwrap the
 * precedence-preserving parens that `expandBetween` emits
 * (Bug-2026-05-25 #46), since chip mode represents an AND-conjunction
 * as separate chips.
 *
 * Bug-2026-05-25 #47 (Codex v9 [high]): NEVER unwrap a group that
 * contains a top-level `OR` — e.g. `expandNotBetween` emits
 * `(field<A OR field>B)`.  Flattening that into separate chips would
 * drop the grouping, so `status=active AND imported_on not between
 * A and B` → `status=active AND imported_on<A OR imported_on>B` and
 * the OR escapes the conjunction (the exact precedence bug #40
 * fixed).  When an OR group is detected we leave the parens intact;
 * the anchored chip splitter then declines to commit and the
 * expression stays as raw query text — which serialises to the
 * backend WITH its grouping preserved.
 */
function unwrapOuterGroup(s: string): string {
  const t = s.trim();
  if (!t.startsWith('(') || !t.endsWith(')')) return s;
  // Confirm the opening `(` balances with the FINAL `)` — i.e. the
  // whole string is one group, not `(a) AND (b)`.
  let depth = 0;
  for (let i = 0; i < t.length; i++) {
    if (t[i] === '(') depth++;
    else if (t[i] === ')') {
      depth--;
      if (depth === 0 && i < t.length - 1) return s;
    }
  }
  if (depth !== 0) return s;
  const inner = t.slice(1, -1).trim();
  // #47: only flatten pure-AND groups.  Scan `inner` for a top-level
  // ` OR ` connector (depth 0 within `inner`); if present, keep the
  // parens so the chip splitter declines and the grouping survives
  // as raw query text.
  let innerDepth = 0;
  for (let i = 0; i < inner.length; i++) {
    if (inner[i] === '(') innerDepth++;
    else if (inner[i] === ')') innerDepth--;
    else if (
      innerDepth === 0 &&
      (inner[i] === 'O' || inner[i] === 'o') &&
      /^\sor\s/i.test(inner.slice(i - 1, i + 3))
    ) {
      return s; // top-level OR → do not flatten
    }
  }
  return inner;
}

function metaOf(field: string): FieldMeta | undefined {
  return FIELD_CATALOG.find((f) => f.name === field);
}

function isSingleToken(field: string): boolean {
  const meta = metaOf(field);
  return (
    meta?.valueType === 'numeric' ||
    meta?.valueType === 'date' ||
    meta?.valueType === 'enum' ||
    meta?.valueType === 'uuid'
  );
}

// A "trigger" is either a keyboard key we just saw (' ', 'Enter', 'Tab')
// or 'auto' when an auto-condition fires (new field prefix detected, closing quote).
//
// `extraFields` is the set of custom doc-type field names hydrated at
// runtime from `useDocTypeFieldsStore` — without it, predicates like
// `purchase_order_supplier_id=Test` would never commit because they
// aren't in the hardcoded SUPPORTED_FIELDS list. Optional so unit
// tests can keep the pure form.
export function shouldCommit(
  text: string,
  trigger: string | null,
  extraFields: ReadonlySet<string> = new Set(),
): ShouldCommitResult {
  const isSupported = (name: string): boolean => {
    const lower = name.toLowerCase();
    return SUPPORTED_FIELDS.has(lower) || extraFields.has(lower);
  };
  // Group-by directive: detect BEFORE shortcut preprocessing because the
  // word "by" is fragile — operator aliases, in-list, etc. could rewrite
  // it. The directive lives in its own chip (field="group_by", op=":",
  // value=<canonical field> [+ "|day|week|month"] for bucketed dates).
  // Only Enter/Tab commit — space stays a typing key so the autocomplete
  // dropdown can finish presenting field options as the user types
  // `group by ven…`.
  if (trigger === 'Enter' || trigger === 'Tab') {
    const gb = extractGroupBy(text);
    // `extractGroupBy` only matches when the directive is at the END of
    // the input AND followed by either nothing or just whitespace. The
    // stripped portion is whatever predicates / keyword come BEFORE it
    // — those should have already been committed as their own chips, so
    // here we only commit the directive when the rest is empty.
    if (gb.groupByOverride && !gb.stripped.trim()) {
      const { field, bucket } = gb.groupByOverride;
      const value = bucket ? `${field}|${bucket}` : field;
      return {
        commit: true,
        chip: {
          field: 'group_by',
          op: ':' as SearchOperator,
          value,
        },
      };
    }
  }

  // Shortcut-aware preprocess. `$50000+` → `total_amount>=50000`, `@User`
  // → `assigned_to="User"`, `status in (a, b)` → `status=a OR status=b`,
  // etc. The tryCommit caller handles multi-predicate output by feeding
  // the remainder back as editor content for the next Enter.
  //
  // Bug-2026-05-25 #46 (Codex v8 [medium]): `expandBetween`/
  // `expandNotBetween` now paren-WRAP their multi-predicate output
  // (`(a>=1 AND a<=2)`) to preserve backend boolean precedence.  In
  // chip mode each predicate becomes a SEPARATE chip and the chip
  // list itself is the conjunction, so the grouping parens are
  // redundant here — strip one balanced outer layer so the
  // multi-predicate splitter below (anchored at `field<op>`) still
  // matches.  Only unwraps when the WHOLE string is one balanced
  // group, so a legitimate `(a OR b) AND c` isn't mis-unwrapped.
  const expanded = unwrapOuterGroup(preprocessShortcuts(text));

  // Closing quote scan (trigger irrelevant).
  const quoteRe = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:)"([^"]*)"\s*$/;
  const quoteMatch = quoteRe.exec(expanded);
  if (quoteMatch) {
    const chip: ShouldCommitResult['chip'] = {
      field: quoteMatch[1],
      op: quoteMatch[2] as SearchOperator,
      value: quoteMatch[3],
    };
    if (quoteRe.test(text.trim())) chip.quoted = true;
    return { commit: true, chip };
  }

  // Multi-predicate: shortcut expansions like `in (...)`, `between`, and
  // `overdue` emit `pred1 AND|OR pred2 …`. Commit pred1 now and hand the
  // rest back as remainder — the leading connector will be picked up by
  // tryCommit on the next keypress and stamped onto the next chip.
  // Accept a connector in any supported language (AND/OR, UND/ODER,
  // ET/OU …) so a space-triggered split commits the first chip the same
  // way English does — DOCB-13123.
  const CONN_SPLIT_RE = new RegExp(
    `^\\s*([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)("[^"]*"|'[^']*'|\\S+)\\s+(${CONNECTOR_WORDS.join(
      '|',
    )})\\s+(.+)$`,
    'i',
  );
  const connMatch = CONN_SPLIT_RE.exec(expanded);
  if (connMatch) {
    const [, field, op, value, , rest] = connMatch;
    if (isSupported(field)) {
      const connector =
        canonicalConnectorWord(connMatch[4]) ?? connMatch[4].toUpperCase();
      return {
        commit: true,
        chip: {
          field,
          op: op as SearchOperator,
          value: unquoteIfNeeded(value),
        },
        remainder: `${connector} ${rest}`,
      };
    }
  }

  // Auto-trigger: new field prefix appears mid-string (no connector).
  const autoMatch = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)(.*?)\s+([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)(.*)$/.exec(
    expanded,
  );
  if (autoMatch) {
    const [, field, op, value, nextField] = autoMatch;
    if (isSupported(field) && isSupported(nextField)) {
      return {
        commit: true,
        chip: {
          field,
          op: op as SearchOperator,
          value: value.trim(),
        },
        remainder: expanded.slice(expanded.indexOf(nextField)),
      };
    }
  }

  const m = PREDICATE_RE.exec(expanded);
  if (!m) return { commit: false };
  const [, field, op, rawValue] = m;
  const value = rawValue.trim();
  if (!value) return { commit: false };
  if (!isSupported(field)) return { commit: false };

  // Trigger logic
  if (trigger === 'Enter' || trigger === 'Tab') {
    return { commit: true, chip: { field, op: op as SearchOperator, value: unquoteIfNeeded(value) } };
  }
  if (trigger === ' ' && isSingleToken(field)) {
    return { commit: true, chip: { field, op: op as SearchOperator, value: unquoteIfNeeded(value) } };
  }
  return { commit: false };
}

function unquoteIfNeeded(v: string): string {
  if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) {
    return v.slice(1, -1);
  }
  return v;
}

export function queryStringToTokens(raw: string): Token[] {
  if (!raw.trim()) return [];
  const parsed = parseSearchQuery(raw);
  const tokens: Token[] = parsed.predicates.map((p) => ({
    kind: 'chip',
    field: p.field,
    op: p.operator,
    value: p.value,
    connector: p.connector,
  }));
  // Directive: rehydrate the group-by override as a directive chip so a
  // page reload (which seeds the editor from the stored raw_query
  // string) restores the same chip the user originally committed.
  if (parsed.groupByOverride) {
    const { field, bucket } = parsed.groupByOverride;
    tokens.push({
      kind: 'chip',
      field: 'group_by',
      op: ':' as SearchOperator,
      value: bucket ? `${field}|${bucket}` : field,
    });
  }
  if (parsed.keyword) {
    tokens.push({ kind: 'text', content: parsed.keyword });
  }
  return tokens;
}

export function tokensToQueryString(tokens: Token[]): string {
  return tokens
    .map((t, i) => {
      if (t.kind === 'text') return t.content;
      const prefix = i === 0 ? '' : `${t.connector ?? 'AND'} `;
      // Directive chip is serialized back to natural-language form so
      // parseSearchQuery's extractGroupBy can re-extract it on the next
      // round-trip without ever leaking `group_by:supplier_name` into
      // the predicate stream (which the backend would reject as an
      // unknown field).
      if (t.field === 'group_by') {
        const [field, bucket] = t.value.split('|');
        return `${prefix}group by ${field}${bucket ? ' ' + bucket : ''}`;
      }
      return `${prefix}${t.field}${t.op}${t.value}`;
    })
    .join(' ')
    .trim();
}
