/**
 * Shared autocomplete state + behaviour for the DocBits quick-search
 * editors (chip view and raw-text view). Both editors want the same
 * dropdown experience — field suggestions, operator suggestions, value
 * suggestions, AND/OR connectors, ghost preview, arrow-key nav — and
 * keeping two copies of that logic in sync is a maintenance landmine.
 *
 * What the composable OWNS:
 *   - Reactive AC state: acOpen / acMode / acField / acQuery / highlighted
 *   - The currentList + connectorSuggestions + ghostText computeds
 *   - updateFromContent(text): the regex-based mode router
 *   - onPick(payload): text mutations for field / operator / connector
 *   - handleKeydown(key): arrow / Enter / Tab / Escape routing
 *
 * What it does NOT know about:
 *   - Chip atoms. When the host editor has chips (the chip view), value
 *     picks need to create an atomic chip node instead of inserting
 *     plain text. The host passes an `onValuePick` callback that fires
 *     in that case; the composable only runs the default text-insert
 *     path when no override is supplied (the raw-text editor).
 *   - Predicate commit (shouldCommit / normaliseValue). Chip-specific,
 *     stays in QuickSearchBox.vue.
 *   - Paren nodes. The composable walks text-before-caret ignoring
 *     non-text nodes; chips + parens both act as boundaries.
 *
 * Host integration checklist:
 *   1. Call useQuickSearchAutocomplete({ editor, ... }) in setup().
 *   2. In the editor's onUpdate, call updateFromContent(textBeforeCaret).
 *   3. Render <FieldAutocomplete> with the returned state + onPick.
 *   4. Wire handleKeydown into the editor's keyboard shortcuts.
 */

import { ref, computed, watch, Ref, ComputedRef } from 'vue';
import type { Editor } from '@tiptap/vue-3';
import {
  FIELD_CATALOG,
  SMART_FILTERS,
  SUPPORTED_FIELDS,
  OPERATOR_HINTS,
  FieldMeta,
} from '../searchQueryParser';
import {
  useFieldValueSource,
  fieldHasValueSource,
} from '../useFieldValueSource';
import { fieldAllowsAutoQuote } from './AutoQuoteOnEquals';
import { connectorMatchesQuery, CONNECTOR_WORDS } from '../searchConnectors';
import {
  fieldDisplayLabel,
  fieldMatchesQuery,
  normaliseOperatorList,
  type TranslateFn,
} from '../fieldDisplay';

export type AcMode = 'field' | 'operator' | 'value';

export interface AcPickArgs {
  payload: { kind: 'value'; value: string; label?: string };
  /** Full text before caret at the moment of the pick. */
  typedText: string;
  /** Current caret position in the document. */
  from: number;
  /** Start of text-before-caret (from - typedText.length). */
  textStart: number;
  /** Leading AND/OR the user typed before the predicate, if any. */
  explicitConnector: 'AND' | 'OR' | undefined;
  /** Field the value belongs to (acField at pick time). */
  field: string;
  /** Operator inferred from typedText (`#` → `:`, everything else `=`
   *  unless the typed text already contained `field op`). */
  op: string;
  /**
   * Category of the field the user PICKED FROM the autocomplete
   * (which dropdown section: STANDARD / EXTENDED / FULLTEXT / VECTOR).
   * Drives chip color downstream — `supplier_name` may legitimately
   * appear in BOTH the EXTENDED and the FULLTEXT section, and the
   * chip must reflect which section the user actually clicked, NOT
   * the catalog's default category for that field name. Undefined
   * when the field was typed (not picked) — the host then falls back
   * to the catalog default.
   */
  category?: 'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai';
}

export function quoteValueForInsert(value: string): string {
  return /[\s"]/.test(value) ? `"${value.replace(/"/g, '\\"')}"` : value;
}

export function stripQueryQuotes(s: string): string {
  return s.replace(/^"/, '').replace(/"$/, '');
}

export interface UseAutocompleteOptions {
  editor: Ref<Editor | null>;
  isFulltextEnabled?: Ref<boolean>;
  isVectorEnabled?: Ref<boolean>;
  /**
   * Chip editor overrides this to insert an atomic chip node instead
   * of plain text. Return true if handled; return false (or omit) to
   * let the composable run its default text-insert path.
   */
  onValuePick?: (args: AcPickArgs) => boolean | void;
  /**
   * Resolves the signed-in user-id for personal Smart Filters
   * (e.g. "Assigned to me"). Optional — when omitted the filter
   * inserts the literal `me` token, which the parser then flags as
   * a no-match instead of silently filtering on the wrong user.
   */
  getUserId?: () => number | string | null;
  /**
   * Resolves the active UI locale code (e.g. "de", "en-US"). Used
   * for locale-scoped Smart Filter matchKeyword lookup so a user
   * only sees shortcuts in their own language. Optional — falls
   * back to `en` when omitted (parser unit tests).
   */
  getLocale?: () => string;
  /**
   * Optional i18n lookup for field-label search. Field picks still insert
   * canonical field names; this only lets users find fields through the
   * labels they see in their current UI language.
   */
  translate?: TranslateFn;
  /**
   * Resolves the per-tenant custom fields (already mapped to FieldMeta
   * shape). Composable stays pinia-free; the host injects the lookup.
   * Optional — when omitted only the static FIELD_CATALOG is offered.
   */
  getCustomFields?: () => FieldMeta[];
}

export interface UseAutocompleteReturn {
  acOpen: Ref<boolean>;
  acMode: Ref<AcMode>;
  acField: Ref<string>;
  /**
   * Category of the field most recently PICKED FROM the autocomplete
   * dropdown — empty string when the field was typed by hand (not
   * picked). Reset whenever the field changes. Hosts use this to
   * preserve the picked section when creating a chip, so a field
   * shown in two sections (e.g. supplier_name in both EXTENDED and
   * FULLTEXT) lands the chip's category according to the section
   * the user actually clicked.
   */
  acCategory: Ref<
    'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai' | ''
  >;
  /** Operator the user picked from the dropdown — empty string when
   *  they haven't picked yet, or have backspaced past the operator.
   *  Authoritative over text-state extraction during value picks
   *  (Bug-2026-04-28). */
  acOp: Ref<string>;
  acQuery: Ref<string>;
  highlighted: Ref<any>;
  /**
   * True once the user has explicitly arrowed (↑/↓) into the suggestion
   * list since it last refreshed. ENTER only auto-picks when this is
   * true (DRFS-534 + DOCB-12249-followup). Default highlights set by
   * the per-mode watcher leave this `false` so ENTER on `filename`
   * still falls through to fulltext-submit.
   */
  userNavigated: Ref<boolean>;
  currentList: ComputedRef<any[]>;
  connectorSuggestions: ComputedRef<string[]>;
  ghostText: ComputedRef<string>;
  /** True while the caret sits at the end of the input — gates ghost text. */
  caretAtEnd: Ref<boolean>;
  /** Sync `caretAtEnd` from the editor selection (host calls on update). */
  syncCaretAtEnd: (ed: Editor) => void;
  /**
   * True when the popover is open AND would actually render at least
   * one pickable row. Host components use this (not the raw `acOpen`)
   * to decide whether the user is mid-selection — so a popover that
   * has hidden itself due to zero matches does not suppress
   * plain-keyword searches like "TestFile" or "filename:novmatch".
   */
  acHasSuggestions: ComputedRef<boolean>;
  /** Text-before-caret walker that resets at chip / paren boundaries. */
  textBeforeCaret: (ed: Editor) => string;
  /** Refresh AC state from the current text-before-caret string. */
  updateFromContent: (content: string) => void;
  /** Handle an AC dropdown pick. */
  onPick: (payload: any) => void;
  /** Handle an editor keyboard shortcut that should route through AC. */
  handleKeydown: (key: string) => boolean;
  /** Move the highlight up or down the current list. */
  moveHighlight: (delta: number) => void;
  /** Open the field-list popover (mode='field') with cleared field/op/query state. */
  openFieldList: () => void;
}

export function useQuickSearchAutocomplete(
  opts: UseAutocompleteOptions,
): UseAutocompleteReturn {
  const { editor, onValuePick } = opts;
  // Non-reactive defaults when the host doesn't pass flags (raw editor).
  const isFulltextEnabled = opts.isFulltextEnabled ?? ref(true);
  const isVectorEnabled = opts.isVectorEnabled ?? ref(true);

  const acOpen = ref(false);
  const acMode = ref<AcMode>('field');
  const acField = ref('');
  // Source-section memory for the last field-pick. The field-pick
  // handler below sets this to f.category when a FieldMeta is clicked.
  // Stays sticky across the operator-pick step and is consumed by the
  // value-pick handler so the resulting chip carries the category from
  // the SECTION the user picked, not the catalog default for the field
  // name (which would mis-color supplier_name when picked from FULLTEXT
  // because the static catalog says it's EXTENDED).
  const acCategory = ref<
    'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai' | ''
  >('');
  // Bug-2026-04-28: stash the operator the user explicitly picked from
  // the dropdown. The legacy value-pick path re-extracted the op via
  // regex over `textBeforeCaret`, which races with TipTap's reactive
  // updates: a fast operator → value click could see a `remaining`
  // string with no operator, fall through to the `=` default, and the
  // chip would render `=` even though the user picked `>=`. Stashing
  // the picked op in its own ref makes the pipeline source-of-truth-
  // free of TipTap text state for the operator dimension.
  const acOp = ref('');
  const acQuery = ref('');
  // Active directive context for the dropdown — currently only
  // 'group_by'. When set, a field-pick wraps the field name in the
  // directive's prefix ("group by <field>") instead of inserting it
  // bare, so the chip-commit pass on Enter/Tab can lift it into a
  // directive chip rather than treating it as a typo'd predicate.
  const acDirective = ref<'group_by' | null>(null);
  const highlighted = ref<any>(null);
  // True when textBeforeCaret stripped a text-level boundary (committed
  // predicate, AND/OR, or paren). Used by connectorSuggestions so the
  // raw editor (no atomic chip nodes) can still surface AND/OR picks
  // once the user has committed at least one predicate.
  const hasCommittedBefore = ref(false);

  // Text-before-caret walker. Resets at each chip / paren / connector
  // boundary — those are atomic predicate markers, and what the user is
  // typing "now" is whatever follows the most recent one.
  //
  // Raw editor has no atomic nodes, so we additionally split on
  // text-level boundaries:
  //   • `<field><op><value>\s` — a committed predicate followed by
  //     whitespace means the value is closed and the next thing the
  //     user is typing is either a connector or a new field.
  //   • `AND`/`OR` as whole words, optionally followed by whitespace.
  //   • `(` / `)` parens, optionally followed by whitespace.
  // Only strip when there's content AFTER the boundary — otherwise
  // typing bare "AND" / "OR" would collapse the query and hide the
  // connector pick for the user who's mid-typing.
  //
  // `hasCommittedBefore` is updated as a side-effect so the connector
  // suggestions can gate themselves without re-scanning the doc.
  const textBeforeCaret = (ed: Editor): string => {
    const { selection, doc } = ed.state;
    const { from } = selection;
    let text = '';
    doc.nodesBetween(0, from, (node) => {
      if (node.type.name === 'text') text += node.text ?? '';
      else if (
        node.type.name === 'chip' ||
        node.type.name === 'paren' ||
        node.type.name === 'connector'
      )
        text = '';
    });
    const boundaryRe = new RegExp(
      `[a-zA-Z_][a-zA-Z0-9_]*(?:>=|<=|!=|=|:|>|<)\\S+\\s+|\\b(?:${CONNECTOR_WORDS.join(
        '|',
      )})\\b\\s*|[()]\\s*`,
      'gi',
    );
    let lastIdx = 0;
    let m: RegExpExecArray | null;
    while ((m = boundaryRe.exec(text)) !== null) {
      lastIdx = m.index + m[0].length;
    }
    const stripped = lastIdx > 0 && lastIdx < text.length;
    if (stripped) text = text.slice(lastIdx);

    // hasCommittedBefore: "is there anything the user has already put
    // into the query that an AND/OR could logically attach to?" Scan the
    // full doc (not just pre-caret) so seeded content with chips still
    // counts even when the caret is at position 0 after mount.
    let hasAtomic = false;
    doc.descendants((node) => {
      if (
        node.type.name === 'chip' ||
        node.type.name === 'paren' ||
        node.type.name === 'connector'
      ) {
        hasAtomic = true;
        return false;
      }
    });
    hasCommittedBefore.value = hasAtomic || stripped;

    return text;
  };

  // ── Suggestions ────────────────────────────────────────────────────
  // Connector picks (AND / OR) are meaningful whenever the query already
  // contains committed content. Two signals feed this:
  //   (a) hasCommittedBefore — set by textBeforeCaret() when the raw
  //       editor strips a text-level predicate / AND / OR / paren
  //       boundary, OR when it sees an atomic chip/paren/connector node.
  //   (b) a live scan of the editor's doc for atomic nodes — belt-and-
  //       braces so seeded content (initialQuery) registers even if the
  //       ref hasn't been refreshed by a textBeforeCaret call yet.
  // Either path is enough; whichever fires, surface AND/OR.
  const connectorSuggestions = computed<string[]>(() => {
    if (acMode.value !== 'field') return [];
    let hasCommitted = hasCommittedBefore.value;
    if (!hasCommitted && editor.value) {
      editor.value.state.doc.descendants((node) => {
        if (
          node.type.name === 'chip' ||
          node.type.name === 'paren' ||
          node.type.name === 'connector'
        ) {
          hasCommitted = true;
          return false;
        }
      });
    }
    if (!hasCommitted) return [];
    const q = (acQuery.value ?? '').toLowerCase();
    const out: string[] = [];
    if (connectorMatchesQuery('AND', q)) out.push('AND');
    if (connectorMatchesQuery('OR', q)) out.push('OR');
    return out;
  });

  const currentList = computed<any[]>(() => {
    if (acMode.value === 'field') {
      const q = (acQuery.value ?? '').toLowerCase();
      const connectors = connectorSuggestions.value.map((v) => ({
        kind: 'connector',
        value: v,
      }));
      // Smart Filters surface above field rows because they're the
      // task the accountant came to do, not the data dimension. Match
      // against the user's CURRENT locale matchKeywords only — a
      // German user shouldn't see Italian shortcuts. Locale lookup
      // is host-injected (see opts.getLocale) to keep the composable
      // pinia/tolgee-free for unit tests.
      const rawLocale = String(opts.getLocale?.() ?? '').toLowerCase();
      const locale = (rawLocale.split('-')[0] || 'en') as
        | 'en'
        | 'de'
        | 'es'
        | 'fr'
        | 'it';
      const smartFilters = SMART_FILTERS.filter((sf) => {
        if (!q) return true;
        if (sf.name.toLowerCase().includes(q)) return true;
        const keywords = sf.matchKeywords[locale] ?? sf.matchKeywords.en ?? [];
        return keywords.some((kw) => kw.toLowerCase().includes(q));
      }).map((sf) => ({
        kind: 'smart-filter',
        smartFilter: sf,
        value: sf.name,
      }));
      const customFields = isFulltextEnabled.value
        ? (opts.getCustomFields?.() ?? [])
        : [];
      const fields = [...FIELD_CATALOG, ...customFields].filter(
        (f) =>
          fieldMatchesQuery(f, q, opts.translate) &&
          (isFulltextEnabled.value || f.category !== 'fulltext') &&
          (isVectorEnabled.value || f.category !== 'vector'),
      );
      // Directive entry — surfaces "Group by…" while the user is still
      // mid-typing (`g`, `gr`, `gro`, `group`, plus the German
      // `gruppieren` and the legacy DocBits keyword "vendor"). Picking
      // this row inserts `group by ` into the editor, which then flips
      // the dropdown into directive mode (acDirective='group_by') and
      // re-shows the field list. Hidden once the user is already in
      // directive mode (acDirective !== null) so it doesn't duplicate.
      const directiveEntries: any[] = [];
      if (acDirective.value === null) {
        const directiveMatchKeywords = [
          'group',
          'group by',
          'gruppieren',
          'gruppe',
        ];
        const matchesDirective =
          !q ||
          directiveMatchKeywords.some(
            (kw) =>
              kw.toLowerCase().startsWith(q) || kw.toLowerCase().includes(q),
          );
        if (matchesDirective) {
          directiveEntries.push({
            kind: 'directive-prefix',
            directive: 'group_by',
            value: 'group_by',
          });
        }
      }
      return [...connectors, ...smartFilters, ...directiveEntries, ...fields];
    }
    if (acMode.value === 'operator') {
      const meta =
        FIELD_CATALOG.find((f) => f.name === acField.value) ??
        (opts.getCustomFields?.() ?? []).find((f) => f.name === acField.value);
      // DRFS-534: filter the operator list by what the user typed after
      // the field name. If nothing matches, currentList is empty and
      // `acHasSuggestions` flips false — the popover closes instead of
      // dangling with stale options.
      const q = (acQuery.value ?? '').toLowerCase();
      const operators = (meta ? normaliseOperatorList(meta) : [])
        .filter((op) => {
          if (!q) return true;
          if (op.toLowerCase().includes(q)) return true;
          const hintKey = OPERATOR_HINTS[op];
          if (!hintKey) return false;
          const hintLabel =
            opts.translate?.(hintKey)?.toLowerCase?.() ?? hintKey.toLowerCase();
          return hintLabel.includes(q);
        })
        .map((op) => ({
          kind: 'operator',
          value: op,
          hint: OPERATOR_HINTS[op],
        }));
      // Bug-2026-04-28: include presence-preset rows in the navigable
      // list so ↑/↓ keys can reach them. The dropdown template already
      // renders the presence section for fields with `supportsPresence`,
      // but `currentList` previously stopped at the operator array —
      // arrow keys could only ever land on `>=`/`<=` and never on
      // `is not null`/`is null`. Append the presets after the operators
      // so the keyboard order matches the visual order in the template.
      // DRFS-534: presence presets follow the same filter — if the
      // typed text doesn't appear in `!=""` / `=""`, hide them so an
      // unrelated query doesn't keep the popover open.
      const presets = meta?.supportsPresence
        ? [
            { kind: 'preset', value: '!=""' },
            { kind: 'preset', value: '=""' },
          ].filter((p) => !q || p.value.toLowerCase().includes(q))
        : [];
      return [...operators, ...presets];
    }
    const all = useFieldValueSource(acField.value).options.value ?? [];
    const q = (acQuery.value ?? '').toLowerCase().trim();
    // String()-coerce on both sides — `value` for user fields is a
    // numeric user id (see prepareUsersDropdown → `value: userObj.id`),
    // and `.toLowerCase()` on a number throws. When the filter threw,
    // the whole computed bailed and the dropdown kept rendering the
    // unfiltered list — which is the bug where `@amier` showed every
    // user instead of just Amier.
    const filtered = q
      ? all.filter(
          (o) =>
            String(o.value ?? '')
              .toLowerCase()
              .includes(q) ||
            String(o.label ?? '')
              .toLowerCase()
              .includes(q),
        )
      : all;
    return filtered.map((o) => ({
      kind: 'value',
      value: o.value,
      label: o.label,
      isGroup: o.isGroup,
    }));
  });

  const isKnownField = (fieldLower: string) =>
    SUPPORTED_FIELDS.has(fieldLower) ||
    FIELD_CATALOG.some((f) => f.name.toLowerCase() === fieldLower) ||
    (opts.getCustomFields?.() ?? []).some(
      (f) => f.name.toLowerCase() === fieldLower,
    );

  // Stable key — FieldMeta has .name; operator/value/connector have .value.
  const keyOf = (x: any): string | null => x?.name ?? x?.value ?? null;

  // DRFS-581 / DOCB-12249-followup: tracks whether the user has
  // explicitly arrowed into the suggestion list since it last refreshed.
  //   • Default highlights (set by the watch below) leave this `false`.
  //   • ArrowDown / ArrowUp into the list flip it `true`.
  //
  // ENTER consults this flag and only auto-picks when `true` — preserves
  // the DRFS-534 guard: typing `file` + ENTER must NOT silently swap the
  // free-text query for the topmost fuzzy match; it must fall through to
  // tryCommit/emitParsed so the host runs a fulltext keyword search.
  //
  // TAB ignores this flag — it is the explicit "complete with the
  // highlighted suggestion" gesture and picks both default and
  // user-navigated highlights.
  const userNavigated = ref(false);

  // DOCB-13124: the inline ghost completion + `↹ Tab` badge render at the
  // caret, so they only make sense when the caret sits at the very end of
  // the input. When the user moves the caret into the middle to edit, the
  // suffix would render in the wrong place — suppress it. The host syncs
  // this from the editor's selection on every update/selection/focus.
  const caretAtEnd = ref(true);
  const syncCaretAtEnd = (ed: Editor): void => {
    try {
      const { selection } = ed.state;
      caretAtEnd.value =
        selection.empty && selection.$head.pos === selection.$head.end();
    } catch {
      caretAtEnd.value = true;
    }
  };

  // Compute the ghost-text suffix that a field-row would contribute
  // for the current `acQuery`. Used by both the default-highlight
  // watcher (to pick the row whose visible label/name extends the
  // typed prefix) and by the `ghostText` computed (to render that
  // suffix as the Google-style inline cue).
  //
  // Preference: translated USER-VISIBLE label first (so a German user
  // typing `Doku` sees `mentname` from `Dokumentname`), canonical
  // `field.name` second (English `file` → `name`). Returns the empty
  // string when neither extends the typed prefix.
  const fieldGhostSuffix = (field: FieldMeta, query: string): string => {
    if (!query) return '';
    const qLower = query.toLowerCase();
    const tx = opts.translate;
    if (tx) {
      try {
        const label = fieldDisplayLabel(field, tx);
        if (label && label.toLowerCase().startsWith(qLower)) {
          return label.slice(query.length);
        }
      } catch {
        /* translator not ready — fall through to canonical name */
      }
    }
    if (field.name.toLowerCase().startsWith(qLower)) {
      return field.name.slice(query.length);
    }
    return '';
  };

  // Find the first field-row whose visible label or canonical name
  // extends `query`. Excludes connector / smart-filter / directive-
  // prefix rows because TAB-completing them would surprise the user
  // (their displayed text doesn't "extend" what was typed).
  const findFieldPrefixMatch = (list: any[], query: string): any => {
    if (!query) return null;
    return (
      list.find((x: any) => {
        if (typeof x?.name !== 'string') return false;
        if (x?.kind === 'connector') return false;
        if (x?.kind === 'smart-filter') return false;
        if (x?.kind === 'directive-prefix') return false;
        return fieldGhostSuffix(x as FieldMeta, query) !== '';
      }) ?? null
    );
  };

  watch(
    currentList,
    (list) => {
      // Preserve an explicit user navigation across list refreshes —
      // when the user arrowed in and that row is still in the new list,
      // keep it. Without `userNavigated`, the default-recompute below
      // would steal back the focus on every keystroke.
      //
      // Bug spotted in Codex review (HIGH): the prior `stillValid` path
      // returned early on EVERY refresh whose `keyOf` survived, even
      // when the typed prefix had grown (`D` → `Dok`) and a different
      // field would now be the better prefix-match. Result: an early
      // fuzzy-match (e.g. `doc_type` on `D`) sticks around as the
      // highlight through `Doku` instead of switching to `filename`
      // (`Dokumentname`). Restricting the preserve-shortcut to the
      // user-navigated case fixes this; for the default path we always
      // recompute against the fresh query.
      if (userNavigated.value) {
        const current = keyOf(highlighted.value);
        const stillValid = list.some((x: any) => keyOf(x) === current);
        if (stillValid) return;
        // User-navigated highlight fell out of the list — fall through
        // to default-recompute so the user isn't left with no highlight.
      }

      // Per-mode default highlight. Surfaces TAB-completion + visual
      // hint, while `userNavigated` stays `false` so the DRFS-534 ENTER
      // guard remains intact — only TAB picks the default; ENTER still
      // needs explicit ↓ navigation before it picks.
      let next: any = null;
      if (acMode.value === 'field') {
        // Prefer label-prefix (German `Doku` → `Dokumentname` / filename)
        // and fall back to canonical name (`fil` → `filename`). The
        // helper resolves both via `fieldGhostSuffix`, so the watcher
        // and the `ghostText` computed agree on which row qualifies.
        const q = acQuery.value ?? '';
        next = findFieldPrefixMatch(list, q);
      } else if (acMode.value === 'operator') {
        // Default to `:` (contains / "like") — Business-User-friendly
        // pick for string fields. DOCB-13124: when the field's operator
        // list has no `:` (enum fields like invoice_sub_type, date/numeric
        // fields), fall back to the first non-`between` operator so the
        // operator step still surfaces a ghost/Tab hint and Enter advances
        // into value mode. `between` is skipped as a one-press default
        // because it needs two values; it stays reachable via ↓.
        const ops = list.filter((x: any) => x?.kind === 'operator');
        next =
          ops.find((x: any) => x.value === ':') ??
          ops.find((x: any) => x.value !== 'between') ??
          ops[0] ??
          null;
      }
      // value mode: keep `null`. The original DRFS-534 concern stands —
      // a user-id list or fuzzy value match must never be silently
      // committed; users select values explicitly via ↓ + Enter / click.
      highlighted.value = next;
      userNavigated.value = false;
    },
    { immediate: true },
  );

  const moveHighlight = (delta: number) => {
    const list = currentList.value;
    if (!list.length) return;
    const current = keyOf(highlighted.value);
    let idx = list.findIndex((x: any) => keyOf(x) === current);
    if (idx < 0) idx = delta > 0 ? -1 : 0;
    const next = (idx + delta + list.length) % list.length;
    highlighted.value = list[next] ?? null;
    userNavigated.value = true;
  };

  const currentPickPayload = () => {
    const h = highlighted.value;
    if (!h) return null;
    if (acMode.value === 'field') return h;
    if (acMode.value === 'operator') {
      if (h.kind === 'preset') return { kind: 'preset', value: h.value };
      return { kind: 'operator', value: h.value };
    }
    return { kind: 'value', value: h.value, label: h.label };
  };

  const ghostText = computed<string>(() => {
    if (!acOpen.value || !highlighted.value) return '';
    // DOCB-13124: only complete at the end of the input (see `caretAtEnd`).
    if (!caretAtEnd.value) return '';
    if (acMode.value === 'field') {
      const h = highlighted.value as any;
      if (h?.kind === 'connector') return '';
      // Smart-filter rows have no useful ghost completion (the user
      // typed "über" but the inserted text is `invoice_due_date < today()`,
      // not `Überfällig`) — suppress the inline ghost so we don't mislead.
      if (h?.kind === 'smart-filter') return '';
      // Directive-prefix rows ("Group by …") also have no inline suffix
      // — the inserted text is the full `group by ` directive, not an
      // extension of the typed letter — same suppress reason as above.
      if (h?.kind === 'directive-prefix') return '';
      // Locale-aware prefix match. `fieldGhostSuffix` prefers the
      // translated user-visible label (so German `Doku` shows the
      // suffix `mentname` for `Dokumentname` / filename) and falls
      // back to the canonical field name (`fil` → `name`). The watcher
      // above selected this row via the same helper, so the visible
      // ghost text always corresponds to a row the user can TAB-pick.
      return fieldGhostSuffix(h as FieldMeta, acQuery.value ?? '');
    }
    if (acMode.value === 'operator') {
      // DOCB-13124: surface the operator step's ghost like field mode —
      // show exactly what TAB/ENTER would insert (the operator symbol),
      // so the box reads `field:` and the `↹ Tab` badge appears here too.
      // Presence-preset rows insert a full `field!=""` predicate, not a
      // simple operator suffix — suppress them like smart-filter rows.
      const h = highlighted.value as any;
      if (h?.kind !== 'operator') return '';
      const symbol = String(h.value ?? '');
      const q = (acQuery.value ?? '').toLowerCase();
      if (!q) return symbol;
      return symbol.toLowerCase().startsWith(q) ? symbol.slice(q.length) : '';
    }
    if (acMode.value === 'value') {
      const q = acQuery.value ?? '';
      if (!q) return '';
      // Codex review (MEDIUM): user value-source dropdowns ship numeric
      // ids as `value` (see prepareUsersDropdown in useFieldValueSource).
      // Calling `.toLowerCase()` on a number throws — coerce via String()
      // and prefer the human-readable `label` (e.g. user display name)
      // so the ghost surface matches what the user expects to see, not
      // the raw id. Without the coercion the entire `ghostText` computed
      // would error out and the whole AC UX would silently break for
      // user-field value mode.
      const raw =
        (highlighted.value as any).label ??
        (highlighted.value as any).value ??
        '';
      const candidate = String(raw);
      if (candidate.toLowerCase().startsWith(q.toLowerCase())) {
        return candidate.slice(q.length);
      }
      return '';
    }
    return '';
  });

  // ── Content → AC mode router ──────────────────────────────────────
  const updateFromContent = (content: string) => {
    const trimmed = content.replace(/^\s*(?:(?:AND|OR)\s+)?/i, '');
    if (!trimmed) {
      acOpen.value = false;
      // Bug-2026-04-28: empty buffer means the previous predicate is
      // gone (user backspaced or committed). Clear the stashed operator
      // so the next pick starts clean.
      acOp.value = '';
      acDirective.value = null;
      return;
    }

    // Group-by directive: typing `group `, `group by `, `group by ven…`
    // routes to field-mode with the existing field dropdown. Picking a
    // field there inserts the canonical "group by <field>" string at
    // the directive prefix's start so the chip-commit pass can lift it
    // back out as a directive chip. Stays open while the user is mid-
    // typing — only the chip-commit on Enter/Tab finalises it.
    const gbMatch = trimmed.match(
      /^group(?:\s+(?:by(?:\s+([a-zA-Z_][a-zA-Z0-9_]*)?)?)?)?\s*$/i,
    );
    if (gbMatch) {
      acDirective.value = 'group_by';
      acMode.value = 'field';
      acField.value = '';
      // The field-name fragment (or empty if user just typed "group ")
      // is what the dropdown filters on. `gbMatch[1]` is the partial
      // field after "group by"; missing → empty string filters nothing.
      acQuery.value = gbMatch[1] ?? '';
      acOp.value = '';
      acOpen.value = true;
      return;
    }
    acDirective.value = null;

    if (/^[@#$]/.test(trimmed)) {
      const prefix = trimmed[0];
      acMode.value = 'value';
      acField.value =
        prefix === '@'
          ? 'assigned_to'
          : prefix === '#'
            ? 'invoice_id'
            : 'total_amount';
      acQuery.value = trimmed.slice(1);
      acOpen.value = true;
      return;
    }

    const betweenMatch = /^([a-zA-Z_][a-zA-Z0-9_]*)\s+between\s*(.*)$/i.exec(
      trimmed,
    );
    if (betweenMatch) {
      const [, field, rest] = betweenMatch;
      const fieldLower = field.toLowerCase();
      const isSupported = isKnownField(fieldLower);
      if (isSupported) {
        acMode.value = 'value';
        acField.value = field;
        acQuery.value = rest ?? '';
        acOp.value = 'between';
        acOpen.value = true;
      } else {
        acOpen.value = false;
      }
      return;
    }

    const m = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)?(.*)$/.exec(trimmed);
    if (!m) {
      // Non-ASCII / non-field-shape input (e.g. "Über…" from a German
      // user looking for the "Überfällig" Smart Filter). The field-name
      // regex requires ASCII identifier chars, but Smart Filters match
      // on locale-aware keywords + i18n labels — so we stay in
      // field-mode with the raw query passed through and let the
      // autocomplete's currentList do the locale-friendly matching.
      acMode.value = 'field';
      acField.value = '';
      acQuery.value = trimmed;
      acOp.value = '';
      acOpen.value = true;
      return;
    }
    const [, field, op, rest] = m;
    const fieldLower = field.toLowerCase();
    const isSupported = isKnownField(fieldLower);
    if (!op) {
      if (isSupported) {
        acMode.value = 'operator';
        acField.value = field;
        // DRFS-534: capture the typed remainder after the field name so
        // the operator list can filter against it. If the user types
        // `test foo` (no matching operator starts with "foo"), the
        // filtered list is empty and the popover hides automatically.
        acQuery.value = rest.trimStart();
      } else {
        acMode.value = 'field';
        acField.value = '';
        acQuery.value = field;
      }
      // Bug-2026-04-28: text now ends with bare field name (no op yet)
      // so any previously-stashed op is stale.
      acOp.value = '';
      acOpen.value = true;
      return;
    }
    if (isSupported) {
      // User-name fields with `:` op → free-text name substring. The
      // value source yields numeric user IDs, which can't help the user
      // type a name; worse, picking one would force the op back to `=`
      // (onValuePick below), silently contradicting the user's explicit
      // `:` choice. Suppress the dropdown so typing `assigned_to:Dan`
      // stays a clean free-text path.
      const USER_FIELDS = new Set([
        'assigned_to',
        'created_by',
        'last_saved_by',
      ]);
      if (op === ':' && USER_FIELDS.has(fieldLower)) {
        acOpen.value = false;
        return;
      }
      // Free-text fields (filename, supplier_name, custom doc-type
      // strings) have no enumerable value list — the backend does
      // substring matching server-side. Reopening the dropdown on
      // every keystroke made multi-word values like
      // `filename=Acme Corp` or `supplier_name="ACME GmbH"` feel like
      // the input was resetting after a space (DRFS-581). Suppress the
      // menu in value mode so the user can type freely.
      //
      // DOCB-13124: a field has a value dropdown iff `fieldHasValueSource`
      // says so — the single source of truth (VALUE_SOURCE_FIELDS + date
      // fields). The previous hardcoded allowlist here had drifted: it never
      // gained `invoice_sub_type` / `po_match_status` (which DO have value
      // dropdowns), so when their meta resolved with valueType 'string' they
      // were misclassified as free-text and the value dropdown was suppressed.
      // `fieldHasValueSource` is a pure static check — it does NOT probe the
      // live store, so it can't race store seeding.
      const fieldMeta =
        FIELD_CATALOG.find((f) => f.name === fieldLower) ??
        (opts.getCustomFields?.() ?? []).find(
          (f) => f.name.toLowerCase() === fieldLower,
        );
      const isFreeTextField =
        fieldMeta?.valueType === 'string' && !fieldHasValueSource(fieldLower);
      if (isFreeTextField) {
        acMode.value = 'value';
        acField.value = field;
        acQuery.value = stripQueryQuotes(rest ?? '');
        acOp.value = op;
        acOpen.value = false;
        return;
      }
      acMode.value = 'value';
      acField.value = field;
      acQuery.value = stripQueryQuotes(rest ?? '');
      // Bug-2026-04-28: keep `acOp` in sync with the operator parsed
      // from the text. If the user picked from the dropdown, this
      // mirrors the value already stashed by the operator pick-handler.
      // If the user typed `>=` directly, this captures it now so the
      // value pick-handler doesn't have to re-extract via regex.
      acOp.value = op;
      acOpen.value = true;
    } else {
      acOpen.value = false;
    }
  };

  // ── Pick ──────────────────────────────────────────────────────────
  const onPick = (payload: any) => {
    if (!editor.value) return;
    const ed = editor.value;
    // Re-focus before reading selection: menu clicks can blur the
    // contenteditable and leave state.selection.from stale, which
    // mis-aligns replacement ranges.
    ed.commands.focus();
    const typedText = textBeforeCaret(ed);
    const { from } = ed.state.selection;
    const textStart = from - typedText.length;

    const connectorMatch = /^\s*(AND|OR)\s+/i.exec(typedText);
    const explicitConnector = connectorMatch
      ? (connectorMatch[1].toUpperCase() as 'AND' | 'OR')
      : undefined;

    // Range to replace depends on which AC mode we're in. The goal
    // everywhere: replace ONLY the characters the user's current typing
    // gesture is completing, never wipe anything the user already
    // committed visually (connector literals, parens, etc).
    //
    //   field mode    → replace acQuery (the partial field name, e.g. "fil")
    //   connector mode→ replace acQuery (the partial "A" / "OR")
    //   operator mode → replace acField (the whole field name just typed,
    //                   because acQuery is empty here and `=` needs to
    //                   rewrite "filename" → "filename=")
    //   value mode    → replace from end of any typed AND/OR connector
    //                   to caret — predicate text is being swapped for
    //                   either a chip (onValuePick) or `field op value`
    const connectorPrefixLen = connectorMatch?.[0].length ?? 0;

    if (payload.kind === 'range') {
      const handled = onValuePick?.({
        payload: {
          kind: 'value',
          value: payload.value,
          label: payload.label,
        },
        typedText,
        from,
        textStart,
        explicitConnector,
        field: acField.value,
        op: 'between',
        category: acCategory.value || undefined,
      });
      if (!handled) {
        const predicateStart = textStart + connectorPrefixLen;
        const newText = `${acField.value} between ${payload.start} and ${payload.end}`;
        ed.chain()
          .focus()
          .deleteRange({ from: predicateStart, to: from })
          .insertContentAt(predicateStart, newText)
          .run();
      }
      acOp.value = '';
      acOpen.value = false;
      return;
    }

    if (payload.kind === 'value') {
      const remaining = typedText.slice(connectorPrefixLen);
      const opMatch = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)/.exec(
        remaining,
      );
      // User-name fields: the dropdown yields a numeric user id
      // (prepareUsersDropdown → value: userObj.id), so a typed `:`
      // substring operator would end up as `assigned_to:<id>` —
      // meaningless (an ID isn't a substring). Force `=` for these
      // fields; users who want a name substring can type
      // `assigned_to:Daniel` without touching the dropdown.
      const USER_FIELDS = new Set([
        'assigned_to',
        'created_by',
        'last_saved_by',
      ]);
      // Bug-2026-04-28: priority order for the operator going into the
      // chip:
      //   1. User-fields force `=` (legacy contract, see comment above).
      //   2. The operator the user explicitly picked from the dropdown
      //      (`acOp.value`, set in the operator pick-handler below).
      //      This is authoritative over text-state extraction — it
      //      survives any TipTap reactivity races between operator and
      //      value picks.
      //   3. Regex extraction over `remaining` for the typed-in path
      //      (user typed `field>=value` directly, no dropdown).
      //   4. `:` for hash-prefixed shortcuts (`#invoice`).
      //   5. `=` as final fallback.
      const op = USER_FIELDS.has(acField.value)
        ? '='
        : acOp.value || opMatch?.[2] || (remaining.startsWith('#') ? ':' : '=');

      const handled = onValuePick?.({
        payload,
        typedText,
        from,
        textStart,
        explicitConnector,
        field: acField.value,
        op,
        category: acCategory.value || undefined,
      });
      if (!handled) {
        // Raw editor path: plain text insertion of `field op value`.
        // Start after the connector literal so `AND filename=Fel` →
        // `AND filename=Fellow` instead of losing the `AND `.
        const predicateStart = textStart + connectorPrefixLen;
        const newText = `${acField.value}${op}${quoteValueForInsert(payload.value)}`;
        ed.chain()
          .focus()
          .deleteRange({ from: predicateStart, to: from })
          .insertContentAt(predicateStart, newText)
          .run();
      }
      // Bug-2026-04-28: predicate is now committed (chip created or
      // text inserted). Clear `acOp` so the next field+op picks start
      // from a clean slate — otherwise a leftover `>=` from this
      // predicate could leak into the next one if updateFromContent
      // doesn't fire fast enough on the new keystroke.
      acOp.value = '';
      acOpen.value = false;
      return;
    }

    if (payload.kind === 'smart-filter') {
      // Business-language quick filter (e.g. "Overdue" → `invoice_due_date < today()`).
      // The picker hands us the full SmartFilter; we resolve `me` to the
      // signed-in user-id here so the inserted text is fully self-contained
      // — the parser will treat it like any other typed predicate.
      const sf =
        payload.smartFilter as import('../searchQueryParser').SmartFilter;
      // The host (QuickSearchBox) is responsible for passing the
      // signed-in user-id via opts. Composable stays pinia-free so
      // parser unit tests don't drag the user store into their boot
      // graph. Falling back to the literal `me` token surfaces as a
      // no-match in the parser rather than silently filtering on a
      // wrong user.
      const userId = opts.getUserId?.() ?? null;
      const predicate = sf.buildPredicate({ userId });
      // Replace the partial query the user typed (e.g. "über") with the
      // resolved predicate. The host's tryCommit('Tab') runs right after
      // and converts the inserted text into one or more atomic chips
      // depending on whether the predicate is single- or multi-clause.
      const pickStart = textStart + connectorPrefixLen;
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, predicate)
        .run();
      acOpen.value = false;
      return;
    }

    if (payload.kind === 'preset') {
      // Presence preset (`field!=""` / `field=""`). The picker emits the
      // full operator+empty-value pair, so chip-aware hosts can create the
      // atomic chip directly for any field instead of round-tripping through
      // transient text first. Raw-text hosts fall back to text insertion.
      const op = String(payload.value ?? '').startsWith('!=') ? '!=' : '=';
      const handled = onValuePick?.({
        payload: {
          kind: 'value',
          value: '',
        },
        typedText,
        from,
        textStart,
        explicitConnector,
        field: acField.value,
        op,
        category: acCategory.value || undefined,
      });
      if (handled) {
        acOp.value = '';
        acOpen.value = false;
        return;
      }

      const pickStart = from - (acField.value?.length ?? 0);
      const newText = `${acField.value}${payload.value}`;
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, newText)
        .run();
      acOpen.value = false;
      return;
    }

    if (payload.kind === 'operator') {
      // acQuery is empty in operator mode — the field is already matched,
      // the user is picking an op for it. Back up by acField's length so
      // the replacement overwrites the typed field name with field+op.
      const pickStart = from - (acField.value?.length ?? 0);
      const isBetween = payload.value === 'between';
      const autoQuote =
        payload.value === '=' && fieldAllowsAutoQuote(acField.value);
      const newText = isBetween
        ? `${acField.value} between `
        : `${acField.value}${payload.value}${autoQuote ? '"' : ''}`;
      // Bug-2026-04-28: stash the user-picked operator BEFORE the chain
      // mutation runs. The mutation triggers updateFromContent which
      // flips us into value-mode; if we wrote to acOp afterwards a
      // race could read a stale empty value and the value-pick handler
      // would fall back to `=`. Setting it here makes it the source of
      // truth from the moment the pick fires.
      acOp.value = payload.value;
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, newText)
        .run();
      // Deliberately NOT setting `acOpen = false` — the editor's onUpdate
      // fires updateFromContent synchronously during chain().run(), which
      // flips AC into value mode (or closes for user-field + `:`). A
      // post-run `acOpen = false` would clobber that, killing the value
      // dropdown the user would naturally expect after picking `=`
      // (mirrors the field-pick path's rationale below).
      return;
    }

    if (payload.kind === 'connector') {
      const pickStart = from - (acQuery.value?.length ?? 0);
      const newText = `${payload.value} `;
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, newText)
        .run();
      acOpen.value = false;
      return;
    }

    if (payload.kind === 'directive-prefix') {
      // User picked the "Group by…" suggestion from the field dropdown.
      // Replace the partial text they typed (`g`, `gr`, `gro`, `group`)
      // with the full directive prefix `group by ` and let the next
      // editor onUpdate flip into acDirective='group_by' mode, which
      // re-shows the field list filtered for groupable columns.
      const pickStart = from - (acQuery.value?.length ?? 0);
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, 'group by ')
        .run();
      // Deliberately NOT closing acOpen — updateFromContent fires on
      // the new text and re-opens the dropdown in directive mode.
      return;
    }

    // Field pick (FieldMeta payload).
    //
    // Insert the field name ONLY — no hardcoded `=`. The subsequent
    // editor onUpdate fires updateFromContent() on the fresh
    // "field-without-operator" text, which routes AC to operator mode
    // (see updateFromContent: SUPPORTED_FIELDS match + no op → operator
    // mode). The user then picks `=` or `:` themselves and sees the
    // per-operator hint from OPERATOR_HINTS. `vector:` is a syntactic
    // prefix rather than a field/operator pair, so it keeps its
    // trailing space that acts as the commit separator for the free-
    // text query that follows.
    //
    // Deliberately NOT setting `acOpen = false` here — the editor's
    // onUpdate fires updateFromContent synchronously during
    // chain().run(), flipping AC into operator mode with acOpen=true.
    // A post-run `acOpen = false` would clobber that, forcing the
    // user to type an extra character before the operator dropdown
    // reappears (the pain point reported in DOCB-11199 follow-up).
    const f = payload as FieldMeta;
    // Stash the source-section so the eventual chip carries the
    // category the user picked from, NOT whatever the static catalog
    // lists for this field name. supplier_name appears in BOTH
    // EXTENDED and FULLTEXT — picking from FULLTEXT must produce an
    // orange chip, not a teal one.
    acCategory.value = f.category ?? '';

    // Group-by directive context: replace the FULL "group [by [partial]]"
    // run with a complete `group by <field>` string. The chip-commit
    // pass (shouldCommit) then lifts this into a directive chip on the
    // next Enter/Tab — same surface area as a regular predicate chip,
    // just a different field/op combination.
    if (acDirective.value === 'group_by') {
      const directiveMatch = typedText.match(
        /(group(?:\s+(?:by(?:\s+[a-zA-Z_][a-zA-Z0-9_]*)?)?)?)\s*$/i,
      );
      const directiveLen = directiveMatch ? directiveMatch[0].length : 0;
      const pickStart = from - directiveLen;
      ed.chain()
        .focus()
        .deleteRange({ from: pickStart, to: from })
        .insertContentAt(pickStart, `group by ${f.name}`)
        .run();
      // Stay in directive context — if the picked field is a date the
      // user might want to follow up with a bucket. The next onUpdate
      // sees the new text and either keeps the dropdown open (date
      // bucket follow-up) or closes it.
      return;
    }

    // Vector prefixes (`vector:`, `ai:`) are free-text gateways — insert
    // with a trailing space so the user lands directly in query-typing
    // position. Named fields insert without the space because the next
    // editor update flips AC to operator mode (user picks `=` / `:`).
    const isVectorPrefix = f.name === 'vector:' || f.name === 'ai:';
    const newText = isVectorPrefix ? `${f.name} ` : f.name;
    const pickStart = from - (acQuery.value?.length ?? 0);
    ed.chain()
      .focus()
      .deleteRange({ from: pickStart, to: from })
      .insertContentAt(pickStart, newText)
      .run();
  };

  const openFieldList = () => {
    acDirective.value = null;
    acMode.value = 'field';
    acField.value = '';
    acQuery.value = '';
    acOp.value = '';
    acOpen.value = true;
  };

  const handleKeydown = (key: string): boolean => {
    if (!acOpen.value) {
      // Closed-menu ArrowDown opens the full field hint screen (Smart
      // Filters + Standard Fields …) so users can discover available
      // filters from the keyboard without typing first. Other keys fall
      // through to the editor's default behaviour (cursor movement).
      if (key === 'ArrowDown') {
        openFieldList();
        return true;
      }
      return false;
    }
    const list = currentList.value;
    if (list.length === 0) return false;
    if (key === 'ArrowDown') {
      moveHighlight(1);
      return true;
    }
    if (key === 'ArrowUp') {
      // DRFS-534: when the user is on the first list entry, ArrowUp
      // deselects rather than wrapping to the bottom. This gives them
      // a way to "exit" the suggestion list so the next Enter falls
      // through to fire the query instead of picking. Popover stays
      // open so they can re-enter the list with ArrowDown.
      const current = keyOf(highlighted.value);
      const idx = list.findIndex((x: any) => keyOf(x) === current);
      if (idx <= 0) {
        highlighted.value = null;
        userNavigated.value = false;
        return true;
      }
      moveHighlight(-1);
      return true;
    }
    if (key === 'Escape') {
      acOpen.value = false;
      return true;
    }
    if (key === 'Tab') {
      // TAB is the explicit "complete with the suggestion" gesture and
      // picks whatever is highlighted — including the per-mode default
      // highlight set by `watch(currentList)` (field-mode prefix match
      // and operator-mode `:`). When no highlight exists (e.g. typed
      // text doesn't prefix-match any field), `currentPickPayload`
      // returns null and we fall through to the host's Tab handler so
      // tryCommit can chip a fully-typed `field=value`.
      const payload = currentPickPayload();
      if (payload) {
        onPick(payload);
        return true;
      }
      return false;
    }
    if (key === 'Enter') {
      // DOCB-13124: operator mode has no free-text fulltext fallback to
      // protect — the field is already committed — so ENTER confirms the
      // pre-highlighted operator (the `:` default from `watch(currentList)`)
      // without the explicit ↓ that the DRFS-534 guard below demands. When
      // no operator is highlighted (numeric/date fields whose list has no
      // `:` default), ENTER is swallowed rather than firing a search for
      // the bare `field` — an incomplete predicate must never run a query.
      if (acMode.value === 'operator') {
        const payload = currentPickPayload();
        if (payload) onPick(payload);
        return true;
      }
      // DOCB-13124: ENTER on a highlighted field suggestion confirms it
      // (advancing to operator mode) rather than firing a fulltext search.
      // The default highlight is always a real prefix-matched field (the
      // watcher excludes connector/smart-filter/directive rows), so picking
      // it is exactly what the visible ghost text promises. To search the
      // typed text as a keyword the user presses ESC first to dismiss the
      // suggestion — the next ENTER then falls through to the host's
      // fulltext submit. With no field highlighted (no prefix match) ENTER
      // also falls through.
      if (acMode.value === 'field') {
        const payload = currentPickPayload();
        if (payload) {
          onPick(payload);
          return true;
        }
        return false;
      }
      // DRFS-534 guard (value mode): never silently commit a fuzzy value
      // or user-id list match — require an explicit ↓ before ENTER picks.
      if (userNavigated.value) {
        const payload = currentPickPayload();
        if (payload) {
          onPick(payload);
          return true;
        }
      }
      // Returning false lets the host's Enter handler proceed:
      // tryCommit chips an explicit `field=value` token; otherwise the
      // raw query is submitted as fulltext.
      return false;
    }
    return false;
  };

  // Popover visibility from the consumer's point of view: open AND
  // actually showing at least one row. Used by the parent to gate
  // the debounced backend apply (DOCB-11199 #1 follow-up: the raw
  // `acOpen` also went true for "TestFile" / "filename:xyz-no-match"
  // and blocked the legitimate full-text search).
  const acHasSuggestions = computed<boolean>(
    () => acOpen.value && currentList.value.length > 0,
  );

  return {
    acOpen,
    acMode,
    acField,
    acCategory,
    acOp,
    acQuery,
    highlighted,
    // Exposed so the host can distinguish a default highlight (still
    // safe to fall through to ENTER → submit / fulltext) from an
    // explicit user navigation that ENTER would auto-pick. Used by
    // QuickSearchBox's `showPendingFireIcon` to decide whether the
    // "Press Enter to search" affordance applies.
    userNavigated,
    currentList,
    connectorSuggestions,
    ghostText,
    // DOCB-13124: the host writes this from the editor selection so the
    // ghost/Tab badge only render while the caret is at the end of the input.
    caretAtEnd,
    syncCaretAtEnd,
    acHasSuggestions,
    textBeforeCaret,
    updateFromContent,
    onPick,
    handleKeydown,
    moveHighlight,
    openFieldList,
  };
}
