<template>
  <!-- Column Settings using V2 Component -->
  <ColumnSettings
    ref="columnSettingsRef"
    :columns="allColumnsArray"
    :visible-column-objects="visibleColumnsObjList"
    :show-trigger-button="true"
    :button-color="'primary'"
    :button-icon="'mdi:filter-variant'"
    :tooltip-key="tooltipKey"
    :enable-batch-selection="true"
    :show-reset-button="false"
    :loading="processing"
    @open="onDialogOpen"
    @close="onDialogClose"
    @save="onSave"
    @cancel="onCancel"
    @remove-custom-column="onRemoveCustomColumn"
    @columns-added="onColumnsAdded"
  >
    <!-- Extra actions slot: Add field from document type button -->
    <template #extra-actions>
      <q-btn
        color="primary"
        unelevated
        :label="$t('add_field_from_document_type')"
        @click="showDocTypeFields = true"
      />
    </template>
  </ColumnSettings>

  <!-- Document type fields dialog -->
  <q-dialog v-model="showDocTypeFields" persistent>
    <DocTypeFields :visible_columns_obj_list="visibleColumnsObjList" />
  </q-dialog>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, defineComponent, PropType } from 'vue';
import { storeToRefs } from 'pinia';
import { useDashboardStore } from 'src/store/main';
import { CONSTANTS } from 'src/constants';
import { ApiExceptions } from 'src/exceptions';
import ColumnSettings, { type ColumnConfig, type ColumnSettingsExposed } from 'src/components/Table/ColumnSettings.vue';
import DocTypeFields from './doc-type-fields.vue';
import type { dynamicObj } from 'src/pages/assets';

export default defineComponent({
  name: 'DashboardColumnSettings',
  components: {
    ColumnSettings,
    DocTypeFields,
  },
  props: {
    tooltipKey: {
      type: String as PropType<string>,
      default: 'table_column_settings_tooltip',
    },
  },
  setup() {
    const dashboardStore = useDashboardStore();

    const {
      table_columns: allColumns,
      selected_dashboard: selectedDashboard,
      personal_dashboards: personalDashboards,
    } = storeToRefs(dashboardStore);

    const {
      getSavedColumns,
      saveColumns,
      getColumnLabel,
      buildFormDataFromJson,
      stripColumnDataForSave,
      populateColumnDataFromServer,
      editDashboardTemplate,
    } = dashboardStore;

    return {
      // Store refs
      allColumns,
      selectedDashboard,
      personalDashboards,
      // Store methods
      getSavedColumns,
      saveColumns,
      getColumnLabel,
      buildFormDataFromJson,
      stripColumnDataForSave,
      populateColumnDataFromServer,
      editDashboardTemplate,
      // Component refs
      columnSettingsRef: ref<ColumnSettingsExposed | null>(null),
      // State
      processing: ref(false),
      showDocTypeFields: ref(false),
      visibleColumnsObjList: ref<Record<string, any>>({}),
      myDashboard: ref<any>(null),
      dashboard_columns_key: CONSTANTS.dashboard_columns_pref_key,
    };
  },
  computed: {
    /**
     * Convert all_columns object to array format for ColumnSettings
     */
    allColumnsArray(): ColumnConfig[] {
      const columns: ColumnConfig[] = [];

      for (const [key, value] of Object.entries(this.allColumns || {})) {
        const item = value as any;
        columns.push({
          name: item.name || key,
          label: this.getColumnLabel(item),
          order: item.order ?? 0,
          sortable: item.sortable ?? true,
          translation_key: item.translation_key,
          ...item,
        });
      }

      return columns;
    },
  },
  mounted() {
    document.addEventListener('add_columns', this.handleAddColumns as EventListener);
  },
  beforeUnmount() {
    document.removeEventListener('add_columns', this.handleAddColumns as EventListener);
  },
  methods: {
    /**
     * Handle dialog open - load columns using store's getSavedColumns
     */
    async onDialogOpen() {
      // Find fresh dashboard data from personal_dashboards
      this.myDashboard = this.selectedDashboard?.id
        ? this.personalDashboards.find((d: any) => d.id === this.selectedDashboard?.id) || {}
        : {};

      // Load visible columns - store's getSavedColumns handles both custom and default dashboard
      if (this.myDashboard?.id) {
        this.visibleColumnsObjList = this.populateColumnDataFromServer(this.myDashboard.customizations).columns;
      } else {
        this.visibleColumnsObjList = await this.getSavedColumns();
      }

      // Add labels to columns
      for (const key in this.visibleColumnsObjList) {
        this.visibleColumnsObjList[key].label = this.getColumnLabel(this.visibleColumnsObjList[key]);
      }

      // Close advanced settings menu
      document.dispatchEvent(new CustomEvent('advancedSettingsClose'));
    },

    /**
     * Handle dialog close
     */
    onDialogClose() {
      document.dispatchEvent(new CustomEvent('remove_advanced_settings_pop_up'));
    },

    /**
     * Handle save - uses store methods
     */
    async onSave(payload: {
      visibleColumns: ColumnConfig[];
      hiddenColumns: ColumnConfig[];
      allColumns: ColumnConfig[];
    }) {
      this.processing = true;

      try {
        // Convert visible columns array back to object format
        const columnsObj: Record<string, any> = {};
        payload.visibleColumns.forEach((col, index) => {
          const key = this.myDashboard?.id ? String(index) : col.name;
          columnsObj[key] = {
            name: col.name,
            order: index + 1,
            sortable: col.sortable ?? true,
            translation_key: col.translation_key || col.name,
            ...(col.doc_type_key && { doc_type_key: col.doc_type_key }),
            ...(col.title && { title: col.title }),
          };
        });

        this.visibleColumnsObjList = columnsObj;

        if (this.myDashboard?.id) {
          // Custom Dashboard
          const objectCopy = { ...this.myDashboard.customizations };
          objectCopy['columns'] = this.stripColumnDataForSave(columnsObj);

          const dataObj = {
            id: this.myDashboard.id,
            name: this.myDashboard.name,
            customizations: objectCopy,
            shared: this.myDashboard.shared,
          };

          await this.editDashboardTemplate(this.buildFormDataFromJson(dataObj));
          document.dispatchEvent(new CustomEvent(this.dashboard_columns_key + '_updated'));
        } else {
          // Default Dashboard
          await this.saveColumns(columnsObj);
        }

        document.dispatchEvent(new CustomEvent('reload_columns'));
        this.columnSettingsRef?.close();
      } catch (error) {
        const msg = ApiExceptions.getErrorMessage(error as dynamicObj);
        notify.error(msg);
        logError(error);
        this.columnSettingsRef?.setSaving(false);
      } finally {
        this.processing = false;
      }
    },
    /**
     * Handle cancel
     */
    onCancel() {
      // Reset to original state (handled by component internally)
    },
    /**
     * Handle custom column removal
     */
    onRemoveCustomColumn(column: ColumnConfig) {
      if (this.selectedDashboard?.id) {
        this.selectedDashboard.customizations.columns = Object.fromEntries(
          Object.entries(this.selectedDashboard.customizations.columns).filter(
            ([_, col]) => (col as any).name !== column.name
          )
        );
        this.visibleColumnsObjList = { ...this.selectedDashboard.customizations.columns };
      } else {
        delete this.visibleColumnsObjList[column.name];
      }
    },
    /**
     * Handle columns added from doc type fields
     */
    onColumnsAdded(columns: ColumnConfig[]) {
      // Update visible columns obj list
      columns.forEach(col => {
        this.visibleColumnsObjList[col.name] = col;
      });
    },
    /**
     * Handle add_columns event from DocTypeFields dialog
     */
    handleAddColumns(e: CustomEvent) {
      if (!e?.detail?.selected_fields) return;

      for (const key in e.detail.selected_fields) {
        this.visibleColumnsObjList[key] = e.detail.selected_fields[key];
      }

      if (this.myDashboard?.id) {
        this.visibleColumnsObjList = Object.values(this.visibleColumnsObjList) as any;
      }

      const newColumns = Object.values(e.detail.selected_fields).map((field: any) => ({
        name: field.name,
        label: field.translation_key || field.title || this.getColumnLabel(field),
        order: field.order,
        doc_type_key: field.doc_type_key,
        isCustomField: true,
        sortable: field.sortable ?? true,
        translation_key: field.translation_key,
        title: field.title,
        ...field,
      }));

      this.columnSettingsRef?.addColumns(newColumns);
      this.showDocTypeFields = false;
    },
    /**
     * Open the column settings dialog (exposed method)
     */
    open() {
      this.columnSettingsRef?.open();
    },
  },
});
</script>
