/**
 * DOCB-11199 #3 — decide what to do with the saved-dashboard
 * preference on mount / re-hydration.
 *
 * Background: the pre-fix flow in `saved-filter-badges.vue:mounted`
 * called `resetViewToDefault()` — which wipes the saved preference
 * — whenever `personal_dashboards.find()` didn't return a match.
 * That's correct when the list is fully loaded and the saved entry
 * really was deleted. It's destructive when the list just hasn't
 * finished fetching yet (network slow, request still in flight
 * despite the `await`, transient failure), because the user loses
 * their tab selection permanently and the next load starts from a
 * blank slate.
 *
 * This helper distinguishes the three cases and returns:
 *   `wait`    — list not populated; caller should defer the decision
 *   `reset`   — list is populated but the saved dashboard is gone
 *   `restore` — found a match, hand back the matching dashboard so
 *               the caller can hand it to `selectDashboard`
 */
export interface DashboardLike {
  id: string | number;
  [k: string]: unknown;
}

export type RestoreDecision =
  | { action: 'restore'; dashboard: DashboardLike }
  | { action: 'reset' }
  | { action: 'wait' };

export function decideTabRestore(args: {
  savedDashboard: DashboardLike | null | undefined;
  personalDashboards: DashboardLike[] | undefined;
}): RestoreDecision {
  const { savedDashboard, personalDashboards } = args;

  if (!savedDashboard || savedDashboard.id === undefined || savedDashboard.id === null) {
    return { action: 'reset' };
  }

  // Anti-reset guard: never wipe the saved preference just because
  // the list hasn't finished fetching. Callers should set up a
  // watcher to retry once `personal_dashboards` populates.
  if (!personalDashboards || personalDashboards.length === 0) {
    return { action: 'wait' };
  }

  const savedId = String(savedDashboard.id);
  const found = personalDashboards.find((d) => String(d.id) === savedId);

  if (found) return { action: 'restore', dashboard: found };
  return { action: 'reset' };
}
