<template>
  <q-btn outline class="q-mr-sm">
    <Icon icon="mdi:sort" width="20" height="20" />
    <q-popup-proxy
      @before-show="BeforePopupShow"
      v-model="show_column_settings"
    >
      <q-banner>
        <div class="row justify-around items-start">
          <div class="col row q-pt-md">
            <div class="text-subtitle1">{{ $t('column_sort_settings') }}</div>
          </div>
        </div>

        <div v-if="error" class="col-12 text-red-5 height-20">
          Please make sure column and direction are selected
        </div>

        <div class="row no-wrap justify-around q-pt-md">
          <!-- Columns list -->

          <div class="col-auto q-mr-md">
            <q-select
              class="select-box"
              outlined
              v-model="order_by_field"
              use-input
              :options="filtered_columns"
              @filter="filterlistEvent"
              :label="$t('column_name')"
              emit-value
              map-options
            />
          </div>

          <div class="col-auto q-mr-md">
            <!-- Sort direction -->
            <q-select
              outlined
              class="select-box"
              v-model="order_by_direction"
              use-input
              :options="direction_options"
              :label="$t('Direction')"
              emit-value
              map-options
            />
          </div>
        </div>

        <div class="row justify-end items-start q-mt-md">
          <q-btn
            flat
            class="q-mr-sm"
            :label="$t('cancel')"
            @click="show_column_settings = false"
          />
          <q-btn color="primary" unelevated :label="$t('done')" @click="saveSettings()" />
        </div>
      </q-banner>
      <q-inner-loading :showing="processing">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </q-popup-proxy>
    <q-tooltip>{{ $t('dashboard_sort_settings_tooltip') }}</q-tooltip>
  </q-btn>
</template>

<script lang="ts">

import { defineComponent, ref } from 'vue';
import { useDashboardStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { objLen } from 'src/utils/general';

export default defineComponent({
  
  props: {},
  mounted() {
    this.init();
  },
  data() {
    return {};
  },

  methods: {
    BeforePopupShow() {
      this.init();
      this.show_column_settings = true;
    },

    async init() {
      this.visible_columns = [] as dynamicObj[];
      await this.setColumns();

      this.direction_options = [];
      this.direction_options.push({ value: 'asc', label: this.$t('asc') });
      this.direction_options.push({ value: 'desc', label: this.$t('desc') });

      if (objLen(this.order_by) !== 0) {
        this.order_by_field = this.order_by.field_name;
        this.order_by_direction = this.order_by.direction;
      }
    },

    async setColumns() {
      await this.setVisibleColumns();
    },

    async setVisibleColumns() {
      const visible_columns = await this.getSavedColumns();

      this.filtered_columns = [] as dynamicObj[];
      this.visible_columns = [] as dynamicObj[];

      for (const key in visible_columns) {
        visible_columns[key].selected = false;
        visible_columns[key].label = this.getColumnLabel(visible_columns[key]);
        visible_columns[key].value = key;
        this.filtered_columns.push(visible_columns[key]);
        this.visible_columns.push(visible_columns[key]);
      }

      this.sortColumns();
    },

    getColumnLabel(item: dynamicObj) {
      if (!item.label) {
        item.label = item.name;
      }

      return this.$t(item.label);
    },

    async saveSettings() {
      this.error = false;
      if (!this.order_by_field || !this.order_by_direction) {
        this.error = true;
        return;
      }

      this.processing = true;
      this.order_by = {
        field_name: this.order_by_field,
        direction: this.order_by_direction,
      };
      await this.saveOrderBy();
      this.processing = false;
      this.show_column_settings = false;

      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    sortColumns() {
      this.filtered_columns.sort((a: any, b: any) => {
        return a.order - b.order;
      });

      this.visible_columns.sort((a: any, b: any) => {
        return a.order - b.order;
      });
    },

    filterlistEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filtered_columns = this.visible_columns;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filtered_columns = this.visible_columns.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { saveOrderBy, getSavedColumns } = dashboard_store;
    const { order_by } = storeToRefs(dashboard_store);
    return {
      order_by,
      saveOrderBy,
      visible_columns: ref([] as dynamicObj[]),
      visible_columns_obj_list: ref({} as dynamicObj),
      filtered_columns: ref({} as any),
      processing: ref(false),
      getSavedColumns,
      show_column_settings: ref(false),
      order_by_field: ref(''),
      order_by_direction: ref(''),
      direction_options: ref([] as dynamicObj[]),
      error: ref(false),
    };
  },
});
</script>
<style lang="scss"></style>
