<template>
  <!-- In-input error badge. Only renders when the parent explicitly
       has errors to surface. Keeping it out of the layout flow when
       empty means adding/removing validation doesn't shift the
       adjacent search row by a pixel — the whole reason this
       indicator replaced the block-level banner. -->
  <q-icon
    v-if="errors.length > 0"
    name="error"
    size="16px"
    class="qs-error-indicator"
    :aria-label="$t('copy_to_clipboard')"
    :title="$t('copy_to_clipboard')"
    @click.stop.prevent="copyErrors"
  >
    <q-tooltip
      anchor="bottom middle"
      self="top middle"
      :offset="[0, 6]"
      content-class="qs-error-tooltip"
      :delay="80"
    >
      <div class="qs-error-tooltip__title">
        {{ $t('search_validation_title') }}
      </div>
      <ul class="qs-error-tooltip__list">
        <li v-for="(err, idx) in errors" :key="idx">
          {{ errorText(err) }}
        </li>
      </ul>
    </q-tooltip>
  </q-icon>
</template>

<script lang="ts">
import { defineComponent, PropType } from 'vue';
import { copyToClipboard } from 'quasar';
import type { ValidationError } from 'src/pages/Dashboard/Filters/validateQuery';

export default defineComponent({
  name: 'ValidationErrorIndicator',
  props: {
    errors: {
      type: Array as PropType<ValidationError[]>,
      default: () => [],
    },
  },
  computed: {
    copyText(): string {
      const title = this.$t('search_validation_title');
      const messages = this.errors.map((err) => this.errorText(err)).filter(Boolean);
      return [title, ...messages].join('\n');
    },
  },
  methods: {
    // Validator errors carry an i18n key + params so the message follows
    // the active locale (the tooltip title already did). `server_rejected`
    // errors arrive pre-formatted from the backend in `message`.
    errorText(err: ValidationError): string {
      if (err.messageKey) {
        return this.$t(err.messageKey, err.params ?? {});
      }
      return err.message ?? '';
    },
    async copyErrors(): Promise<void> {
      if (!this.copyText) return;
      await copyToClipboard(this.copyText);
    },
  },
});
</script>

<style lang="scss" scoped>
// Small, non-intrusive indicator: a filled error glyph tinted with the
// destructive token so it reads as "something's wrong" in both themes.
// Placing it inside the input's prepend slot means it never pushes the
// search row vertically; absent-vs-present is a pure colour/opacity
// change as far as layout is concerned.
.qs-error-indicator {
  color: var(--destructive);
  margin-left: 4px;
  cursor: pointer;
  animation: qs-error-pulse 1.4s ease-out 1;
}

@keyframes qs-error-pulse {
  0%   { transform: scale(0.8); opacity: 0; }
  40%  { transform: scale(1.15); opacity: 1; }
  100% { transform: scale(1); opacity: 1; }
}
</style>

<style lang="scss">
// Tooltip content class — global because q-tooltip portals its body
// out of the component tree, so scoped styles can't reach it.
.qs-error-tooltip {
  max-width: 360px;
  padding: 10px 12px;
  background: var(--popover, var(--background));
  color: var(--foreground);
  border: 1px solid color-mix(in srgb, var(--destructive) 45%, transparent);
  border-radius: 8px;
  font-size: 12.5px;
  line-height: 1.45;
  box-shadow: 0 6px 20px -8px rgba(0, 0, 0, 0.25);
}
.qs-error-tooltip__title {
  font-weight: 600;
  color: var(--destructive-badge-text, var(--destructive));
  margin-bottom: 4px;
}
.qs-error-tooltip__list {
  margin: 0;
  padding-left: 16px;
}
.qs-error-tooltip__list li + li {
  margin-top: 2px;
}
</style>
