<template>
  <!-- <span class="icon-grey q-pl-md list-heading text-capitalize">{{ $t('personal') }}</span> -->
  <q-list class="max-width-300 q-mt-md">
    <template
      v-for="dashboard in filtered_personal_dashboards"
      :key="dashboard?.id"
    >
      <q-item
        v-if="dashboard"
        :active="isDashboardActive(dashboard.id)"
        class="dashboard-item-padding"
        clickable
        v-close-popup
        @click="selectDashboard(dashboard, true, true)"
      >
        <q-item-section avatar class="min-width-28">
          <q-icon
            name="share"
            class="dashboard-text-color"
            v-if="dashboard && dashboard.in_share"
            size="15px"
            style="font-weight: bold"
          />
          <Icon
            icon="mdi:filter"
            width="15"
            height="15"
            class="dashboard-text-color"
            v-else
          />
        </q-item-section>
        <div class="dashboard-name-section">
          <span class="dashboard-name">{{ dashboard.name }}
            <q-tooltip>{{ dashboard.name }}</q-tooltip>
          </span>
        </div>
        <q-item-section side class="no-padding">
          <div class="row no-wrap">
            <q-btn flat dense @click.stop.prevent="showConfirmationPopUp(dashboard.id)" :disable="dashboard.in_share">
              <q-icon name="delete" size="xs" class="control-icon display-none"/>
              <q-tooltip v-if="dashboard.in_share">
                {{ $t('cant_delete_dashboard') }}
              </q-tooltip>
            </q-btn>
            <q-btn flat dense @click.stop.prevent="$emit('edit-dashboard', dashboard.id)" :disable="dashboard.in_share">
              <q-icon name="edit" size="xs" class="control-icon display-none"/>
              <q-tooltip v-if="dashboard.in_share">
                {{ $t('cant_edit_dashboard') }}
              </q-tooltip>
            </q-btn>
          </div>
        </q-item-section>
      </q-item>
    </template>
  </q-list>

  <q-dialog
    v-model="deleteConfirm"
    persistent
    transition-show="scale"
    transition-hide="scale"
  >
    <q-card class="confirm-delete-card">
      <q-card-section class="centered q-pt-lg q-pb-none">
        <q-avatar
          icon="warning"
          color="negative"
          text-color="white"
          size="48px"
        />
      </q-card-section>

      <q-card-section class="q-pt-md q-px-lg">
        <div class="text-h6 text-center">{{ $t('sure') }}</div>
      </q-card-section>

      <q-separator spaced />

      <q-card-actions align="right" class="q-pa-md">
        <q-btn flat :label="$t('cancel')" v-close-popup />
        <q-btn
          color="negative"
          unelevated
          :label="$t('delete')"
          v-close-popup
          @click="deleteDashboard(delete_id)"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useDashboardStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  components: {
    
  },
  emits: ['edit-dashboard'],
  methods: {
    showConfirmationPopUp(id: string) {
      this.delete_id = id;
      this.deleteConfirm = true;
    },
    async deleteDashboard(id: string) {
      try {
        await this.deleteDashboardTemplate(id);
        notify.success(this.$t('DELETED_SUCCESSFULLY'));
        if (id == this.selected_dashboard.id) {
          this.resetViewToDefault();
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const {
      personal_dashboards,
      order_by,
      pagination_size,
      processing,
      filtered_personal_dashboards,
      quickFilterMap,
      selected_dashboard,
    } = storeToRefs(dashboard_store);
    const {
      getDashboardListView,
      isDashboardActive,
      saveOrderBy,
      resetViewToDefault,
      selectDashboard,
      deleteDashboardTemplate,
      saveSortedColumns,
      overWriteFilters,
    } = dashboard_store;
    return {
      getDashboardListView,
      isDashboardActive,
      deleteDashboardTemplate,
      saveOrderBy,
      filtered_personal_dashboards,
      saveSortedColumns,
      personal_dashboards,
      overWriteFilters,
      resetViewToDefault,
      selectDashboard,
      quickFilterMap,
      selected_dashboard,
      order_by,
      processing,
      pagination_size,
      deleteConfirm: ref(false),
      delete_id: ref(''),
    };
  },
});
</script>
<style scoped>
.dashboard-item-padding:hover {
  .control-icon {
    display: block;
  }
}

.dashboard-name-section {
  flex: 1;
  overflow: hidden;
  min-width: 0;
  display: flex;
  align-items: center;
}

.dashboard-name {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  display: block;
}

