<template>
  <div class="row q-my-sm capitalize">
    <span class="mt-10 q-mr-md">{{ $t('start_date') }}</span>
    <q-space />
    <q-input
      outlined
      dense
      v-model="startDate"
      data-cy="start_date"
      :clearable="true"
      class="q-mr-sm"
      style="width: 227px; height: 40px"
      @update:model-value="modelUpdated()"
    >
      <template v-slot:append>
        <q-icon name="event" class="cursor-pointer" id="btn_start_date">
          <q-popup-proxy cover transition-show="scale" transition-hide="scale">
            <q-date
              v-model="startDate"
              mask="YYYY-MM-DD"
              @update:model-value="modelUpdated()"
            >
              <div class="row items-center justify-end">
                <q-btn v-close-popup label="Close" color="primary" flat />
              </div>
            </q-date>
          </q-popup-proxy>
        </q-icon>
      </template>
    </q-input>
  </div>

  <div class="row q-my-sm capitalize">
    <span class="mt-10 q-mr-md">{{ $t('end_date') }}</span>
    <q-space />
    <q-input
      outlined
      dense
      v-model="endDate"
      data-cy="end_date"
      :clearable="true"
      class="q-mr-sm"
      style="width: 227px; height: 40px"
      @update:model-value="modelUpdated()"
    >
      <template v-slot:append>
        <q-icon name="event" class="cursor-pointer" data-cy="btn_end_date">
          <q-popup-proxy cover transition-show="scale" transition-hide="scale">
            <q-date
              v-model="endDate"
              mask="YYYY-MM-DD"
              @update:model-value="modelUpdated()"
            >
              <div class="row items-center justify-end">
                <q-btn v-close-popup label="Close" color="primary" flat />
              </div>
            </q-date>
          </q-popup-proxy>
        </q-icon>
      </template>
    </q-input>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { CONSTANTS } from 'src/constants';
import { useDashboardStore } from 'src/store/main';

export default defineComponent({
  // mixins: [],
  props: {
    start_date: {
      type: String,
      default: '',
    },
    end_date: {
      type: String,
      default: '',
    },
  },
  watch: {
    tempFilterMap: {
      deep: true,
      handler: function (newVal, oldVal) {
        this.loadFilters();
      },
    },
  },

  mounted() {
    this.loadFilters();
    this.startDate = this.start_date;
    this.endDate = this.end_date;
  },

  methods: {
    loadFilters() {
      const dateRange = this.tempFilterMap.get('date_range');

      if (!dateRange) {
        this.startDate = '';
        this.endDate = '';
        return;
      }

      const dateArray = dateRange.split(CONSTANTS.dateSplitBy);

      if (dateArray[0] != CONSTANTS.questionSymbol) {
        this.startDate = dateArray[0];
      }

      if (dateArray[1] != CONSTANTS.questionSymbol) {
        this.endDate = dateArray[1];
      }
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    modelUpdated() {
      let dateRange = '';

      if (this.startDate || this.endDate) {
        if (this.startDate) {
          dateRange = this.startDate;
        } else {
          dateRange += CONSTANTS.questionSymbol;
        }

        dateRange += CONSTANTS.dateSplitBy;

        if (this.endDate) {
          dateRange += this.endDate;
        } else {
          dateRange += CONSTANTS.questionSymbol;
        }
      }

      if (dateRange) {
        this.tempFilterMap.set('date_range', dateRange);
      } else {
        this.tempFilterMap.delete('date_range');
      }

      // this.triggerApplyFilters();
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { tempFilterMap } = storeToRefs(dashboard_store);

    return {
      tempFilterMap,
      startDate: ref(''),
      endDate: ref(''),
    };
  },
});
</script>
<style lang="scss" scoped>
.user-filter-select {
  width: 227px;
}

:deep(.q-field--dense .q-field__control) {
  height: 35px !important;
}
</style>
