import type { ValueOption } from './useFieldValueSource';

/**
 * DOCB-11199 follow-up — pure value → {value, label} resolver used by
 * the chip editor's re-commit path (`normaliseValue` in
 * QuickSearchBox.vue). Extracted so the case-insensitive match
 * (including the String-coerce that handles numeric user ids from
 * `prepareUsersDropdown`) is unit-testable without mounting the
 * whole editor.
 *
 * Lookup order:
 *   1. Exact match on `o.value` (case-insensitive, stringified on
 *      both sides so a typed "2" matches a stored numeric 2).
 *   2. Fallback match on `o.label` — lets the user type
 *      `assigned_to=Amier` (label) and still round-trip to the
 *      canonical id.
 *   3. No match → return the original value with no label. Callers
 *      pass this through to the chip, which keeps the raw typed
 *      text visible so the user knows exactly what filter they
 *      submitted.
 *
 * Empty value or empty options short-circuit to `{ value }` so the
 * caller doesn't accidentally attach a stale label from a previous
 * field's list.
 */
export function matchValueInOptions(
  value: string,
  options: ReadonlyArray<ValueOption>,
): { value: string; label?: string } {
  if (!value) return { value };
  if (!options || options.length === 0) return { value };

  const lower = String(value).toLowerCase();

  // Exact on value first — the canonical path. Stringify both sides:
  // user fields carry numeric ids (see
  // `src/store/Dropdown/dropdown.store.ts:prepareUsersDropdown`
  // pushing `value: userObj.id` where id is a number). Calling
  // `.toLowerCase()` on a number throws, and because the throw
  // happens inside `.find()`'s predicate the whole lookup silently
  // returned undefined — the reported "chip shows just the user id
  // after backspace + enter" bug.
  const exact = options.find(
    (o) => String(o.value ?? '').toLowerCase() === lower,
  );
  if (exact) return { value: String(exact.value), label: exact.label };

  // Label match — the "user typed the human label instead of the
  // canonical id" path. Returns the CANONICAL value so the backend
  // still gets the id form.
  const byLabel = options.find(
    (o) => String(o.label ?? '').toLowerCase() === lower,
  );
  if (byLabel) return { value: String(byLabel.value), label: byLabel.label };

  return { value };
}
