/**
 * TipTap custom inline node for a lexical grouping paren: `(` or `)`.
 *
 * Why a node (atomic) and not plain text:
 * - Predicates are committed as atomic chip nodes, so parens need to
 *   coexist with them in a single contenteditable. Having parens as
 *   plain text would force the chip-commit logic to strip leading `(`
 *   and trailing `)` from every typedText inspection.
 * - Atomic means the cursor treats each paren as a single unit and
 *   backspace deletes the whole thing — same UX as a chip.
 * - Round-trip is explicit: `editorDocToQueryString` walks `paren`
 *   nodes and emits `(` / `)`; `buildDocContent` tokenises the raw
 *   string and inserts a paren node for every paren token.
 *
 * Not every `(` is a grouping paren — `today()`, `now()`, `today(-1)`
 * are function-call literals where the parens belong to the identifier
 * they follow, not to a logical grouping. Those stay as plain text
 * inside the value segment (so `imported_on=today()-1` serialises back
 * exactly the way the user typed it, no spaces injected).
 *
 * The distinction is made at input time via `handleTextInput` below:
 *   • typing `(`  → convert to atom UNLESS preceded by an identifier
 *                   character (function-call case — keep as text)
 *   • typing `)`  → convert to atom UNLESS the innermost unmatched
 *                   `(` before the caret is plain text (meaning we're
 *                   closing a function-call paren we kept as text)
 *
 * Attributes stored on the node:
 *   side — 'open' | 'close'
 */

import { Node, mergeAttributes } from '@tiptap/core';
import { VueNodeViewRenderer } from '@tiptap/vue-3';
import { Plugin, PluginKey } from '@tiptap/pm/state';
import type { Component } from 'vue';

export type ParenSide = 'open' | 'close';

export interface ParenAttrs {
  side: ParenSide;
}

const IDENT_CHAR_RE = /[a-zA-Z0-9_]/;

/**
 * Walk text-before-caret in reverse looking for the innermost unmatched
 * opening paren. Returns true if one is found AND it's plain text (not
 * a paren node) — i.e. the user is currently inside a function-call's
 * argument list. Paren nodes terminate the walk early because any `)`
 * closing them is definitively a grouping close.
 */
function caretIsInsideFunctionCall(state: any): boolean {
  const { selection, doc } = state;
  const { from } = selection;
  // Accumulate text-before-caret, resetting at atomic boundaries (a
  // chip / paren / connector node splits the lexical context).
  let text = '';
  doc.nodesBetween(0, from, (node: any) => {
    if (node.type.name === 'text') text += node.text ?? '';
    else if (
      node.type.name === 'chip' ||
      node.type.name === 'paren' ||
      node.type.name === 'connector'
    ) text = '';
  });
  // Scan right-to-left counting unmatched opens. If we find `(` with
  // no matching `)` after it, the caret is inside a function-call arg.
  let depth = 0;
  for (let i = text.length - 1; i >= 0; i--) {
    const ch = text[i];
    if (ch === ')') depth++;
    else if (ch === '(') {
      if (depth === 0) return true; // innermost unmatched `(`
      depth--;
    }
  }
  return false;
}

export function createParenNode(ParenNodeViewComponent: Component) {
  return Node.create<never>({
    name: 'paren',

    group: 'inline',
    inline: true,
    atom: true,
    selectable: true,
    draggable: false,

    addAttributes() {
      return {
        side: { default: 'open' },
      };
    },

    parseHTML() {
      return [
        {
          tag: 'span[data-paren]',
          getAttrs(el) {
            const dom = el as HTMLElement;
            const s = dom.getAttribute('data-side') === 'close' ? 'close' : 'open';
            return { side: s };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      return [
        'span',
        mergeAttributes(HTMLAttributes, { 'data-paren': '' }),
      ];
    },

    // DOCB-11199 follow-up: clipboard plain-text emits literal `(` /
    // `)` so grouped selections (`(chip1 OR chip2)`) round-trip
    // through the parser on paste.
    renderText({ node }) {
      const side = (node.attrs as { side?: string }).side;
      return side === 'close' ? ')' : '(';
    },

    addNodeView() {
      return VueNodeViewRenderer(ParenNodeViewComponent as any);
    },

    // Context-aware paren handling — nodeInputRule isn't expressive
    // enough because we need to read doc state around the caret.
    addProseMirrorPlugins() {
      const nodeType = this.type;
      return [
        new Plugin({
          key: new PluginKey('paren-input'),
          props: {
            handleTextInput(view, _from, _to, insertedText) {
              if (insertedText !== '(' && insertedText !== ')') return false;
              const { state } = view;
              const { selection } = state;
              const caret = selection.from;

              // Opening paren: keep as plain text when
              //   (a) preceded by an identifier char — function call like `today(`
              //   (b) preceded by the shortcut keyword `in` (with optional
              //       leading `not`) — e.g. `status in (open, error)` — so
              //       `expandInList` can still match `status in (...)` at
              //       commit time.
              if (insertedText === '(') {
                const textBefore = state.doc.textBetween(
                  Math.max(0, caret - 32),
                  caret,
                  '\0',
                );
                const prev = textBefore[textBefore.length - 1] ?? '';
                if (IDENT_CHAR_RE.test(prev)) return false; // function call
                if (/\b(?:not\s+)?in\s*$/i.test(textBefore)) return false; // `in (…)`
                // Otherwise insert the atomic open-paren node.
                const tr = state.tr.replaceSelectionWith(
                  nodeType.create({ side: 'open' }),
                );
                view.dispatch(tr);
                return true;
              }

              // Closing paren: skip the atomisation if we're inside a
              // function call (the matching `(` we saw was text).
              if (caretIsInsideFunctionCall(state)) return false;
              const tr = state.tr.replaceSelectionWith(
                nodeType.create({ side: 'close' }),
              );
              view.dispatch(tr);
              return true;
            },
          },
        }),
      ];
    },
  });
}
