import type { FieldMeta } from './searchQueryParser';
import { UUID_RE } from './searchQueryParser';

export type TranslateFn = (key: string) => string;

const compactSearchLabelKey = (name: string) => `search_field_label_${name}`;

const translated = (
  key: string | undefined,
  translate?: TranslateFn,
): string | null => {
  if (!key || !translate) return null;
  try {
    const value = String(translate(key) ?? '').trim();
    if (!value || value === key) return null;
    return value;
  } catch {
    return null;
  }
};

export const prettyFieldName = (raw: string): string => {
  if (raw === 'vector:') return 'Vector';
  if (raw === 'ai:') return 'AI';
  return raw
    .split('_')
    .filter((w) => !UUID_RE.test(w))
    .map((w) => (w ? w[0].toUpperCase() + w.slice(1) : w))
    .join(' ');
};

export const fieldDisplayLabel = (
  field: FieldMeta,
  translate?: TranslateFn,
): string =>
  translated(field.labelKey, translate) ??
  translated(compactSearchLabelKey(field.name), translate) ??
  field.displayName ??
  prettyFieldName(field.name);

export const fieldDescription = (
  field: FieldMeta,
  translate?: TranslateFn,
): string =>
  translated(field.descriptionKey, translate) ?? field.description ?? '';

export const fieldSearchText = (
  field: FieldMeta,
  translate?: TranslateFn,
): string =>
  [
    field.name,
    prettyFieldName(field.name),
    field.displayName,
    field.description,
    field.labelKey,
    field.descriptionKey,
    translated(field.labelKey, translate),
    translated(compactSearchLabelKey(field.name), translate),
    translated(field.descriptionKey, translate),
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

export const fieldMatchesQuery = (
  field: FieldMeta,
  query: string,
  translate?: TranslateFn,
): boolean => {
  const q = query.toLowerCase().trim();
  return !q || fieldSearchText(field, translate).includes(q);
};

export const isRangeCapableField = (field: FieldMeta): boolean =>
  field.valueType === 'date' ||
  (field.valueType === 'numeric' &&
    field.ops.some((op) => ['>', '<', '>=', '<='].includes(op)));

const DATE_OPS = ['between', '>=', '<='] as const;

// Display order shared by the operator-picker (FieldAutocomplete) and
// the autocomplete composable's `currentList`. `:` (contains / "like")
// leads because it matches the Business-User mental model for string
// fields — exact-equality (`=`) is the secondary pick, with negative
// equality and comparisons trailing. `between` stays last so the
// range-capable prepend in `normaliseOperatorList` still surfaces it
// for numeric fields while the keyboard / visual default lands on `:`.
const OPERATOR_DISPLAY_ORDER = [
  ':',
  '=',
  '!=',
  '>=',
  '<=',
  '>',
  '<',
  'between',
] as const;

export const normaliseOperatorList = (field: FieldMeta): string[] => {
  // Date fields keep their dedicated DATE_OPS order — `between` is the
  // natural default for date searches and must stay top, ahead of `>=`
  // / `<=`. Routing them through the OPERATOR_DISPLAY_ORDER sort below
  // would demote `between` and break the calendar-picker UX.
  if (field.valueType === 'date') return [...DATE_OPS];
  const ops = [...field.ops];
  if (isRangeCapableField(field) && !ops.includes('between')) {
    ops.unshift('between');
  }
  const unique = [...new Set(ops)];
  // Stable sort: ops listed in OPERATOR_DISPLAY_ORDER use that index;
  // unknown ops keep their relative order at the end (Array#sort in V8
  // / TimSort is stable, so equal comparator results preserve order).
  return unique.sort((a, b) => {
    const ai = OPERATOR_DISPLAY_ORDER.indexOf(a as (typeof OPERATOR_DISPLAY_ORDER)[number]);
    const bi = OPERATOR_DISPLAY_ORDER.indexOf(b as (typeof OPERATOR_DISPLAY_ORDER)[number]);
    if (ai === -1 && bi === -1) return 0;
    if (ai === -1) return 1;
    if (bi === -1) return -1;
    return ai - bi;
  });
};
