<template>
  <q-menu
    id="advanceSettingRef"
    ref="advanceSettingRef"
    max-width="500px"
    class="wm-content advanced-menu"
    :offset="[0, 5]"
    persistent
    v-model="menuVisible"
    anchor="bottom middle"
    self="top middle"
    @keyup.esc="menuVisible = false"
  >
    <div class="advanced-search">
      <div class="row q-pa-sm">
        <div class="col-12 display-flex items-center">
          <q-btn
            square
            color="primary"
            class="q-mr-sm sub-menu-button"
            unelevated
            :to="'/settings/dashboard'"
            v-show="is_admin === true"
          >
            <Icon icon="mdi:cog" width="20" height="20" />
            <q-tooltip>{{ $t('more_settings') }}</q-tooltip>
          </q-btn>
          <q-btn
            square
            color="primary"
            unelevated
            icon="keyboard"
            class="q-mr-sm key-card sub-menu-button"
            @click="showKeyboardShortcuts = true"
          >
            <q-tooltip>{{ $t('keyboard_shortcut') }}</q-tooltip>
          </q-btn>
          <span style="margin-left: -8px; margin-right: 8px">
            <q-btn
              color="primary"
              unelevated
              square
              class="q-ml-sm sub-menu-button"
              @click="showMailImportLogs()"
            >
              <Icon icon="mdi:text-box-multiple" width="20" height="20" />
              <q-tooltip>{{ $t('import_log') }}</q-tooltip>
            </q-btn>
          </span>

          <span>
            <DashboardColumnSettings :tooltip-key="column_tooltip" />
          </span>
          <q-btn
            icon="close"
            rounded
            dense
            class="advance-setting-icon icon-grey sub-menu-close-button q-ml-sm"
            @click="menuVisible = false"
            round
            size="sm"
            flat
          >
          </q-btn>
          <!-- <span class="col-auto">
            <SortColumnsSettings />
          </span> -->
        </div>
        <!-- <div class="col-auto time-filter">
          <TimeFilter />
        </div> -->

        <div class="col-auto q-ml-md">
          <!-- <UserFilter /> -->
        </div>

        <div class="col-auto q-ml-md">
          <!-- <PaginationSettings /> -->
        </div>
      </div>
    </div>
  </q-menu>

  <ImportLogs
    :connection_id="0"
    :show_import_logs="show_import_logs"
    :setheight="'36px'"
  />
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
//import TimeFilter from './time-filter.vue';
import { useDashboardStore } from 'src/store/main';
import { isUserAdmin } from 'src/utils/UserDetails';
import SortColumnsSettings from './sort-columns-settings.vue';
import DashboardColumnSettings from './DashboardColumnSettings.vue';
import ImportLogs from 'src/pages/Settings/Components/Import/ImportLogs.vue';

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    
    ImportLogs,
    // UserFilter,
    //TimeFilter,
    // PaginationSettings,
    DashboardColumnSettings,
    SortColumnsSettings,
  },
  watch: {},
  mounted: function () {
    document.addEventListener('hide_import_logs', this.onImportLogPopupClose);
    document.addEventListener(
      'advancedSettingsClose',
      this.closeAdvanceSetting,
    );
    document.addEventListener(
      'remove_advanced_settings_pop_up',
      this.removeAdvanceSetting,
    );

    this.is_admin = isUserAdmin();
  },
  unmounted: function () {
    document.removeEventListener(
      'hide_import_logs',
      this.onImportLogPopupClose,
    );
    document.removeEventListener(
      'advancedSettingsClose',
      this.closeAdvanceSetting,
    );
    document.removeEventListener(
      'remove_advanced_settings_pop_up',
      this.removeAdvanceSetting,
    );
  },
  methods: {
    closeAdvanceSetting(event: Event) {
      const element = document.getElementById('advanceSettingRef');
      if (element) {
        element.style.visibility = 'hidden';
      }
    },
    removeAdvanceSetting(event: Event) {
      if (!this.advanceSettingRef) {
        return;
      }
      this.advanceSettingRef.hide();
    },

    showMailImportLogs() {
      this.show_import_logs = !this.show_import_logs;
    },
    onImportLogPopupClose() {
      this.show_import_logs = false;
    },
  },
  data() {
    return {
      column_tooltip: 'table_column_settings_tooltip',
    };
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const advanceSettingRef = ref();
    const { showKeyboardShortcuts } = storeToRefs(dashboard_store);
    return {
      menuVisible: ref(false),
      advanceSettingRef,
      showKeyboardShortcuts,
      is_admin: ref(false),
      show_import_logs: ref(false),
    };
  },
});
</script>

