<template>
  <q-menu class="dashboard-list-menu" :offset="[0, 5]">
    <q-list>
      <q-item dense class="dashboard-item-padding">
        <q-item-section>
          <q-input
            @click.stop.prevent
            dense
            outlined
            :placeholder="$t('search_by_name_or_Id')"
            @update:model-value="(val: any) => filterDashboardList(val)"
            v-model="filterKeyWord"
            class="q-py-sm"
          >
            <!-- <template v-slot:after>
              <q-icon name="search" class="cursor-pointer"></q-icon>
            </template> -->
          </q-input>
        </q-item-section>
      </q-item>
      <q-separator />
      <template v-for="item in function_items" :key="item.name">
        <q-item
          dense
          class="dashboard-item-padding"
          clickable
          v-close-popup
          @click="item.action()"
          :disable="!item.when()"
        >
          <q-item-section class="row">
            <q-icon :name="item.icon" class="q-mr-sm" />
            <span>{{ $t(item.name) }}</span>
          </q-item-section>
          <q-tooltip v-if="!item.when()">
            {{ $t(item.disabledReason ? item.disabledReason() : 'select_dashboard_to_enable') }}
          </q-tooltip>
        </q-item>
        <q-separator inset v-if="item.separator" />
      </template>
    </q-list>
    <q-separator inset v-if="filtered_personal_dashboards.length != 0" />
    <PersonalList
      v-if="filtered_personal_dashboards.length != 0"
      @edit-dashboard="editDashboard"
    />
  </q-menu>

  <q-dialog v-model="create_popup" persistent>
    <CreatePopup :model="current_dashboard" @reset-dashboard-list="getDashboardListView();dashboard_updated=false"/>
  </q-dialog>
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import PersonalList from 'src/pages/Dashboard/multipleListView/PersonalList.vue';
// import SharedList from 'src/pages/Dashboard/multipleListView/SharedList.vue';
import CreatePopup from 'src/pages/Dashboard/multipleListView/Create.vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { storeToRefs } from 'pinia';
import { useDashboardStore } from 'src/store/main';
// Export FunctionItem interface for use in other components
export interface FunctionItem {
  name: string;
  separator: boolean;
  action(): any;
  when(): any;
  icon: string;
  // Optional: returns the translation key to show in the disabled
  // tooltip. When omitted the list falls back to a generic
  // "select a dashboard" message.
  disabledReason?(): string;
}

export default defineComponent({
    components: {
    PersonalList,
    // SharedList,
    CreatePopup,
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const {
      selected_dashboard,
      filtered_personal_dashboards,
      dashboard_updated,
      canSaveCurrentDashboard,
    } = storeToRefs(dashboard_store);
    const {
      filterDashboardList,
      buildFormDataFromJson,
      resetViewToDefault,
      saveChangesToDashboard,
      getCustomization,
      editDashboardTemplate,
      setDefaultFilters,
      resetFilters,
      getDashboardListView,
    } = dashboard_store;
    return {
      filterDashboardList,
      filtered_personal_dashboards,
      dashboard_updated,
      resetFilters,
      getCustomization,
      buildFormDataFromJson,
      saveChangesToDashboard,
      resetViewToDefault,
      editDashboardTemplate,
      canSaveCurrentDashboard,
      selected_dashboard,
      setDefaultFilters,
      create_popup: ref(false),
      rename_popup: ref(false),
      current_dashboard: ref(null as any),
      filterKeyWord: ref(''),
      getDashboardListView,
    };
  },
  mounted() {
    document.addEventListener('close_create_popup', this.closeCreatePopUp);
  },
  unmounted() {
    document.removeEventListener('close_create_popup', this.closeCreatePopUp);
  },
  data() {
    const function_items: FunctionItem[] = [
      {
        name: 'create_new_view',
        separator: false,
        action: this.createNewView,
        when: () => {
          return true;
        },
        icon: 'add',
      },
      {
        name: 'default_dashboard_view',
        separator: true,
        action: this.resetViewToDefault,
        when: () => {
          return true;
        },
        icon: 'person',
      },
      {
        name: 'overwrite_current_view',
        separator: false,
        action: this.saveViewAs,
        // DRFS-583 — share the predicate with saved-filter-badges
        // so the in-list "Overwrite" entry enables/disables in lockstep
        // with the badge above the table.
        when: () => this.canSaveCurrentDashboard,
        // Tell the user *why* they can't save right now instead of
        // the generic "select a dashboard" hint, which was misleading
        // when a dashboard was already selected but either shared or
        // unchanged.
        disabledReason: () => {
          const dashboard = this.selected_dashboard as {
            id?: string | number;
            in_share?: boolean;
          };
          if (!dashboard || !dashboard.id) return 'select_dashboard_to_enable';
          if (dashboard.in_share) return 'cannot_overwrite_shared_dashboard';
          return 'no_changes_to_save';
        },
        icon: 'edit',
      },
    ] as FunctionItem[];
    return {
      function_items,
    };
  },
  methods: {
    closeCreatePopUp() {
      this.current_dashboard = null;
      this.create_popup = false;
    },
    createNewView() {
      this.current_dashboard = null;
      this.create_popup = true;
    },
    async saveViewAs() {
      try {
        await this.saveChangesToDashboard();
        notify.success(this.$t('dashboard_updated_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    editDashboard(dashboard_id: string) {
      this.current_dashboard = this.filtered_personal_dashboards.find(
        (db) => db.id == dashboard_id,
      );
      this.create_popup = true;
    },
  },
});
</script>
<style scoped>
.dashboard-list-menu {
  border-radius: 7px;
  min-width: 300px !important;
  max-width: 300px !important;
}

.row {
  flex-direction: row !important;
  justify-content: start;
  align-items: center;
}
</style>
