<template>
  <div ref="rootRef" class="qs-raw-editor">
    <div v-if="$slots.prepend" class="qs-raw-editor__prepend" @click.stop>
      <slot name="prepend" />
    </div>
    <editor-content :editor="editor" class="qs-raw-editor-content" />
    <div v-if="$slots.append" class="qs-raw-editor__append" @click.stop>
      <slot name="append" />
    </div>
    <!-- Invisible marker positioned at the caret DOMRect; the AC menu
         uses this as its anchor so it opens directly under the cursor. -->
    <div ref="caretAnchorRef" class="qs-caret-anchor" aria-hidden="true"></div>
    <FieldAutocomplete
      v-if="caretAnchorRef"
      :anchor-el="caretAnchorRef"
      :show-menu="acOpen"
      :mode="acMode"
      :field="acField"
      :query="acQuery"
      :highlighted="highlighted"
      :connectors="connectorSuggestions"
      :value-items="valueItems"
      @pick="onAutocompletePick"
      @update:show-menu="setAcOpen"
    />
  </div>
</template>

<script lang="ts">
/**
 * Minimal TipTap editor used by quick-search.vue in raw-view mode.
 *
 * Why not a plain q-input? Because the user asked for syntax
 * highlighting on the raw query string too. A plain input can't
 * colour individual segments. A TipTap editor with the same
 * SyntaxHighlight extension the main chip editor uses reuses the
 * exact regex + palette, so both views read identically.
 *
 * This editor has NO chip / paren nodes and NO input rules — it's
 * strictly for editing a single string of text. Pressing Enter
 * emits `apply`; every change emits `update:modelValue` so the
 * parent can keep its reactive ref in sync.
 */

import {
  defineComponent,
  ref,
  shallowRef,
  computed,
  onMounted,
  onUnmounted,
  watch,
} from 'vue';
import { Editor, EditorContent, Extension } from '@tiptap/vue-3';
import Document from '@tiptap/extension-document';
import Paragraph from '@tiptap/extension-paragraph';
import Text from '@tiptap/extension-text';
import { i18n } from 'src/boot/i18n';
import { SyntaxHighlight } from './tiptap/SyntaxHighlight';
import {
  AutoQuoteOnEquals,
  hasDanglingQuote,
} from './tiptap/AutoQuoteOnEquals';
import FieldAutocomplete from './FieldAutocomplete.vue';
import { useQuickSearchAutocomplete } from './tiptap/useQuickSearchAutocomplete';

export default defineComponent({
  name: 'RawQueryEditor',
  components: { EditorContent, FieldAutocomplete },

  props: {
    modelValue: { type: String, default: '' },
    placeholder: { type: String, default: '' },
  },

  emits: ['update:modelValue', 'apply'],

  setup(props, { emit }) {
    const rootRef = ref<HTMLElement | null>(null);
    // Caret-follow anchor — same role as in QuickSearchBox. See the
    // comment block in that file for the full rationale.
    const caretAnchorRef = ref<HTMLElement | null>(null);
    const editor = shallowRef<Editor | null>(null);

    const updateCaretAnchor = () => {
      const ed = editor.value;
      const anchor = caretAnchorRef.value;
      const host = rootRef.value;
      if (!ed || !anchor || !host) return;
      try {
        const pos = ed.state.selection.from;
        const coords = ed.view.coordsAtPos(pos);
        const hostRect = host.getBoundingClientRect();
        anchor.style.left = `${coords.left - hostRect.left}px`;
        anchor.style.top = `${coords.bottom - hostRect.top}px`;
      } catch {
        // Layout not ready yet — skip; next update will retry.
      }
    };

    // Shared autocomplete — same composable the chip editor uses.
    // No onValuePick override: value picks fall through to the default
    // text-insert path, which writes `field op value` at the caret
    // (appropriate for a single-line raw query string).
    const ac = useQuickSearchAutocomplete({
      editor,
      getLocale: () => {
        try {
          return i18n.getLanguage?.() ?? 'en';
        } catch {
          return 'en';
        }
      },
      translate: (key: string) => i18n.t(key),
    });
    const {
      acOpen,
      acMode,
      acField,
      acQuery,
      highlighted,
      connectorSuggestions,
      updateFromContent,
      onPick,
      handleKeydown,
    } = ac;
    void ac.currentList;
    const valueItems = computed(() =>
      acMode.value === 'value'
        ? ac.currentList.value.map((o: any) => ({
            value: o.value,
            label: o.label,
          }))
        : null,
    );

    const onAutocompletePick = (payload: any) => {
      onPick(payload);
      // v-model emit happens via the editor's onUpdate when the insert
      // commits — no explicit sync needed here.
    };

    // Setter exposed to the template so `@update:show-menu` can toggle
    // acOpen without the template having to unwrap the ref manually.
    const setAcOpen = (v: boolean) => {
      acOpen.value = v;
    };

    const closeDanglingQuoteIfNeeded = () => {
      const ed = editor.value;
      if (!ed) return;
      let text = '';
      ed.state.doc.descendants((node) => {
        if (node.type.name === 'text' && node.text) text += node.text;
      });
      if (hasDanglingQuote(text)) {
        ed.chain().focus('end').insertContent('"').run();
      }
    };

    const EnterApplies = Extension.create({
      name: 'rawEnterApplies',
      addKeyboardShortcuts() {
        return {
          // Route Enter / Tab / Arrow / Escape through the AC dropdown
          // first so keyboard users can pick suggestions without losing
          // focus. Falls through to Enter-applies when AC is closed.
          Enter: () => {
            if (handleKeydown('Enter')) return true;
            closeDanglingQuoteIfNeeded();
            emit('apply');
            return true;
          },
          Tab: () => handleKeydown('Tab'),
          ArrowDown: () => handleKeydown('ArrowDown'),
          ArrowUp: () => handleKeydown('ArrowUp'),
          Escape: () => handleKeydown('Escape'),
        };
      },
    });

    onMounted(() => {
      editor.value = new Editor({
        extensions: [
          Document,
          Paragraph,
          Text,
          SyntaxHighlight,
          AutoQuoteOnEquals,
          EnterApplies,
        ],
        content: props.modelValue
          ? {
              type: 'doc',
              content: [
                {
                  type: 'paragraph',
                  content: [{ type: 'text', text: props.modelValue }],
                },
              ],
            }
          : { type: 'doc', content: [{ type: 'paragraph' }] },
        editorProps: {
          attributes: { class: 'qs-raw-editor-pm', spellcheck: 'false' },
        },
        onUpdate() {
          if (!editor.value) return;
          // Serialize to plain text — a raw query is single-line so
          // joining paragraphs (if any somehow appear) with spaces is
          // safe. The contenteditable enforces paragraph-only content.
          let text = '';
          editor.value.state.doc.descendants((node) => {
            if (node.type.name === 'text' && node.text) text += node.text;
          });
          emit('update:modelValue', text);
          // Drive the AC dropdown from the text-before-caret, same as
          // the chip editor does in its own onUpdate.
          updateFromContent(ac.textBeforeCaret(editor.value));
          updateCaretAnchor();
        },
        onSelectionUpdate() {
          updateCaretAnchor();
        },
        onFocus() {
          updateCaretAnchor();
        },
      });
      // Focus at the end so the user can start editing immediately
      // after toggling to raw view.
      editor.value.commands.focus('end');
    });

    onUnmounted(() => {
      editor.value?.destroy();
    });

    // External updates (parent replaces modelValue) should replace the
    // editor's content. Compare against the editor's current text to
    // avoid feedback loops while the user is typing.
    watch(
      () => props.modelValue,
      (raw) => {
        if (!editor.value) return;
        let current = '';
        editor.value.state.doc.descendants((node) => {
          if (node.type.name === 'text' && node.text) current += node.text;
        });
        if (raw === current) return;
        editor.value.commands.setContent(
          raw
            ? {
                type: 'doc',
                content: [
                  { type: 'paragraph', content: [{ type: 'text', text: raw }] },
                ],
              }
            : { type: 'doc', content: [{ type: 'paragraph' }] },
        );
      },
    );

    return {
      rootRef,
      caretAnchorRef,
      editor,
      acOpen,
      acMode,
      acField,
      acQuery,
      highlighted,
      connectorSuggestions,
      valueItems,
      onAutocompletePick,
      setAcOpen,
    };
  },
});
</script>

