  padding-right: 8px;
  margin-right: 4px;
  border-right: 1px solid var(--border);
  color: var(--muted-foreground);
}
.qs-raw-editor__append {
  display: flex;
  align-items: center;
  gap: 2px;
  margin-left: 4px;
  padding-left: 4px;
  border-left: 1px solid var(--border);
}

// Relative positioning so the FieldAutocomplete q-menu can anchor to
