<template>
  <q-select
    ref="q-select"
    class="q-mr-sm user-filter-select"
    dense
    multiple
    outlined
    use-input
    v-model="assigned_user"
    :options="usersDropdownList"
    @update:model-value="modelUpdated"
    @filter="filterUserByName"
    :label="$t('assigned_to')"
    :loading="loading"
    data-cy="assigned_to"
    @input="clearFilter"
  >
    <template v-slot:option="{ itemProps, selected, opt, toggleOption }">
      <q-item v-bind="itemProps">
        <q-item-section side>
          <q-checkbox
            :model-value="selected"
            @update:model-value="toggleOption(opt)"
          ></q-checkbox>
        </q-item-section>
        <q-item-section avatar>
          <q-icon
            :name="opt.kind === 'group' ? 'groups' : 'person'"
            size="xs"
          />
        </q-item-section>
        <q-item-section>
          <div>{{ opt.label }}</div>
        </q-item-section>
      </q-item>
    </template>
  </q-select>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { getCurrentUserDetails } from 'src/utils/UserDetails';
import {
  useDashboardStore,
  useDropdownStore,
  useDocPermissionsStore,
} from 'src/store/main';
import {
  buildAssigneeOptions,
  partitionAssignees,
  type AssigneeOption,
} from './assignee-filter.helpers';

export default defineComponent({
  props: {
    includeGroups: { type: Boolean, default: false },
  },
  watch: {
    tempFilterMap: {
      deep: true,
      handler: function () {
        this.loadFilters();
      },
    },
  },
  data() {
    return {
      loading: false,
      assigned_to_me_only: 'assigned_to_me_only',
      user_id_key: 'user_id',
      group_id_key: 'group_id',
    };
  },

  async mounted() {
    this.loading = true;
    await this.prepareUsersDropdown();
    if (this.includeGroups) {
      await this.ensureGroupsLoaded();
    }
    this.setAssigneeOptions();
    this.loadSelectedAssignees();
    this.loading = false;
  },

  methods: {
    async ensureGroupsLoaded() {
      if (this.groups && this.groups.length > 0) {
        return;
      }
      await this.getPermissionsData();
    },

    setAssigneeOptions() {
      this.user_options = buildAssigneeOptions(
        this.usersMap,
        this.groups,
        this.includeGroups,
      );
      this.usersDropdownList = this.user_options;
      this.resetFilters();
    },

    selectedAssignees(): AssigneeOption[] {
      const users = this.tagList(
        this.tempFilterMap.get(this.user_id_key + '_list'),
        'user',
      );
      const groups = this.tagList(
        this.tempFilterMap.get(this.group_id_key + '_list'),
        'group',
      );
      return [...users, ...groups];
    },

    tagList(list: any, kind: 'user' | 'group'): AssigneeOption[] {
      if (!Array.isArray(list)) {
        return [];
      }
      return list.map((option: any) => ({ ...option, kind }));
    },

    loadSelectedAssignees() {
      const selected = this.selectedAssignees();
      if (selected.length > 0) {
        this.assigned_user = selected;
      }
    },

    loadFilters() {
      if (this.tempFilterMap.get(this.assigned_to_me_only)) {
        this.migrateAssignedToMeOnly();
        return;
      }

      const selected = this.selectedAssignees();
      if (selected.length > 0) {
        this.assigned_user = selected;
        return;
      }

      this.resetFilters();
    },

    migrateAssignedToMeOnly() {
      this.tempFilterMap.delete(this.assigned_to_me_only);

      const currentUser = getCurrentUserDetails();
      this.assigned_user = [
        {
          value: currentUser.id,
          label: currentUser.userFullName,
          kind: 'user',
        },
      ];
      this.tempFilterMap.set(this.user_id_key, currentUser.id);
      this.tempFilterMap.set(this.user_id_key + '_list', this.assigned_user);
    },

    resetFilters() {
      this.assigned_user = [];
    },

    modelUpdated() {
      const { userIds, groupIds, userList, groupList } = partitionAssignees(
        this.assigned_user,
      );
      this.applyKey(this.user_id_key, userIds, userList);
      this.applyKey(this.group_id_key, groupIds, groupList);
    },

    applyKey(key: string, ids: string, list: AssigneeOption[]) {
      if (list.length === 0) {
        this.tempFilterMap.delete(key);
        this.tempFilterMap.delete(key + '_list');
        return;
      }
      this.tempFilterMap.set(key, ids);
      this.tempFilterMap.set(key + '_list', list);
    },

    filterUserByName(val: any, update: any) {
      if (val === '') {
        update(() => {
          this.usersDropdownList = this.user_options;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.usersDropdownList = this.user_options.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },

    clearFilter() {
      if (this.$refs.qselect !== void 0) {
        (this.$refs.qselect as any).updateInputValue('');
      }
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const { tempFilterMap } = storeToRefs(dashboard_store);

    const dropdownStore = useDropdownStore();
    const { usersMap } = storeToRefs(dropdownStore);
    const { prepareUsersDropdown } = dropdownStore;

    const permission_store = useDocPermissionsStore();
    const { groups } = storeToRefs(permission_store);
    const { getPermissionsData } = permission_store;

    return {
      usersMap,
      groups,
      tempFilterMap,
      assigned_user: ref([] as AssigneeOption[]),
      user_options: ref([] as AssigneeOption[]),
      usersDropdownList: ref([] as AssigneeOption[]),
      prepareUsersDropdown,
      getPermissionsData,
    };
  },
});
</script>
<style lang="scss">
.user-filter-select {
  width: 227px;
}
</style>
