<template>
  <div
    class="saved-filter-badge full-width row justify-start q-mb-sm"
    data-test="qs-filter-badges"
  >
    <q-badge
      class="q-mr-sm q-pa-xs cursor-pointer"
      v-ripple
      rounded
      color="primary"
    >
      <Icon icon="mdi:filter" width="16" height="16" class="text-white" />
      <span class="filter-badge-text"
        >{{
          selected_dashboard && selected_dashboard.name ? selected_dashboard.name : $t('all_invoices')
        }}
        ({{ current_invoice_count }})</span
      >
      <Icon icon="mdi:chevron-down" width="11" height="11" class="filter-badge-down" />
      <DashboardList />
    </q-badge>

    <q-badge
      outline
      class="q-mr-sm q-pa-xs cursor-pointer"
      rounded
      color="primary"
      v-if="canSaveCurrentDashboard"
      data-test="dashboard-save-changes"
      @click="saveViewAs"
    >
      <span class="filter-badge-text">{{ $t('overwrite_current_view') }}</span>
    </q-badge>

    <!-- JQL-style structured predicates from QuickSearchBox. Each
         predicate gets its own badge with an × to remove it. -->
    <template v-for="(pred, pIdx) in parsedPredicates" :key="'pred-' + pIdx">
      <q-badge
        rounded
        color="primary"
        class="q-mr-sm q-pa-xs"
        :data-test="`qs-predicate-badge-${pred.field}`"
      >
        <q-icon class="filter-badge-icon" name="filter_list" />
        <span class="filter-badge-text">
          {{ predicateLabel(pred.field) }} {{ pred.op }} {{ pred.value }}
        </span>
        <q-icon
          name="close"
          color="white"
          class="cursor-pointer filter-badge-close"
          :data-test="`qs-predicate-remove-${pred.field}`"
          @click="removePredicate(pIdx)"
        />
      </q-badge>
    </template>

    <template v-for="[key, value] in quickFilterMap" :key="key">
      <template v-if="key == 'status_list'">
        <div v-for="(status, index) in value" :key="status.value">
          <q-badge rounded color="primary" class="q-mr-sm capitalize q-pa-xs">
            <q-icon class="filter-badge-icon" name="bar_chart" />
            <span class="filter-badge-text">{{ $t(status.value) }}</span>

            <q-icon
              name="close"
              color="white"
              class="cursor-pointer filter-badge-close"
              @click="removeFilter(key, Number(index), status)"
            />
          </q-badge>
        </div>
      </template>
      <template v-if="['user_id_list','group_id_list'].includes(key)">
        <div v-for="ids, index in value" :key="ids.value">
          <q-badge rounded color="primary" class="q-mr-sm capitalize q-pa-xs">
              <q-icon class="filter-badge-icon" :name="getFilterIconForKey(key)" />
              <span class="filter-badge-text">{{ $t(ids.label) }}</span>

              <q-icon
                name="close"
                color="white"
                class="cursor-pointer filter-badge-close"
                @click="removeFilter(key, Number(index))"
              />
          </q-badge>
        </div>
      </template>
      <q-badge rounded color="primary" class="q-mr-sm q-pa-xs" 
      v-else-if="!['status','status_list','tab_status','user_id','user_id_list','group_id', 'group_id_list'].includes(key) && shouldRenderKey(key)">
        <template v-if="value.hasOwnProperty('label')">
          <q-icon class="filter-badge-icon" :name="getFilterIconForKey(key)" />111
          <span class="filter-badge-text">{{ value.translation_key ? getDocTypeLabel(value) : $t(value.label) }}</span>
        </template>
        <template v-else-if="key == 'restart_filter'">
          <q-icon class="filter-badge-icon" :name="getFilterIconForKey(key)" />
          <span class="filter-badge-text">{{ $t('restart_required') }}</span>
        </template>
        <template v-else>
          <q-icon class="filter-badge-icon" :name="getFilterIconForKey(key)" />
          <span class="filter-badge-text">{{ value }}</span>
        </template>
        <q-icon
          name="close"
          color="white"
          class="cursor-pointer filter-badge-close"
          @click="removeFilter(key)"
        />
      </q-badge>
    </template>
  </div>
</template>

<script lang="ts">

import { i18n } from 'src/boot/i18n';
import { storeToRefs } from 'pinia';
import docTypeLable from 'src/utils/docTypeLable';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { defineComponent, ref, computed, watch } from 'vue';
import { selected_dashboard_pref_key } from 'src/constants';
import { notify } from 'src/components/notifications/notify';
import { useDashboardStore, useSettingStore } from 'src/store/main';
import DashboardList from 'src/pages/Dashboard/multipleListView/List.vue';
import { FIELD_CATALOG } from 'src/pages/Dashboard/Filters/searchQueryParser';
import { decideTabRestore } from 'src/pages/Dashboard/Filters/dashboardTabRestore';

export default defineComponent({
  props: {},
  mixins: [docTypeLable],
  components: {
    DashboardList,

  },
  // DOCB-11199 #3 — cached saved-preference so the watcher on
  // `personal_dashboards` can retry the restore the moment the
  // list populates (handles the race where the list fetch came
  // back empty or late and the initial mount-time lookup missed).
  data(): { savedDashboardPref: any } {
    return { savedDashboardPref: null };
  },
  async mounted() {
    try {
      this.init();
      document.addEventListener(
        'load_saved_filter_badge',
        this.loadSavedFiltersBadges,
      );
      await this.getDashboardListView();
      const settings_store = useSettingStore();
      const response = await settings_store.getUserBasedSettings(
        selected_dashboard_pref_key,
      );
      if (!response) {
        return;
      }

      // Parse the response to get the saved dashboard from settings.
      // IMPORTANT: check the PARSED dashboard, not the store's
      // `selected_dashboard` — on page load the store starts empty
      // while settings may already carry a saved dashboard.
      let savedDashboard;
      try {
        savedDashboard = JSON.parse(response);
      } catch (e) {
        this.resetViewToDefault();
        return;
      }

      // Stash the saved pref so the watcher installed below can
      // retry the restore if `personal_dashboards` repopulates later
      // (DOCB-11199 #3: the pre-fix code called `resetViewToDefault`
      // whenever the list lookup missed, which permanently wiped the
      // preference when the miss was caused by a still-empty list).
      this.savedDashboardPref = savedDashboard;
      this.attemptDashboardRestore();
    } catch (err) {
      logError(err);
    }
  },
  unmounted: function () {
    document.removeEventListener(
      'load_saved_filter_badge',
      this.loadSavedFiltersBadges,
    );
  },
  // DOCB-11199 #3 — retry the tab restore whenever the dashboard
  // list populates after mount. The mount hook snapshots the saved
  // preference into `savedDashboardPref`; this watcher re-runs the
  // decision each time the list mutates so a late-arriving fetch
  // completes the restore instead of permanently wiping the pref.
  watch: {
    personal_dashboards: {
      handler() {
        if (this.savedDashboardPref) this.attemptDashboardRestore();
      },
      deep: false,
    },
  },
  methods: {
    // Decide whether we can restore the saved dashboard right now.
    // Delegates to `decideTabRestore` which returns one of three
    // actions — restore (call selectDashboard), reset (wipe pref),
    // or wait (leave pref intact so the watcher can retry later).
    attemptDashboardRestore() {
      const decision = decideTabRestore({
        savedDashboard: this.savedDashboardPref,
        personalDashboards: this.personal_dashboards,
      });
      if (decision.action === 'restore') {
        // Pass skipColumnEvent=true to avoid duplicate dashboard
        // requests on initial load (the dashboard page already
        // fetches its own data once on mount).
        void this.selectDashboard(
          this.savedDashboardPref,
          true,
          false,
          true,
        );
        // Clear the cached pref once we've applied it so later
        // list refreshes don't re-fire the selection.
        this.savedDashboardPref = null;
      } else if (decision.action === 'reset') {
        this.resetViewToDefault();
        this.savedDashboardPref = null;
      }
      // 'wait' → leave `savedDashboardPref` set so the watcher
      // retries when personal_dashboards populates.
    },
    async saveViewAs() {
      try {
        if (!this.selected_dashboard.id) {
          return;
        }
        await this.saveChangesToDashboard();
        notify.success(this.$t('dashboard_updated_successfully'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      }
    },
    // DOCB-11199 #2 — renamed from the misleading `isKeyBlocked`
    // (which returned `true` when the key was NOT blocked, the
    // opposite of what the name suggested). Now named for what it
    // does: returns true if the key should render in the generic
    // fallback badge slot. Keeps semantics identical.
    shouldRenderKey(key: string) {
      return !this.blocked_keys.includes(key);
    },
    getFilterIconForKey(key: string) {
      let icon = '';
      switch (key) {
        case 'user_id_list':
          icon = 'person'
          break;
        case 'doc_type':
          icon = 'description';
          break;
        case 'filter':
          icon = 'filter_list';
          break;
        case 'restart_filter':
          icon = 'refresh';
          break;
        case 'date_range':
          icon = 'event';
          break;
        case 'keyword':
          icon = 'keyboard';
          break;
        case 'group_id_list':
          icon = 'group'
          break;
        default:
          break;
      }
      return icon;
    },
    async init() {
      await this.$nextTick();
      this.loadSavedFiltersBadges();
    },

    removeFilter(key: string, index?: number, status: any = null) {
      if (key == 'status_list') {
        const statusList = this.quickFilterMap.get('status_list');
        statusList.splice(index, 1);

        if (statusList.length > 0) {
          this.quickFilterMap.set('status_list', statusList);
          // Rebuild string from remaining list (no trailing comma)
          const new_string = statusList.map((s: any) => s.value).join(',');
          this.quickFilterMap.set('status', new_string);
        } else {
          this.quickFilterMap.delete('tab_status');
          this.quickFilterMap.delete('status_list');
          this.quickFilterMap.delete('status');
        }
      }
      if (key == 'keyword') {
        const event = new CustomEvent('delete_input_text', { detail: {} });
        document.dispatchEvent(event);
      }
      if (key == 'doc_type') {
        const event = new CustomEvent('remove_selected_tab', { detail: {} });
        document.dispatchEvent(event);
      }
      if (key == 'date_range') {
        this.tempFilterMap.delete(key);
        const event = new CustomEvent('clear_custom_dates', { detail: {} });
        document.dispatchEvent(event);
      }
      
      if (['user_id_list','group_id_list'].includes(key) && index !== undefined) {
        const idsList = this.quickFilterMap.get(key);
        const removedItem = idsList[index];
        idsList.splice(index, 1);

        const sringKey = key.replace('_list','');
        if(idsList.length > 0) {
          this.quickFilterMap.set(key, idsList);
          // Rebuild string from remaining list (no trailing comma)
          const new_string = idsList.map((item: any) => item.value).join(',');
          this.quickFilterMap.set(sringKey, new_string);
        } else {
          this.quickFilterMap.delete(key);
          this.quickFilterMap.delete(sringKey);
        }
      }
      if (!['status_list', 'user_id_list', 'group_id_list'].includes(key)) {
        this.quickFilterMap.delete(key);
      }
      this.triggerApplyFilters();
      this.triggerRemoveFilterByKey(key);
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },

    predicateLabel(field: string): string {
      const meta = FIELD_CATALOG.find((f) => f.name === field);
      if (meta) {
        try {
          if (meta.labelKey) return i18n.t(meta.labelKey);
          return i18n.t(meta.descriptionKey);
        } catch { return field; }
      }
      return field;
    },

    removePredicate(index: number) {
      const preds = [...this.parsedPredicates];
      preds.splice(index, 1);
      if (preds.length === 0) {
        this.quickFilterMap.delete('filter_predicates');
        this.quickFilterMap.delete('filter_predicates_connector');
      } else {
        this.quickFilterMap.set('filter_predicates', JSON.stringify(preds));
      }
      // Refresh QuickSearchBox so its inline chips stay in sync with
      // the filter state. Rebuild the raw query from remaining state.
      const rawParts: string[] = [];
      for (const p of preds) rawParts.push(`${p.field}${p.op}${p.value}`);
      const keyword = this.quickFilterMap.get('keyword');
      if (keyword) rawParts.push(keyword);
      let raw = rawParts.join(' AND ');
      // DOCB-12249 (Codex review MEDIUM #9): preserve any active
      // group-by directive when rebuilding raw_query from remaining
      // predicate badges. Without this, removing a predicate badge
      // while grouped silently clears the `Gruppieren nach :` chip
      // from the editor (the table stays grouped because
      // `selectedGroupByState` survives in the Pinia store — same
      // two-sources-of-truth desync as the original Hanna bug). The
      // directive must trail the predicates so the parser's
      // GROUP_BY_SUFFIX_RE (anchored at end-of-string) re-extracts it.
      const gb = this.dashboard_store.selectedGroupByState;
      if (gb && gb.field) {
        const directive = `group by ${gb.field}${gb.bucket ? ' ' + gb.bucket : ''}`;
        raw = raw ? `${raw} ${directive}` : directive;
      }
      document.dispatchEvent(
        new CustomEvent('load_saved_filter', { detail: { raw } }),
      );
      this.checkForDashboardUpdates();
      this.triggerApplyFilters();
    },

    async triggerRemoveFilterByKey(key: string) {
      await this.$nextTick();
      const remove_filters_event = new CustomEvent('remove_filter_by_key', {
        detail: key,
      });
      document.dispatchEvent(remove_filters_event);
    },

    loadSavedFiltersBadges() {
      const search_input_el = document.querySelector(
        '.search-input',
      ) as HTMLDivElement;
      if (!search_input_el) {
        return;
      }

      const saved_filter_badge_el = document.querySelector(
        '.saved-filter-badge',
      ) as HTMLDivElement;
      if (!saved_filter_badge_el) {
        return;
      }
      let rect = search_input_el.getBoundingClientRect();
      let left = Number(rect.left + window.pageXOffset);
      saved_filter_badge_el.style.left = left - 20 + 'px';
    },
  },
  setup() {
    const dashboard_store = useDashboardStore();
    const {
      quickFilterMap,
      tempFilterMap,
      current_invoice_count,
      personal_dashboards,
      selected_dashboard,
      dashboard_updated,
      canSaveCurrentDashboard,
    } = storeToRefs(dashboard_store);
    const {
      getDashboardListView,
      selectDashboard,
      saveChangesToDashboard,
      stripColumnDataForSave,
      populateColumnDataFromServer,
      resetViewToDefault,
      checkForDashboardUpdates,
    } = dashboard_store;
    // Keys we render with dedicated UI elsewhere, so the generic fallback
    // in the template should skip them. `filter_predicates` and its
    // connector are rendered by the dedicated per-predicate loop above.
    // `raw_query` is already visualised by the chip editor directly
    // above this row — duplicating it as one giant badge is noise.
    // `is_fulltext` / `is_vector` are backend routing hints (true/false
    // strings) with no user-meaningful label; they should never surface
    // as a badge. Without `is_vector` in this list, the Bug-28 wiring
    // (quick-search.vue:337 sets `is_vector: 'false'` on every parse)
    // made the literal string "false" appear as a filter badge — visible
    // bug seen on /dashboard.
    const blocked_keys = [
      'doc_type',
      'filter',
      'filter_predicates',
      'filter_predicates_connector',
      'raw_query',
      'is_fulltext',
      'is_vector',
    ];
    // Parse the structured-predicate JSON payload into an array for
    // the per-predicate badges. Returns [] when the key is absent or
    // malformed.
    const parsedPredicates = computed<Array<{ field: string; op: string; value: string }>>(() => {
      const raw = quickFilterMap.value.get('filter_predicates');
      if (!raw || typeof raw !== 'string') return [];
      try {
        const arr = JSON.parse(raw);
        return Array.isArray(arr) ? arr : [];
      } catch {
        return [];
      }
    });

    return {
      quickFilterMap,
      tempFilterMap,
      selected_dashboard,
      current_invoice_count,
      dashboard_updated,
      canSaveCurrentDashboard,
      saveChangesToDashboard,
      selectDashboard,
      getDashboardListView,
      personal_dashboards,
      blocked_keys: ref(blocked_keys),
      stripColumnDataForSave,
      populateColumnDataFromServer,
      resetViewToDefault,
      parsedPredicates,
      // DOCB-12249 (Codex review MEDIUM #9): exposed so removePredicate
      // can preserve the active group-by directive when rebuilding the
      // raw_query dispatched to the chip editor.
      dashboard_store,
      // DOCB-11424 (from origin/dev): exposed so chip-editor edits and
      // predicate removals can mark the dashboard dirty on every change.
      checkForDashboardUpdates,
    };
  },
});
</script>

