/**
 * Syntax highlighting for free text inside the chip editor.
 *
 * Committed predicates render as styled ChipNodes (their own colour
 * palette by category). This extension decorates the PRE-COMMIT text
 * — what the user types before space/Enter turns it into a chip —
 * so `doc_type=Invoice` reads as three coloured segments instead of
 * a flat string. Same colour language as the chips themselves:
 *
 *   field  → primary       (e.g. `doc_type`)
 *   op     → muted         (e.g. `=`, `:`, `>=`)
 *   value  → success-badge (e.g. `Invoice` — same hue as success
 *                           badges; reads as a string-literal tone)
 *   AND/OR → muted, uppercase-bold (logical glue)
 *
 * Implementation: a ProseMirror plugin that rebuilds an inline
 * DecorationSet whenever the document changes. Decorations are pure
 * view-layer styling — the underlying text is unchanged, parsing and
 * serialization are unaffected.
 */

import { Extension } from '@tiptap/core';
import { Plugin, PluginKey } from '@tiptap/pm/state';
import { Decoration, DecorationSet } from '@tiptap/pm/view';
import { CONNECTOR_WORDS } from '../searchConnectors';

// Matches one of four token kinds, in priority order:
//   1. A predicate head: field op value (all three at once, captured
//      as separate groups so each gets its own class)
//   2. Standalone AND / OR (outside a predicate)
//
// Value grammar (inner alternation, left-to-right):
//   "[^"]*"                    — double-quoted string
//   '[^']*'                    — single-quoted string
//   [^\s()]*(\([^()]*\)[+-]?N?)?
//     — bare word / ISO date / numeric, with OPTIONAL single
//       balanced `(…)` suffix (today(), now(), today()-7).
//       Stops at stray `)` so `status=ready_for_validation)` in
//       raw view leaves the trailing `)` unstyled instead of
//       painting it with the value colour.
//
// Combined into a single alternation so we can walk every text node
// once. Global so exec() yields every match.
//
// The connector branch (group 4) accepts every supported language —
// AND/UND/ET, OR/ODER/OU (DOCB-13123) — uppercased to preserve the
// existing uppercase-only "logical glue" styling, and `\b`-anchored so a
// short word like ET never paints inside a value (`budget`).
const CONNECTOR_ALTERNATION = CONNECTOR_WORDS.map((word) =>
  word.toUpperCase(),
).join('|');

export const TOKEN_RE = new RegExp(
  `([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)("[^"]*"|'[^']*'|[^\\s()]*(?:\\([^()]*\\)(?:[+-]\\d+)?)?)|\\b(${CONNECTOR_ALTERNATION})\\b`,
  'g',
);

const KEY = new PluginKey('qs-syntax-highlight');

function buildDecorations(doc: any): DecorationSet {
  const decos: Decoration[] = [];
  doc.descendants((node: any, pos: number) => {
    if (!node.isText || !node.text) return;
    const base = pos; // text node's start in the document
    const text = node.text as string;
    TOKEN_RE.lastIndex = 0;
    let m: RegExpExecArray | null;
    while ((m = TOKEN_RE.exec(text)) !== null) {
      if (m[1] && m[2]) {
        // Predicate head: field / op / value
        const fieldStart = base + m.index;
        const fieldEnd = fieldStart + m[1].length;
        decos.push(Decoration.inline(fieldStart, fieldEnd, { class: 'qs-hl-field' }));
        const opStart = fieldEnd;
        const opEnd = opStart + m[2].length;
        decos.push(Decoration.inline(opStart, opEnd, { class: 'qs-hl-op' }));
        if (m[3]) {
          const valStart = opEnd;
          const valEnd = valStart + m[3].length;
          decos.push(Decoration.inline(valStart, valEnd, { class: 'qs-hl-value' }));
        }
      } else if (m[4]) {
        const s = base + m.index;
        const e = s + m[4].length;
        decos.push(Decoration.inline(s, e, { class: 'qs-hl-connector' }));
      }
    }
  });
  return DecorationSet.create(doc, decos);
}

export const SyntaxHighlight = Extension.create({
  name: 'qsSyntaxHighlight',

  addProseMirrorPlugins() {
    return [
      new Plugin({
        key: KEY,
        state: {
          init: (_config, { doc }) => buildDecorations(doc),
          apply: (tr, old) => (tr.docChanged ? buildDecorations(tr.doc) : old),
        },
        props: {
          decorations(state) {
            return (this as any).getState(state);
          },
        },
      }),
    ];
  },
});
