<template>
  <node-view-wrapper
    as="span"
    class="qs-paren-wrapper"
    contenteditable="false"
  >
    <span class="qs-paren" :class="sideClass">{{ glyph }}</span>
  </node-view-wrapper>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { NodeViewWrapper } from '@tiptap/vue-3';

export default defineComponent({
  name: 'ParenNodeView',
  components: { NodeViewWrapper },

  props: {
    editor:      { type: Object, required: true },
    node:        { type: Object, required: true },
    decorations: { type: Array,  required: false, default: () => [] },
    selected:    { type: Boolean, required: false, default: false },
    extension:   { type: Object, required: true },
    getPos:      { type: Function, required: true },
    updateAttributes: { type: Function, required: true },
    deleteNode:  { type: Function, required: true },
  },

  setup(props) {
    const glyph = computed(() => (props.node.attrs.side === 'close' ? ')' : '('));
    const sideClass = computed(() =>
      props.node.attrs.side === 'close' ? 'qs-paren--close' : 'qs-paren--open',
    );
    return { glyph, sideClass };
  },
});
</script>
