<template>
  <q-menu
    :model-value="effectiveShowMenu"
    @update:model-value="$emit('update:showMenu', $event)"
    no-focus
    no-refocus
    no-parent-event
    :target="anchorEl"
    anchor="bottom left"
    self="top left"
    :offset="[0, 14]"
    class="field-autocomplete-menu"
    data-test="qs-ac-menu"
  >
    <q-list
      ref="listRef"
      dense
      class="qs-ac-list"
      :data-test="`qs-ac-mode-${mode}`"
    >
      <!-- ── operator mode ── -->
      <template v-if="mode === 'operator'">
        <div class="qs-ac-header">
          <q-icon name="compare_arrows" size="xs" class="q-mr-xs" />
          {{ $t('search_pick_operator') }}
        </div>
        <q-item
          v-for="op in operatorList"
          :key="op"
          clickable
          dense
          v-ripple
          @click="$emit('pick', { kind: 'operator', value: op })"
          :active="highlighted && (highlighted as any).value === op"
          class="qs-ac-item"
          :data-test="`qs-ac-operator-${operatorTestId(op)}`"
        >
          <q-item-section>
            <q-item-label>
              <span class="text-mono qs-ac-op">{{ op }}</span>
              <span
                v-if="operatorHintKey(op)"
                class="text-caption qs-ac-hint q-ml-sm"
                >{{ $t(operatorHintKey(op)) }}</span
              >
            </q-item-label>
          </q-item-section>
        </q-item>
        <!-- Presence presets: one-click `field!=""` / `field=""` shortcut
             for fields where extraction often leaves a value unset. The
             pick emits a complete predicate (kind: 'preset') instead of
             just the operator, so the parent can commit it as a single
             chip without dragging the user through a value-mode prompt. -->
        <template v-if="presencePresets.length > 0">
          <div class="qs-ac-header qs-ac-header--presence">
            <q-icon name="check_circle_outline" size="xs" class="q-mr-xs" />
            {{ $t('search_pick_presence') }}
          </div>
          <q-item
            v-for="p in presencePresets"
            :key="'preset:' + p.value"
            clickable
            dense
            v-ripple
            @click="$emit('pick', { kind: 'preset', value: p.value })"
            :active="
              highlighted &&
              (highlighted as any).kind === 'preset' &&
              (highlighted as any).value === p.value
            "
            class="qs-ac-item qs-ac-presence-item"
            :class="p.toneClass"
            :data-test="presenceTestId(p.value)"
          >
            <q-item-section>
              <q-item-label>
                <q-icon
                  :name="p.icon"
                  size="xs"
                  class="qs-ac-presence-icon q-mr-xs"
                />
                <span class="qs-ac-presence-label">{{ $t(p.labelKey) }}</span>
                <!-- Bug-2026-04-28: removed the `!=""`/`=""` operator
                     hint suffix. Business users don't read `!=` as
                     "not equal" and the SQL-y `is not null` / `is null`
                     label already conveys the intent. Power users who
                     want the literal can still type `field!=""`
                     directly into the editor — autocomplete won't
                     duplicate it. -->
              </q-item-label>
            </q-item-section>
          </q-item>
        </template>
      </template>

      <!-- ── value mode ── -->
      <template v-else-if="mode === 'value'">
        <div class="qs-ac-header">
          <q-icon name="tune" size="xs" class="q-mr-xs" />
          {{ activeFieldLabel }}
        </div>
        <div
          v-if="isBetweenValueMode"
          class="qs-ac-range"
          @click.stop
          @mousedown.stop
        >
          <label class="qs-ac-range__field">
            <span>{{ $t('search_range_from') }}</span>
            <input
              v-model="rangeStart"
              :type="rangeInputType"
              :step="rangeInputStep"
              class="qs-ac-range__input"
              data-test="qs-ac-range-from"
            />
          </label>
          <span class="qs-ac-range__sep">–</span>
          <label class="qs-ac-range__field">
            <span>{{ $t('search_range_to') }}</span>
            <input
              v-model="rangeEnd"
              :type="rangeInputType"
              :step="rangeInputStep"
              class="qs-ac-range__input"
              data-test="qs-ac-range-to"
            />
          </label>
          <button
            type="button"
            class="qs-ac-range__apply"
            :disabled="!rangeStart || !rangeEnd"
            data-test="qs-ac-range-apply"
            @click.stop="emitRangePick"
          >
            {{ $t('search_range_apply') }}
          </button>
        </div>
        <template v-else>
          <q-item
            v-for="opt in filteredValueItems"
            :key="opt.value"
            clickable
            dense
            v-ripple
            @click="
              $emit('pick', {
                kind: 'value',
                value: opt.value,
                label: opt.label,
              })
            "
            :active="highlighted && (highlighted as any).value === opt.value"
            class="qs-ac-item"
            :data-test="`qs-ac-value-${slugify(opt.value)}`"
          >
            <q-item-section>
              <q-item-label class="qs-ac-value-label">{{
                opt.label
              }}</q-item-label>
              <q-item-label caption class="text-mono qs-ac-value-sub">{{
                opt.isGroup ? 'GROUP' : opt.value
              }}</q-item-label>
            </q-item-section>
          </q-item>
        </template>
      </template>

      <!-- ── field mode (default) ── -->
      <template v-else>
        <!-- Connector entries (AND / OR) are surfaced by the parent
             when there's at least one committed predicate. Their own
             group at the top of the list so they read as logical glue
             rather than data fields. -->
        <template v-if="connectors.length > 0">
          <div class="qs-ac-header qs-ac-header--connector">
            <q-icon name="link" size="xs" class="q-mr-xs" />
            {{ $t('search_field_group_connector') }}
          </div>
          <q-item
            v-for="c in connectors"
            :key="'connector:' + c"
            clickable
            dense
            v-ripple
            @click="$emit('pick', { kind: 'connector', value: c })"
            :active="
              highlighted &&
              (highlighted as any).kind === 'connector' &&
              (highlighted as any).value === c
            "
            class="qs-ac-item"
            :data-test="`qs-ac-connector-${c.toLowerCase()}`"
          >
            <q-item-section>
              <q-item-label>
                <span class="text-mono qs-ac-connector-label">{{
                  connectorLabel(c)
                }}</span>
                <span class="text-caption qs-ac-hint q-ml-sm">{{
                  c === 'AND'
                    ? $t('search_connector_and_hint')
                    : $t('search_connector_or_hint')
                }}</span>
              </q-item-label>
            </q-item-section>
          </q-item>
        </template>

        <!-- Group-by directive suggestion. Surfaces while the user is
             still typing the directive prefix (`g`, `gr`, `gro`,
             `group`, `gruppieren`) so the autocomplete leads them into
             the directive flow instead of requiring the FULL `group `
             token before the dropdown helps. Picking this row inserts
             `group by ` and the next onUpdate flips into directive
             mode (acDirective='group_by'), which re-shows the field
             list filtered to groupable columns. -->
        <template v-if="directivePrefixVisible">
          <q-item
            clickable
            dense
            v-ripple
            @click="
              $emit('pick', {
                kind: 'directive-prefix',
                directive: 'group_by',
                value: 'group_by',
              })
            "
            :active="
              highlighted && (highlighted as any).kind === 'directive-prefix'
            "
            class="qs-ac-item qs-ac-directive-item"
            data-test="qs-ac-directive-group-by"
          >
            <q-item-section>
              <q-item-label>
                <q-icon
                  name="mdi-shape-outline"
                  size="xs"
                  class="qs-ac-directive-icon q-mr-xs"
                />
                <span class="qs-ac-directive-label">
                  {{ $t('dashboard_group_by') }}…
                </span>
                <span class="text-caption qs-ac-hint q-ml-sm">
                  {{ $t('dashboard_group_by_hint') }}
                </span>
              </q-item-label>
            </q-item-section>
          </q-item>
        </template>

        <!-- Smart Filters surface above the field rows because the
             user usually came to do a task ("show me overdue") rather
             than dimension-shop ("filter by invoice_due_date"). The
             pick emits a `smart-filter` payload that the host expands
             into a complete predicate and chips in one shot. -->
        <template v-if="smartFilters.length > 0">
          <div class="qs-ac-header qs-ac-header--smart-filter">
            <q-icon name="bolt" size="xs" class="q-mr-xs" />
            {{ $t('search_field_group_smart_filters') }}
          </div>
          <q-item
            v-for="sf in smartFilters"
            :key="'smart-filter:' + sf.name"
            clickable
            dense
            v-ripple
            @click="
              $emit('pick', {
                kind: 'smart-filter',
                smartFilter: sf,
                value: sf.name,
              })
            "
            :active="
              highlighted &&
              (highlighted as any).kind === 'smart-filter' &&
              (highlighted as any).value === sf.name
            "
            class="qs-ac-item qs-ac-smart-filter-item"
            :data-test="`qs-ac-smart-filter-${slugify(sf.name)}`"
          >
            <q-item-section>
              <q-item-label>
                <q-icon
                  :name="sf.icon"
                  size="xs"
                  class="qs-ac-smart-filter-icon q-mr-xs"
                />
                <span class="qs-ac-smart-filter-label">{{
                  $t(sf.labelKey)
                }}</span>
                <span class="text-caption qs-ac-hint q-ml-sm">{{
                  $t(sf.descriptionKey)
                }}</span>
              </q-item-label>
            </q-item-section>
          </q-item>
        </template>

        <template v-for="group in groups" :key="group.label">
          <div class="qs-ac-header" :class="group.headerClass">
            <q-icon :name="group.icon" size="xs" class="q-mr-xs" />
            {{ group.label }}
          </div>
          <q-item
            v-for="f in group.fields"
            :key="f.name"
            clickable
            dense
            v-ripple
            @click="$emit('pick', f)"
            :active="highlighted && (highlighted as any).name === f.name"
            class="qs-ac-item"
            :data-test="`qs-ac-field-${slugify(f.name)}`"
          >
            <q-item-section>
              <q-item-label>
                <span
                  class="qs-ac-field-label"
                  :class="categoryClass(f.category)"
                  >{{ fieldLabel(f) }}</span
                >
                <span
                  v-if="f.docTypes && f.docTypes.length === 1"
                  class="qs-ac-doctype-pill q-ml-sm"
                >
                  {{ prettyFieldName(f.docTypes[0]) }}
                </span>
              </q-item-label>
              <q-item-label caption class="qs-ac-sub">
                {{ fieldDescriptionText(f) }}
              </q-item-label>
            </q-item-section>
            <!-- DOCB-11199 follow-up: the per-row operator pill
                 (`f.ops[0]`) was noisy and mis-leading once the
                 field-pick flow switched to opening the full operator
                 dropdown on the next step. Dropped so the row reads
                 as "field name + description" and nothing else. -->
          </q-item>
        </template>
      </template>
    </q-list>
  </q-menu>
</template>

<script lang="ts">
import { defineComponent, PropType, ref, nextTick } from 'vue';
import { useTranslate, useTolgee } from '@tolgee/vue';
import { i18n } from 'src/boot/i18n';
import { localeConnectorLabel } from './searchConnectors';
import type { LogicalConnector } from './searchQueryParser';
import {
  FIELD_CATALOG,
  FieldMeta,
  OPERATOR_HINTS,
  SMART_FILTERS,
  UUID_RE,
  customFieldsToFieldMetas,
} from 'src/pages/Dashboard/Filters/searchQueryParser';
import {
  fieldDescription,
  fieldDisplayLabel,
  fieldMatchesQuery,
  normaliseOperatorList,
  prettyFieldName,
} from 'src/pages/Dashboard/Filters/fieldDisplay';
import { useDocTypeFieldsStore } from 'src/store/Settings/doc_type_fields.store';
import { useFieldValueSource, ValueOption } from './useFieldValueSource';

const HYBRID_FULLTEXT_FIELDS = new Set(['supplier_name']);

export default defineComponent({
  name: 'FieldAutocomplete',
  props: {
    anchorEl: { type: Object as PropType<HTMLElement | null>, default: null },
    showMenu: { type: Boolean, default: false },
    query: { type: String, default: '' },
    highlighted: {
      type: Object as PropType<FieldMeta | ValueOption | null>,
      default: null,
    },
    mode: {
      type: String as PropType<'field' | 'operator' | 'value'>,
      default: 'field',
    },
    field: { type: String, default: '' },
    operator: { type: String, default: '' },
    isFulltextEnabled: { type: Boolean, default: true },
    isVectorEnabled: { type: Boolean, default: true },
    // Connector picks (AND / OR) surfaced above the field list. The
    // parent supplies this filtered by typed query + chip presence.
    connectors: { type: Array as PropType<string[]>, default: () => [] },
    // Pre-filtered value options from the composable. When supplied,
    // we render these directly instead of re-filtering internally —
    // this keeps the dropdown in lockstep with `currentList` and
    // avoids the two filter paths drifting for `@`/`#`/`$` shortcuts.
    valueItems: { type: Array as PropType<ValueOption[]>, default: null },
  },
  emits: ['update:showMenu', 'pick', 'ghost'],

  setup() {
    // Composables and the lone template ref live in setup; everything
    // else (reactive state, computeds, watchers, lifecycle, methods)
    // belongs in the Options API blocks below.
    const { t } = useTranslate();
    const tolgee = useTolgee(['language']);
    const docFieldsStore = useDocTypeFieldsStore();
    const listRef = ref<any>(null);
    // Connector suggestions are stored canonically (AND/OR) but shown in
    // the active UI locale (DOCB-13123).
    const connectorLabel = (kind: string) =>
      localeConnectorLabel(
        kind as LogicalConnector,
        tolgee.value.getLanguage(),
      );
    return { t, docFieldsStore, listRef, connectorLabel };
  },

  data() {
    return {
      // Local input state for the date / numeric range value-mode UI.
      // Synced from props.query via the watcher below.
      rangeStart: '',
      rangeEnd: '',
    };
  },

  computed: {
    customFulltextFields(): FieldMeta[] {
      return customFieldsToFieldMetas(
        (this.docFieldsStore as any).getAllUniqueFieldsWithDocTypes,
      );
    },

    effectiveFieldCatalog(): FieldMeta[] {
      return FIELD_CATALOG.map((field) => {
        if (!HYBRID_FULLTEXT_FIELDS.has(field.name)) return field;
        return {
          ...field,
          category: this.isFulltextEnabled ? 'fulltext' : 'extended',
        };
      });
    },

    effectiveCustomFulltextFields(): FieldMeta[] {
      const customFulltextFields = Array.isArray(this.customFulltextFields)
        ? this.customFulltextFields
        : [];
      return customFulltextFields.map((field) => {
        if (!HYBRID_FULLTEXT_FIELDS.has(field.name)) return field;
        return {
          ...field,
          category: this.isFulltextEnabled ? 'fulltext' : 'extended',
        };
      });
    },

    // Smart Filters — business-language quick predicates (Overdue,
    // Assigned to me, …). Match against the user's CURRENT locale
    // matchKeywords plus the i18n-resolved label, so a German user
    // never sees Italian shortcuts and vice versa. Unknown locales
    // fall back to `en` so the picker still works for languages where
    // keywords haven't been pflegt yet.
    smartFilters() {
      const q = (this.query || '').toLowerCase().trim();
      let rawLocale = '';
      try {
        rawLocale = String((i18n as any).getLanguage?.() ?? '').toLowerCase();
      } catch {
        /* i18n not ready */
      }
      // Strip region suffix ("en-US" → "en", "de-DE" → "de") so the
      // record lookup matches the SmartFilterLocale union codes.
      const locale = (rawLocale.split('-')[0] || 'en') as
        | 'en'
        | 'de'
        | 'es'
        | 'fr'
        | 'it';
      return SMART_FILTERS.filter((sf) => {
        if (!q) return true;
        if (sf.name.toLowerCase().includes(q)) return true;
        const keywords = sf.matchKeywords[locale] ?? sf.matchKeywords.en ?? [];
        if (keywords.some((kw) => kw.toLowerCase().includes(q))) return true;
        try {
          const localized = String(
            (this.t as any)(sf.labelKey) ?? '',
          ).toLowerCase();
          if (localized && localized.includes(q)) return true;
        } catch {
          /* i18n not ready — fall through to keyword match only */
        }
        return false;
      });
    },

    // Group-by directive suggestion visibility. Shows in field-mode when
    // the typed query is empty OR matches one of the directive trigger
    // keywords (`group`, `gruppieren`, etc.). Hidden in operator/value
    // modes where it'd be irrelevant. Localised so a German user can
    // type `gru` and reach it.
    directivePrefixVisible(): boolean {
      if (this.mode !== 'field') return false;
      const q = (this.query || '').toLowerCase().trim();
      if (!q) return true;
      const triggers = ['group', 'group by', 'gruppieren', 'gruppe', 'grupp'];
      return triggers.some(
        (kw) => kw.startsWith(q) || q.startsWith(kw) || kw.includes(q),
      );
    },

    groups() {
      const q = (this.query || '').toLowerCase().trim();
      // Bare UUID → show only the `id` row so the user sees the fast
      // path is being taken instead of the confusing "No matching
      // field" message the substring filter would produce.
      const isBareUuid = !!q && UUID_RE.test(q);
      const filter = (f: FieldMeta) => {
        if (!q) return true;
        if (isBareUuid) return f.name === 'id';
        return fieldMatchesQuery(f, q, this.translate);
      };
      const standard = this.effectiveFieldCatalog.filter(
        (f) => f.category === 'standard' && filter(f),
      );
      // Custom (per-org / per-doc-type) fields can be EITHER 'extended'
      // (when their name is in the backend's SYNC_COLUMNS list — see
      // customFieldsToFieldMetas) or 'fulltext' (default for everything
      // else). Split them by category so the chip dropdown sections
      // match the chip's own coloured pill — otherwise a teal-coloured
      // field would render under the orange FULLTEXT header.
      const customByCategory =
        this.effectiveCustomFulltextFields.filter(filter);
      const customExtended = customByCategory.filter(
        (f) => f.category === 'extended',
      );
      const customFulltext = customByCategory.filter(
        (f) => f.category !== 'extended',
      );
      // Extended fields come from document_extracted_data and are
      // SQL-searchable without OpenSearch. Render each field exactly
      // once: the backend catalog decides whether a hybrid field such as
      // supplier_name appears as fulltext (licensed org) or extended
      // (non-fulltext org).
      const extendedRaw = [
        ...this.effectiveFieldCatalog.filter(
          (f) => f.category === 'extended' && filter(f),
        ),
        ...customExtended,
      ];
      const fulltextNames = new Set([
        ...this.effectiveFieldCatalog
          .filter((f) => f.category === 'fulltext')
          .map((f) => f.name),
        ...customFulltext.map((f) => f.name),
      ]);
      const extended = extendedRaw.filter((f) => !fulltextNames.has(f.name));
      const fulltext: FieldMeta[] = this.isFulltextEnabled
        ? [
            ...this.effectiveFieldCatalog.filter(
              (f) => f.category === 'fulltext' && filter(f),
            ),
            ...customFulltext,
          ]
        : [];
      const vector = this.isVectorEnabled
        ? this.effectiveFieldCatalog.filter(
            (f) => f.category === 'vector' && filter(f),
          )
        : [];
      // `ai:` is a separate routing path from `vector:` (LLM natural-
      // language parser vs. kNN). It needs fulltext on the org — not
      // the vector index — so its visibility tracks isFulltextEnabled.
      const ai: FieldMeta[] = this.isFulltextEnabled
        ? this.effectiveFieldCatalog.filter(
            (f) => f.category === 'ai' && filter(f),
          )
        : [];
      const ocr: FieldMeta[] = this.isFulltextEnabled
        ? this.effectiveFieldCatalog.filter(
            (f) => f.category === 'ocr' && filter(f),
          )
        : [];
      const result: Array<{
        label: string;
        icon: string;
        headerClass: string;
        fields: FieldMeta[];
      }> = [];
      if (standard.length) {
        result.push({
          label: this.translate('search_field_group_standard'),
          icon: 'storage',
          headerClass: 'ac-header-standard',
          fields: standard,
        });
      }
      if (extended.length) {
        result.push({
          label: this.translate('search_field_group_extended'),
          icon: 'view_column',
          headerClass: 'ac-header-extended',
          fields: extended,
        });
      }
      if (fulltext.length) {
        result.push({
          label: this.translate('search_field_group_fulltext'),
          icon: 'search',
          headerClass: 'ac-header-fulltext',
          fields: fulltext,
        });
      }
      if (vector.length) {
        result.push({
          label: this.translate('search_field_group_vector'),
          icon: 'auto_awesome',
          headerClass: 'ac-header-vector',
          fields: vector,
        });
      }
      if (ai.length) {
        result.push({
          label: this.translate('search_field_group_ai'),
          icon: 'smart_toy',
          headerClass: 'ac-header-ai',
          fields: ai,
        });
      }
      if (ocr.length) {
        result.push({
          label: this.translate('search_field_group_ocr'),
          icon: 'document_scanner',
          headerClass: 'ac-header-ocr',
          fields: ocr,
        });
      }
      return result;
    },

    operatorList(): string[] {
      const meta = this.resolveFieldMeta(this.field);
      return meta ? normaliseOperatorList(meta) : [];
    },

    activeFieldMeta(): FieldMeta | undefined {
      return this.resolveFieldMeta(this.field);
    },

    isBetweenValueMode(): boolean {
      return (
        this.mode === 'value' &&
        this.operator === 'between' &&
        ['date', 'numeric'].includes(this.activeFieldMeta?.valueType ?? '')
      );
    },

    rangeInputType(): string {
      const vt = this.activeFieldMeta?.valueType;
      return vt === 'date' ? 'date' : vt === 'numeric' ? 'number' : 'text';
    },

    rangeInputStep(): string | undefined {
      return this.activeFieldMeta?.valueType === 'numeric' ? 'any' : undefined;
    },

    activeFieldLabel(): string {
      return this.activeFieldMeta
        ? fieldDisplayLabel(this.activeFieldMeta, this.translate)
        : prettyFieldName(this.field);
    },

    // Presence presets — one-click shortcut to commit a complete
    // `field!=""` / `field=""` predicate. Only offered for fields that
    // opt in via `supportsPresence` in the catalog (most extracted /
    // user-typed columns; not enums or always-set system columns).
    presencePresets() {
      const meta = this.effectiveFieldCatalog.find(
        (f) => f.name === this.field,
      );
      if (!meta?.supportsPresence) return [];
      return [
        {
          value: '!=""',
          labelKey: 'search_op_preset_is_not_empty',
          icon: 'check_circle',
          toneClass: 'qs-ac-presence--has',
        },
        {
          value: '=""',
          labelKey: 'search_op_preset_is_empty',
          icon: 'do_not_disturb_on',
          toneClass: 'qs-ac-presence--empty',
        },
      ];
    },

    // Effective list rendered for value mode:
    //   • If the parent supplies pre-filtered `valueItems` (the
    //     composable's `currentList`), use them verbatim.
    //   • Otherwise fall back to the legacy internal filter — only
    //     the component-spec harness exercises this path now.
    filteredValueItems(): ValueOption[] {
      if (this.valueItems !== null) return this.valueItems as ValueOption[];
      // useFieldValueSource is a composable; calling it inside a
      // computed gives us reactivity without creating a brand-new
      // reactive context per call (the store subscriptions are
      // owned by the singleton inside the composable).
      const all = useFieldValueSource(this.field).options.value ?? [];
      const q = (this.query || '').toLowerCase().trim();
      if (!q) return all;
      return all.filter(
        (o) =>
          o.value.toLowerCase().includes(q) ||
          o.label.toLowerCase().includes(q),
      );
    },

    // Composite key for the "field+operator+query" watcher. A computed
    // is the Options-API-friendly source for an array-of-paths watch,
    // since Vue's watch entry in `watch:` only accepts a single
    // property name or a method-name string.
    fieldOperatorQuerySignature(): string {
      return `${this.field}|${this.operator}|${this.query}`;
    },

    // Hide the menu when the active mode has nothing to offer. The
    // parent toggles showMenu on type; we silently suppress render
    // when there are no rows so the user never sees an empty popover.
    //
    // DOCB-12249 Bug #3: the field-mode predicate must also consider
    // `directivePrefixVisible`. Without it, typing a directive trigger
    // prefix like "gr"/"gru"/"grup" (which no field name starts with)
    // closes the whole menu — even though the Group-By directive item
    // would render via the v-if="directivePrefixVisible" template
    // block. Result: the user sees "Group by" at prefix "g" then it
    // disappears at "gr", making the feature undiscoverable.
    effectiveShowMenu(): boolean {
      if (!this.showMenu) return false;
      if (this.mode === 'value')
        return this.isBetweenValueMode || this.filteredValueItems.length > 0;
      if (this.mode === 'operator')
        return this.operatorList.length > 0 || this.presencePresets.length > 0;
      return (
        this.groups.length > 0 ||
        this.connectors.length > 0 ||
        this.smartFilters.length > 0 ||
        this.directivePrefixVisible
      );
    },
  },

  watch: {
    // Sync the range inputs from the typed query whenever the field /
    // operator / query trio changes (DRFS-581: parent component
    // updates these as the user types `field between X and Y`).
    fieldOperatorQuerySignature: {
      immediate: true,
      handler() {
        if (!this.isBetweenValueMode) return;
        const q = (this.query || '').trim();
        const m = /^([^\s,]+)?(?:\s*,\s*(\S+)?)?$/.exec(q);
        this.rangeStart = m?.[1] ?? '';
        this.rangeEnd = m?.[2] ?? '';
      },
    },
    // Scroll the highlighted item into view when it changes off-screen.
    // Without this, arrow-down past the visible area advances the
    // highlight but leaves it below the fold.
    highlighted() {
      if (!this.showMenu) return;
      nextTick(() => {
        const root = ((this.listRef as any)?.$el ?? this.listRef) as
          | HTMLElement
          | undefined;
        if (!root) return;
        const active = root.querySelector(
          '.q-item--active',
        ) as HTMLElement | null;
        active?.scrollIntoView({ block: 'nearest', inline: 'nearest' });
      });
    },

    // DPT-252: defer the 19KB /field/get_field_settings_all_document_types
    // fetch until the autocomplete menu is actually open. The field catalog is
    // only needed for field-name suggestions, never for the initial dashboard
    // render, so warming it on mount only piled onto the cold-start boot
    // waterfall. showMenu is the parent's canonical open-signal (toggled on
    // type); the catalog populates reactively once the fetch lands, and the
    // empty-guard keeps it a one-shot load.
    //
    // immediate: true so a parent that mounts already-open (showMenu=true)
    // still fetches — the default is showMenu=false, which hits the early
    // return below, so this does NOT reintroduce an on-mount fetch.
    showMenu: {
      immediate: true,
      handler(open: boolean) {
        if (!open) return;
        const store = this.docFieldsStore as any;
        if (Object.keys(store.fields_doc_type_list).length === 0) {
          store.getAllDocTypeFields();
        }
      },
    },
  },

  methods: {
    translate(key: string): string {
      try {
        return String((this.t as any)(key) ?? '');
      } catch {
        // t not ready yet (Tolgee initializing) — fall back to the key
        return key;
      }
    },

    categoryClass(c: string): string {
      return c === 'standard'
        ? 'field-category-standard'
        : c === 'extended'
          ? 'field-category-extended'
          : c === 'fulltext'
            ? 'field-category-fulltext'
            : c === 'ocr'
              ? 'field-category-ocr'
              : c === 'ai'
                ? 'field-category-ai'
                : 'field-category-vector';
    },

    // Map categories to CSS classes that use design-system tokens,
    // matching the chip palette: standard = --primary, fulltext =
    // --warning, vector = --accent.
    categoryBadgeClass(c: string): string {
      return c === 'standard'
        ? 'ac-badge-standard'
        : c === 'fulltext'
          ? 'ac-badge-fulltext'
          : c === 'ocr'
            ? 'ac-badge-ocr'
            : c === 'ai'
              ? 'ac-badge-ai'
              : 'ac-badge-vector';
    },

    fieldLabel(field: FieldMeta): string {
      return fieldDisplayLabel(field, this.translate);
    },

    fieldDescriptionText(field: FieldMeta): string {
      return fieldDescription(field, this.translate);
    },

    prettyFieldName(raw: string): string {
      return prettyFieldName(raw);
    },

    // DRFS-581: catalog lookup that also falls back to the live
    // custom doc-type fields, so chips and operator pickers for
    // user-defined fields resolve their friendly title and ops.
    resolveFieldMeta(name: string): FieldMeta | undefined {
      const builtin = (this.effectiveFieldCatalog ?? []).find(
        (f) => f.name === name,
      );
      if (builtin) return builtin;
      return (this.effectiveCustomFulltextFields ?? []).find(
        (f) => f.name === name,
      );
    },

    // Resolves the Tolgee key for the short per-operator hint. Returns
    // an empty string for operators without a registered hint so the
    // template's v-if hides the column cleanly (rather than rendering a
    // bare `undefined`).
    operatorHintKey(op: string): string {
      return OPERATOR_HINTS[op] ?? '';
    },

    slugify(raw: string): string {
      return String(raw)
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/(^-|-$)/g, '');
    },

    operatorTestId(op: string): string {
      const map: Record<string, string> = {
        '=': 'eq',
        ':': 'contains',
        '>': 'gt',
        '<': 'lt',
        '>=': 'gte',
        '<=': 'lte',
        between: 'between',
      };
      return map[op] ?? this.slugify(op);
    },

    presenceTestId(value: string): string {
      return value === '!=""'
        ? 'qs-ac-preset-has-value'
        : 'qs-ac-preset-is-empty';
    },

    emitRangePick() {
      if (!this.rangeStart || !this.rangeEnd) return;
      const start = this.rangeStart;
      const end = this.rangeEnd;
      // Emit one logical range value; the chip renderer knows how to
      // display it and the serializer expands it to backend DSL.
      this.$emit('pick', {
        kind: 'range',
        start,
        end,
        value: `${start}..${end}`,
        label: `${start} – ${end}`,
      });
    },
  },
});
</script>

