<template>
  <!-- Document type fields selections -->
  <q-card class="small-popup-size">
    <q-toolbar class="text-white secondary-toolbar draggable-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{ $t('select_doc_type_fields') }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section>
      <!-- Main -->
      <div class="row no-wrap justify-around q-pt-md">
        <!-- Doc Types -->

        <div class="q-mr-md">
          <q-select
            clearable
            outlined
            dense
            v-model="selected_doc_type"
            :options="active_doc_types_sub_types_list"
            @update:model-value="docTypeSelected"
            :label="$t('document_type')"
            style="min-width: 250px"
          >
          </q-select>
        </div>

        <!-- Selected Doc type fields -->
        <div class="fields-list rounded-borders q-mr-md">
          <div
            class="box row justify-center items-center position-sticky back-white l-0 t-0 z-index-1"
            style="border-bottom: 1px solid grey"
          >
            {{ $t('fields') }}
          </div>

          <div
            class="search-column-card position-sticky l-0 back-white z-index-1"
          >
            <q-input
              dense
              autofocus
              outlined
              :placeholder="$t('search_field')"
              v-model="doc_type_search_value"
            ></q-input>
          </div>
          <div>
            <template
              v-for="(row, index) in display_doc_type_field"
              :key="index"
            >
              <div class="box">
                <q-checkbox v-model="row.selected" class="box-checkbox" />
                {{ getFieldLabelFromAllPrefixes(row) }} ({{ row?.field_name }})
              </div>
            </template>
          </div>

          <div v-if="!hasFields()" class="box row justify-center items-center">
            {{ $t('select_doc_type_with_fields') }}
          </div>
        </div>
      </div>

      <div class="row justify-end items-start q-mt-md q-mr-md">
        <q-btn
          color="primary"
          unelevated
          :label="$t('add_to_visible_columns')"
          @click="addSelectedFieldsToVisibleColumns()"
        />
      </div>
    </q-card-section>

    <q-inner-loading :showing="processing || doc_fields_processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import {
  useDashboardStore,
  useDropdownStore,
  useDocTypeFieldsStore,
} from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { isObjectEmtpy } from 'src/utils/general';
export default defineComponent({
  mixins: [displayFieldLabel],
  props: {
    visible_columns_obj_list: {} as any,
  },
  mounted() {
    this.init();
  },
  data() {
    return {
      doc_type_search_value: '',
      display_doc_type_field: [] as dynamicObj,
    };
  },
  watch: {
    doc_type_search_value(val: any) {
      this.searchDocTypeFiled(val);
    },
    fields(val: any) {
      this.display_doc_type_field = val;
    },
  },
  methods: {
    async init() {
      try {
        this.processing = true;
        await this.getAllDocTypeFields();
        this.selected_doc_type = this.active_doc_types_sub_types_list[0];
        this.docTypeSelected();
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    searchDocTypeFiled(value: any) {
      if (value) {
        const search_value = value.toLowerCase();
        this.display_doc_type_field = Object.values(this.fields).filter(
          (column: any) =>
            column.title.toLowerCase().includes(search_value) as string,
        );
        return;
      }
      this.display_doc_type_field = this.fields;
    },

    addSelectedFieldsToVisibleColumns() {
      let largest_sort_order = this.getLargestSortOrderNumber();

      let doc_type_key = '';
      if (this.selected_doc_type.hasOwnProperty('value')) {
        doc_type_key = this.selected_doc_type['value'];
      }
      if (this.selected_doc_type.hasOwnProperty('doc_type_key')) {
        doc_type_key = this.selected_doc_type['doc_type_key'];
      }

      const selected_fields = {} as dynamicObj;
      for (const key of Object.keys(this.fields)) {
        const field = this.fields[key];
        if (!field.selected) {
          continue;
        }

        selected_fields[key] = {
          name: key,
          sortable: false,
          order: ++largest_sort_order,
          translation_key: field.translation_key || key,
          doc_type_key: doc_type_key,
          title: field.title,
        };
      }

      if (Object.keys(selected_fields).length == 0) {
        notify.error('no_fields_selected');
        return;
      }

      const event = new CustomEvent('add_columns', {
        detail: { selected_fields },
      });
      document.dispatchEvent(event);
    },

    getLargestSortOrderNumber() {
      let largest_sort_order = 0;

      for (const key of Object.keys(this.visible_columns_obj_list)) {
        const column = this.visible_columns_obj_list[key] as dynamicObj;
        if (column.order > largest_sort_order) {
          largest_sort_order = column.order;
        }
      }

      return largest_sort_order;
    },

    docTypeSelected() {
      try {
        if (!this.selected_doc_type) {
          return;
        }
        this.processing = true;
        let doc_type = this.selected_doc_type['value'];
        if (this.selected_doc_type['doc_type_key'] != undefined) {
          doc_type = this.selected_doc_type['doc_type_key'];
        }
        if (typeof this.selected_doc_type == 'string') {
          doc_type = this.selected_doc_type;
        }
        this.fields = this.getFieldsByDocType(doc_type);
      } catch (err: any) {
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    hasFields() {
      return !isObjectEmtpy(this.fields);
    },
  },
  setup() {
    const dropdown_store = useDropdownStore();
    const { active_doc_types_sub_types_list } = storeToRefs(dropdown_store);

    const doc_type_fields_store = useDocTypeFieldsStore();
    const { processing: doc_fields_processing, getFieldsByDocType } =
      storeToRefs(doc_type_fields_store);
    const { getAllDocTypeFields } = doc_type_fields_store;

    return {
      getAllDocTypeFields,
      getFieldsByDocType,
      doc_fields_processing,
      processing: ref(false),
      active_doc_types_sub_types_list,
      selected_doc_type: ref(),
      fields: ref({} as dynamicObj),
    };
  },
});
</script>
