/**
 * TipTap custom inline node for a committed search predicate chip.
 *
 * Each chip is atomic (users navigate around it, not into it).
 * Clicking it expands it back to editable text. Backspace-before
 * also expands it (handled in QuickSearchBox.vue keyboard shortcuts).
 *
 * Attributes stored on the node:
 *   field    — e.g. "invoice_id"
 *   op       — e.g. "=" | ">" | ">=" | …
 *   value    — canonical form sent to the backend (e.g. user_id "u_42")
 *   label    — optional human-readable form shown in the chip UI
 *              (e.g. "Amier Khan"). Falls back to value when absent.
 *   category — "standard" | "fulltext" | "vector" | "ocr"
 *
 * Note: AND/OR connectors used to live as a `connector` attribute on
 * this node. They're now their own atomic ConnectorNode siblings so
 * they can also sit between a chip and a paren / group boundary.
 */

import { Node, mergeAttributes } from '@tiptap/core';
import { VueNodeViewRenderer } from '@tiptap/vue-3';
import type { Component } from 'vue';

export interface ChipAttrs {
  field: string;
  op: string;
  value: string;
  label?: string;
  category: 'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr';
  // `field="value"` (anchored start/end match) vs `field=value` (starts-with).
  quoted?: boolean;
}

// We accept the ChipNodeView component as a factory parameter so that
// ChipNode.ts stays free of a circular dependency on the .vue file.
export function createChipNode(ChipNodeViewComponent: Component) {
  return Node.create<never>({
    name: 'chip',

    // ── Schema ──────────────────────────────────────────────────────────
    group: 'inline',
    inline: true,
    atom: true, // cursor treats this as a single unit
    selectable: true,
    draggable: false,

    addAttributes() {
      return {
        field: { default: '' },
        op: { default: '=' },
        value: { default: '' },
        label: { default: undefined },
        category: { default: 'standard' },
        quoted: { default: false },
      };
    },

    parseHTML() {
      return [
        {
          tag: 'span[data-chip]',
          getAttrs(el) {
            const dom = el as HTMLElement;
            return {
              field: dom.getAttribute('data-field') ?? '',
              op: dom.getAttribute('data-op') ?? '=',
              value: dom.getAttribute('data-value') ?? '',
              label: dom.getAttribute('data-label') ?? undefined,
              category: dom.getAttribute('data-category') ?? 'standard',
              quoted: dom.getAttribute('data-quoted') === 'true',
            };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      return ['span', mergeAttributes(HTMLAttributes, { 'data-chip': '' })];
    },

    // DOCB-11199 follow-up: clipboard plain-text for a chip is its
    // raw-query segment — `field` + `op` + `value` — so Cmd+C over a
    // selection that spans chips produces text the query parser can
    // round-trip (`invoice_id=INV-1 AND total_amount>500`). Without
    // this, atomic nodes serialise to an empty string and the user
    // sees just the free-text fragments of their query on paste.
    renderText({ node }) {
      const { field, op, value, quoted } = node.attrs as {
        field: string;
        op: string;
        value: string;
        quoted?: boolean;
      };
      if (op === 'between') {
        const [start, end] = String(value).split('..');
        return start && end
          ? `${field} between ${start} and ${end}`
          : `${field} between ${value}`;
      }
      const v = quoted ? `"${value}"` : value;
      return `${field}${op}${v}`;
    },

    // ── Vue node view ────────────────────────────────────────────────────
    addNodeView() {
      return VueNodeViewRenderer(ChipNodeViewComponent as any);
    },
  });
}
