<template>
  <q-card style="width: 30vw">
    <q-toolbar class="text-white secondary-toolbar">
      <q-toolbar-title>
        <span class="text-weight-bold">{{
          isCreateMode() ? $t('create_new_view') : $t('edit_dashboard')
        }}</span>
      </q-toolbar-title>
      <q-btn flat round dense icon="close" v-close-popup />
    </q-toolbar>
    <q-card-section>
      <q-input
        :placeholder="$t('name')"
        v-model="listName"
        outlined
        dense
        :class="isCreateMode() || isEditMode() ? 'q-pb-lg' : ''"
      />
      <template v-if="isCreateMode() || isEditMode()">
        <span>{{ $t('who_can_see_this_dashboard') }}</span>
        <div class="column q-gutter-md q-pt-sm">
          <q-radio
            dense
            v-model="visibility"
            val="private"
            :label="$t('only_i_can_see')"
          />
          <q-radio
            dense
            v-model="visibility"
            val="all"
            :label="$t('all_user_can_see')"
          />
          <q-radio
            dense
            v-model="visibility"
            val="share"
            :label="$t('share_this_with_group_user')"
          />
        </div>

        <template v-if="visibility == 'share'">
          <q-select
            multiple
            use-chips
            clearable
            use-input
            dense
            outlined
            @filter="filterGroupsEvent"
            :options="filteredGroupList"
            :loading="groups_loading"
            emit-value
            map-options
            class="q-pt-md"
            v-model="selected_groups"
            :label="$t('groups')"
            @update:model-value="controlAllowedSelection('selected_groups')"
          />

          <q-select
            outlined
            v-model="selected_users"
            :options="filteredUsersList"
            :label="$t('select_user')"
            dense
            emit-value
            map-options
            option-value="value"
            @filter="filterUsersEvent"
            use-input
            fill-input
            multiple
            use-chips
            class="q-pt-md"
            @update:model-value="controlAllowedSelection('selected_users')"
          />
        </template>
      </template>
    </q-card-section>

    <q-card-actions align="right" class="q-px-md">
      <q-btn flat v-close-popup :label="$t('cancel')" />
      <q-btn
        color="primary"
        unelevated
        :label="$t('save')"
        @click="saveDashboard()"
        v-close-popup="closePopup"
      />
    </q-card-actions>
  </q-card>
</template>
<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { isUndefinedOrNull } from 'src/utils/general';
import { getUserDetails } from 'src/utils/UserDetails';
import { useGroupDropdownStore, useDropdownStore, useDashboardStore } from 'src/store/main';

export default defineComponent({
    async mounted() {
    await this.getGroups();
    this.$nextTick(() => {
      if (!isUndefinedOrNull(this.model)) {
        this.fillFields();
      }
    });
  },
  props: {
    model: {} as any,
  },
  methods: {
    isCreateMode() {
      return isUndefinedOrNull(this.model);
    },
    isEditMode() {
      return !!this.model?.id;
    },
    fillFields() {
      this.listName = this.model.name;
      if (!this.model.shared || this.model.shared == 'all') {
        this.visibility = !this.model.shared ? 'private' : this.model.shared;
      } else {
        this.visibility = 'share';
        const ids_list = this.model.shared.split(',');
        const uuidPattern =
          /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;

        const group_ids = ids_list.filter((item: string) =>
          uuidPattern.test(item),
        );
        const user_ids = ids_list.filter(
          (item: string) => !uuidPattern.test(item),
        );

         
        this.selected_groups = this.group_list.filter((u: { value: any }) =>
          group_ids.includes(String(u.value)),
        );
         
        this.selected_users = this.usersList.filter((u: { value: any }) =>
          user_ids.includes(String(u.value)),
        );
      }
    },

    async createRequestBody(id = '') {
      const data = new FormData();
      data.append('name', this.listName);
      if (this.getListShares()) {
        data.append('shared', this.getListShares());
      }
      data.append('customizations', await this.getCustomization());
      if (id) {
        data.append('id', id);
      }
      return data;
    },

    getListShares() {
      if (this.visibility == 'share') {
        return this.selected_users.concat(this.selected_groups).toString();
      } else if (this.visibility == 'all') {
        return this.visibility;
      } else {
        return null;
      }
    },

    async saveDashboard() {
      try {
        this.processing = true;
        if (!this.listName) {
          notify.error(this.$t('name_cannot_be_empty'));
          return;
        }
        if (this.isCreateMode()) {
          const data = await this.createRequestBody();

          if (
            this.filtered_personal_dashboards.find(
              (board) => board.name == this.listName,
            )
          ) {
            notify.error(this.$t('similar_name_already_exists'));
            return;
          }
          const response = await this.createDashboardTemplate(data);
          if (!response.success) {
            notify.error(this.$t('similar_name_already_exists'));
            return;
          }
          notify.success(this.$t('dashboard_created_successfully'));
          const event = new CustomEvent('close_create_popup', {});
          document.dispatchEvent(event);
          return;
        } else if (this.isEditMode()) {
          const matches = this.filtered_personal_dashboards.filter(
            (board) => board.name == this.listName,
          );
          if (matches.length > 0 && this.model.id != matches[0].id) {
            notify.error(this.$t('similar_name_already_exists'));
            return;
          }
        }

        const edit_data = JSON.parse(JSON.stringify(this.model));
        edit_data.name = this.listName;

        if (this.visibility == 'all') {
          edit_data.shared = 'all';
        } else if (this.visibility == 'share') {
          // Extract IDs from selected_users and selected_groups
           
          const user_ids = this.selected_users.map((u: any) =>
            typeof u === 'object' ? u.value : u,
          );
           
          const group_ids = this.selected_groups.map((g: any) =>
            typeof g === 'object' ? g.value : g,
          );
          edit_data.shared = user_ids.concat(group_ids).join(',');
        } else {
          // visibility == 'private' - set shared to empty string to clear sharing
          edit_data.shared = '';
        }

        //Build JSON
        const formData = this.buildFormDataFromJson(edit_data)
        await this.editDashboardTemplate(formData, true);
        const event = new CustomEvent('close_create_popup', {});
        document.dispatchEvent(event);
        notify.success(this.$t('dashboard_updated'));
        this.$emit('reset-dashboard-list');
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }

      // TODO: Create Backend Call
    },
    filterUsersEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredUsersList = this.usersList.filter(
            (user: any) => user.value !== getUserDetails().id,
          );
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        const currentUserId = getUserDetails().id;
        this.filteredUsersList = this.usersList.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1 && v.value !== currentUserId
        );
      });
    },
    filterGroupsEvent(val: string, update: any, abort: any) {
      if (!val) {
        update(() => {
          this.filteredGroupList = this.group_list;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredGroupList = this.group_list.filter(
          (v: any) => v.label.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    controlAllowedSelection(fieldType: string) {
      if (fieldType === 'selected_groups') {
        const maxSelection = 5;
        if (this.selected_groups.length > maxSelection) {
          this.selected_groups.splice(maxSelection);
          notify.error(this.$t('max_five_groups_to_share'));
        }
      } else if (fieldType === 'selected_users') {
        const maxSelection = 10;
        if (this.selected_users.length > maxSelection) {
          this.selected_users.splice(maxSelection);
          notify.error(this.$t('max_ten_users_to_share'));
        }
      }
    },
  },
  setup() {
    const group_store = useGroupDropdownStore();
    const filteredGroupList: any = ref(group_store.group_list);
    const { group_list, groups_loading } = storeToRefs(group_store);
    const { getGroups } = group_store;

    const dashboard_store = useDashboardStore();
    const { quickFilterMap, processing, filtered_personal_dashboards } =
      storeToRefs(dashboard_store);
    const {
      handleTableColumns,
      getOrderBy,
      buildFormDataFromJson,
      getCustomization,
      editDashboardTemplate,
      getPaginationSize,
      createDashboardTemplate,
    } = dashboard_store;

    const dropdown_store = useDropdownStore();
    const filteredUsersList: any = ref(dropdown_store.usersList);
    const { prepareUsersDropdown } = dropdown_store;
    const { usersList } = storeToRefs(dropdown_store);

    return {
      listName: ref(''),
      visibility: ref('private'),
      selected_groups: ref([] as any),
      selected_users: ref([] as any),
      processing,
      closePopup: ref(false),
      filteredGroupList,
      buildFormDataFromJson,
      filteredUsersList,
      getCustomization,
      group_list,
      groups_loading,
      getGroups,
      handleTableColumns,
      quickFilterMap,
      prepareUsersDropdown,
      createDashboardTemplate,
      editDashboardTemplate,
      usersList,
      getOrderBy,
      getPaginationSize,
      filtered_personal_dashboards,
    };
  },
});
</script>
