<template>
  <node-view-wrapper
    as="span"
    class="qs-connector-wrapper"
    contenteditable="false"
  >
    <span
      class="qs-connector-pill"
      :class="kindClass"
      data-test="qs-connector"
      :data-test-kind="node.attrs.kind"
      :title="$t('search_connector_toggle_tooltip')"
      @click.stop="toggle"
      >{{ label }}</span
    >
  </node-view-wrapper>
</template>

<script lang="ts">
import { defineComponent, computed } from 'vue';
import { NodeViewWrapper } from '@tiptap/vue-3';
import { useTolgee } from '@tolgee/vue';
import { localeConnectorLabel } from '../searchConnectors';
import type { LogicalConnector } from '../searchQueryParser';

export default defineComponent({
  name: 'ConnectorNodeView',
  components: { NodeViewWrapper },

  props: {
    editor:      { type: Object, required: true },
    node:        { type: Object, required: true },
    decorations: { type: Array,  required: false, default: () => [] },
    selected:    { type: Boolean, required: false, default: false },
    extension:   { type: Object, required: true },
    getPos:      { type: Function, required: true },
    updateAttributes: { type: Function, required: true },
    deleteNode:  { type: Function, required: true },
  },

  setup(props) {
    // The node's `kind` stays canonical AND/OR; only the visible pill
    // is localised to the active UI locale (DOCB-13123).
    const tolgee = useTolgee(['language']);
    const label = computed(() =>
      localeConnectorLabel(
        props.node.attrs.kind as LogicalConnector,
        tolgee.value.getLanguage(),
      ),
    );

    const kindClass = computed(() =>
      props.node.attrs.kind === 'OR' ? 'qs-connector--or' : 'qs-connector--and',
    );

    // Click-to-toggle. Fast interaction for flipping between AND/OR
    // without keyboard focus gymnastics — the whole point of making
    // connectors first-class atomic nodes.
    const toggle = () => {
      const next = props.node.attrs.kind === 'AND' ? 'OR' : 'AND';
      props.updateAttributes({ kind: next });
    };

    return { kindClass, toggle, label };
  },
});
</script>
