/**
 * Structural validator for the dashboard search query grammar.
 *
 * `parseSearchQuery` is deliberately lenient — it coerces garbled
 * input into something runnable so partial, mid-type queries still
 * produce SOME results instead of throwing. That leniency is the
 * wrong behaviour for the "switch to Standard view" / "chip commit"
 * paths, which need structural certainty: an unbalanced paren, a
 * dangling connector, or two adjacent predicates without a connector
 * will produce silently-wrong chip layouts (or no-op clicks on the
 * Standard-view toggle) unless we refuse up-front.
 *
 * This module is pure — no Vue, no DOM, no side effects. UI layers
 * debounce the input and decide whether to surface each error.
 *
 * Rules summary:
 *   • Predicates (`field op value`) must be separated by AND / OR.
 *   • Parentheses must balance; empty `()` is invalid.
 *   • Connectors must sit between two expression terms — never at
 *     the start, end, inside an empty paren, or back-to-back.
 *   • `field op` with no value is an incomplete predicate.
 *   • Free-text tokens (plain words, shortcut keywords like `in`,
 *     `between`, `not`, `contains`) are intentionally permissive:
 *     they can appear anywhere without triggering connector checks,
 *     so the parser-level shortcuts keep working. Users who really
 *     typed a field/op/value predicate use the strict path.
 *   • A trailing `sort <field> (asc|desc)` suffix is stripped before
 *     validation — it's orthogonal to filter grammar.
 */

import {
  tokenise,
  expandBetween,
  expandOverdueShortcut,
  expandInList,
  expandNegationPrefix,
  expandNotBetween,
} from './searchQueryParser';

export type ValidationErrorCode =
  | 'missing_connector'
  | 'leading_connector'
  | 'trailing_connector'
  | 'empty_connector_pair'
  | 'unmatched_open_paren'
  | 'unmatched_close_paren'
  | 'empty_parens'
  | 'incomplete_predicate'
  | 'trailing_garbage'
  | 'server_rejected';

export interface ValidationError {
  code: ValidationErrorCode;
  /**
   * i18n key for validator-generated errors. The UI layer resolves it
   * via `$t(messageKey, params)` so the message follows the active
   * locale. Absent only for `server_rejected`, whose text is supplied
   * pre-formatted by the backend (see `message`).
   */
  messageKey?: string;
  /** Interpolation values for `messageKey` (FormatSimple `{name}` style). */
  params?: Record<string, string>;
  /** Pre-formatted, already-localised text. Used for `server_rejected`. */
  message?: string;
  /** Zero-based token index in the tokenise() output, best-effort. */
  tokenIndex?: number;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

const CONNECTOR_RE = /^(?:AND|OR)$/i;
const PREDICATE_RE = /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)(.*)$/;
const SHORTCUT_PREFIX_RE = /^[@#$]/;
const SORT_SUFFIX_RE = /\s+sort\s+\w+\s+(?:asc|desc)\s*$/i;

// Words that legitimately follow a closed group without a connector.
// Anything else after `)` is flagged as `trailing_garbage`. Keep this
// list aligned with the shortcut syntax the parser recognises.
const SHORTCUT_KEYWORDS = new Set([
  'and', 'or',         // connectors (already classified separately; listed for safety)
  'in',                // `status in (a, b)`
  'between',           // `total_amount between 100 and 200`
  'not',               // `not status=finished`
  'is',                // `field is empty`
  'empty',             // `field is empty`
  'exists',            // `field exists`
  'contains',          // `filename contains foo`
]);

type TokenKind =
  | 'open_paren'
  | 'close_paren'
  | 'connector'
  | 'pred_complete'
  | 'pred_incomplete'
  | 'shortcut'
  | 'free_text';

interface ClassifiedToken {
  kind: TokenKind;
  raw: string;
  field?: string;
  op?: string;
  value?: string;
}

function classify(tok: string): ClassifiedToken {
  if (tok === '(') return { kind: 'open_paren', raw: tok };
  if (tok === ')') return { kind: 'close_paren', raw: tok };
  if (CONNECTOR_RE.test(tok)) return { kind: 'connector', raw: tok };
  if (SHORTCUT_PREFIX_RE.test(tok)) return { kind: 'shortcut', raw: tok };
  const m = PREDICATE_RE.exec(tok);
  if (m) {
    const [, field, op, value] = m;
    return {
      kind: value ? 'pred_complete' : 'pred_incomplete',
      raw: tok,
      field,
      op,
      value,
    };
  }
  return { kind: 'free_text', raw: tok };
}

/**
 * State of the walker. Tracks what category of token the validator
 * last saw so it can decide whether the current token is legal.
 *
 *   start       — no tokens seen yet, or just opened a `(`
 *   pred        — a complete predicate / shortcut was just consumed
 *   connector   — AND or OR was just consumed (waiting for right side)
 *   close_paren — a `)` was just consumed (treated like a predicate
 *                 for grammar purposes — needs a connector before the
 *                 next predicate)
 *   free_text   — a plain word was just consumed (permissive — does
 *                 NOT require a connector before the next token)
 */
type WalkerState = 'start' | 'pred' | 'connector' | 'close_paren' | 'free_text';

export function validateQuery(raw: string): ValidationResult {
  const errors: ValidationError[] = [];
  if (!raw.trim()) return { valid: true, errors };

  // Strip sort suffix before tokenising — it's orthogonal syntax.
  let stripped = raw.replace(SORT_SUFFIX_RE, '');

  // Apply the same shortcut-to-canonical expansions the parser runs
  // so multi-token phrases like `total_amount between 100 and 200`,
  // `status in (a, b)`, `not pred`, `overdue` reach the walker as
  // proper `pred AND pred` / `pred OR pred` shape. Without this, the
  // `and` inside BETWEEN would be read as a logical connector and
  // `100` / `200` would be stranded free-text — tripping the new
  // unresolved-connector check.
  stripped = expandOverdueShortcut(stripped);
  stripped = expandInList(stripped);
  stripped = expandNegationPrefix(stripped);
  stripped = expandNotBetween(stripped);
  stripped = expandBetween(stripped);

  // Collapse whitespace around operators so `total_amount > 5000`
  // tokenises as a single `total_amount>5000` predicate. Lookahead
  // keeps us from gluing `filename=` onto a following `AND`/`OR` —
  // that pattern is pred_incomplete and must stay visible to the
  // walker.
  stripped = stripped.replace(
    /\s*(>=|<=|!=|>|<|=|:)\s*(?!(?:AND|OR)\b)/gi,
    '$1',
  );

  const tokens = tokenise(stripped);

  let state: WalkerState = 'start';
  let parenDepth = 0;
  // A connector (AND/OR) needs a STRUCTURAL right-hand side — a
  // complete predicate, a shortcut, or a group. Free-text tokens alone
  // don't close the connector (they're always either part of a
  // multi-token shortcut phrase like `in (…)` / `between X and Y` /
  // `not pred`, or a half-typed field name). We flip this flag on when
  // a connector fires and only off when something structural lands.
  // At end-of-input, still-true means the query tail was `AND statu`
  // or similar — fire it as a `trailing_connector` error so the
  // WS-gate in quick-search.vue holds off the request.
  let connectorUnresolved = false;
  // Track the last free-text token seen in a post-connector run so we
  // can quote it in the error message.
  let lastFreeTextAfterConnector = '';

  const pushErr = (
    code: ValidationErrorCode,
    messageKey: string,
    params?: Record<string, string>,
    tokenIndex?: number,
  ): void => {
    errors.push({ code, messageKey, params, tokenIndex });
  };

  for (let i = 0; i < tokens.length; i++) {
    const t = classify(tokens[i]);

    if (t.kind === 'open_paren') {
      if (state === 'pred' || state === 'close_paren') {
        pushErr(
          'missing_connector',
          'search_error_missing_connector',
          { token: '(' },
          i,
        );
      }
      parenDepth++;
      state = 'start';
      connectorUnresolved = false;
      continue;
    }

    if (t.kind === 'close_paren') {
      if (parenDepth === 0) {
        pushErr(
          'unmatched_close_paren',
          'search_error_unmatched_close_paren',
          undefined,
          i,
        );
        // Stay in the same state; don't let depth go negative.
        continue;
      }
      if (state === 'start') {
        pushErr(
          'empty_parens',
          'search_error_empty_parens',
          undefined,
          i,
        );
      } else if (state === 'connector') {
        pushErr(
          'trailing_connector',
          'search_error_trailing_connector_paren',
          undefined,
          i,
        );
      }
      parenDepth--;
      state = 'close_paren';
      connectorUnresolved = false;
      continue;
    }

    if (t.kind === 'connector') {
      if (state === 'start') {
        pushErr(
          'leading_connector',
          'search_error_leading_connector',
          { connector: t.raw.toUpperCase() },
          i,
        );
      } else if (state === 'connector') {
        pushErr(
          'empty_connector_pair',
          'search_error_empty_connector_pair',
          undefined,
          i,
        );
      }
      state = 'connector';
      connectorUnresolved = true;
      lastFreeTextAfterConnector = '';
      continue;
    }

    if (t.kind === 'pred_complete' || t.kind === 'shortcut') {
      if (state === 'pred' || state === 'close_paren') {
        pushErr(
          'missing_connector',
          'search_error_missing_connector',
          { token: t.raw },
          i,
        );
      }
      state = 'pred';
      connectorUnresolved = false;
      continue;
    }

    if (t.kind === 'pred_incomplete') {
      if (state === 'pred' || state === 'close_paren') {
        pushErr(
          'missing_connector',
          'search_error_missing_connector',
          { token: t.raw },
          i,
        );
      }
      pushErr(
        'incomplete_predicate',
        'search_error_incomplete_predicate',
        { predicate: `${t.field}${t.op}` },
        i,
      );
      state = 'pred';
      connectorUnresolved = false;
      continue;
    }

    if (t.kind === 'free_text') {
      // Free text is permissive INSIDE shortcut phrases (`status in (a,
      // b)`, `total_amount between 100 and 200`, `not status=finished`)
      // — those tokenise as mixed free-text + pred + paren runs and the
      // parser normalises the semantics. BUT free text after a closed
      // group (`... (a OR b) for validation`) is almost always user
      // error: the stray words sit outside the grouping and don't
      // belong to any predicate. Flag it unless the word is a known
      // shortcut keyword that legitimately chains groups together.
      if (state === 'close_paren' && !SHORTCUT_KEYWORDS.has(t.raw.toLowerCase())) {
        pushErr(
          'trailing_garbage',
          'search_error_trailing_garbage',
          { token: t.raw },
          i,
        );
      }
      // Free text does NOT resolve a pending connector — it's either a
      // mid-typed field name (`AND statu`) or the head of a shortcut
      // phrase that still needs to land a structural token later.
      // `connectorUnresolved` stays as-is; the end-of-input check fires
      // if the query ended here without a structural RHS.
      if (connectorUnresolved) lastFreeTextAfterConnector = t.raw;
      state = 'free_text';
      continue;
    }
  }

  // End-of-input checks.
  if (state === 'connector') {
    pushErr(
      'trailing_connector',
      'search_error_trailing_connector',
    );
  } else if (connectorUnresolved) {
    // Query ended while the text after AND/OR was still being typed —
    // e.g. `filename:fellow AND statu` or `pred OR imported_o`. The
    // RHS never landed a structural token (pred_complete / shortcut /
    // group). Flag it so the WS-gate holds off.
    if (lastFreeTextAfterConnector) {
      pushErr(
        'trailing_connector',
        'search_error_trailing_connector_incomplete',
        { token: lastFreeTextAfterConnector },
      );
    } else {
      pushErr('trailing_connector', 'search_error_trailing_connector_generic');
    }
  }
  for (let i = 0; i < parenDepth; i++) {
    pushErr(
      'unmatched_open_paren',
      'search_error_unmatched_open_paren',
    );
  }

  return {
    valid: errors.length === 0,
    errors,
  };
}
