<template>
  <q-dialog
    :model-value="modelValue"
    @update:model-value="$emit('update:modelValue', $event)"
    :maximized="$q.screen.lt.md"
  >
    <q-card
      class="search-help-card"
      :style="$q.screen.lt.md ? '' : 'width: 92vw; max-width: 1000px; height: 88vh;'"
    >
      <!-- Header -->
      <q-card-section class="row items-center q-py-sm shc-header">
        <div class="shc-header__text">
          <div class="text-h6 q-mb-none">{{ $t('search_help_title') }}</div>
          <div class="text-caption shc-muted">
            {{ $t('search_help_syntax_intro') }}
          </div>
        </div>
        <q-space />
        <q-btn icon="close" flat round dense v-close-popup />
      </q-card-section>

      <!-- Free-text filter across operators, examples, fields, shortcuts.
           Filtering everything through a single query keeps the user
           oriented: typing "due" narrows both the "Fulltext" tab and
           the shortcuts table simultaneously. -->
      <div class="shc-search">
        <q-input
          v-model="search"
          :placeholder="$t('search_help_search_placeholder')"
          dense
          outlined
          clearable
          debounce="120"
          class="shc-search__input"
        >
          <template #prepend>
            <q-icon name="search" size="xs" />
          </template>
        </q-input>
      </div>

      <q-separator />

      <!-- Unified scroll body: operators, tabs, and panels share one
           scroll container so the bottom section isn't squeezed into a
           tiny viewport. Tabs stick to the top of the scroll area so
           they remain accessible no matter how far the user scrolls. -->
      <div class="shc-body">
        <!-- Operators reference. Always rendered (unless the search query
             filters it empty) because '=' vs ':' vs comparison operators
             are the first thing a beginner needs — putting them behind a
             tab buried the lede. -->
        <section v-if="filteredOperators.length" class="shc-operators">
          <div class="shc-section__title">
            {{ $t('search_help_operators_title') }}
          </div>
          <div class="shc-op-grid">
            <template v-for="op in filteredOperators" :key="op.sym">
              <code class="shc-code shc-code--op">{{ op.sym }}</code>
              <div class="shc-op-body">
                <div class="shc-op-name">{{ op.name }}</div>
                <div class="shc-op-desc">{{ op.desc }}</div>
              </div>
              <code class="shc-code shc-code--muted shc-op-example">{{ op.example }}</code>
            </template>
          </div>
        </section>

        <q-separator v-if="filteredOperators.length" />

        <q-tabs
          v-model="tab"
          dense
          no-caps
          align="left"
          class="shc-tabs"
          active-color="primary"
          indicator-color="primary"
        >
          <q-tab name="always" :label="$t('search_help_tab_always')" />
          <q-tab v-if="isFulltextEnabled" name="fulltext" :label="$t('search_help_tab_fulltext')" />
          <q-tab name="shortcuts" :label="$t('search_help_tab_shortcuts')" />
          <q-tab v-if="isVectorEnabled" name="vector" :label="$t('search_help_tab_vector')" />
          <!-- OCR tab — searches the fulltext_text_v1 companion index
               (ai_text, pages[].pageText/customPageText). Triggered by
               the `ocr:` prefix; routes to the heavy-text index built
               by the documents/text split. Visibility tracks the
               fulltext capability since the companion index only
               exists when fulltext is enabled. -->
          <q-tab v-if="isFulltextEnabled" name="ocr" :label="$t('search_help_tab_ocr')" />
          <!-- AI tab — separate from Vector. Routes through the LLM
               ai_query_parser (Ollama in fulltextsearch), NOT through
               kNN. Visibility tracks isFulltextEnabled — ai: needs
               fulltext on the org, not the vector index. -->
          <q-tab v-if="isFulltextEnabled" name="ai" :label="$t('search_help_tab_ai')" />
        </q-tabs>

        <q-separator />

        <q-tab-panels v-model="tab" animated class="shc-panels">
        <!-- Always available examples — these work regardless of the
             workspace's capability flags. -->
        <q-tab-panel name="always" class="q-pa-md">
          <section v-if="filteredAlwaysFields.length" class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_standard_fields') }}
            </div>
            <div class="shc-fieldlist">
              <code
                v-for="f in filteredAlwaysFields"
                :key="f"
                class="shc-code"
              >{{ f }}</code>
            </div>
          </section>

          <section v-if="filteredAlwaysExamples.length" class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_tab_always') }}
            </div>
            <div class="shc-grid">
              <template v-for="ex in filteredAlwaysExamples" :key="ex.query">
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-grid__code">{{ ex.query }}</code>
                  <q-btn
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[ex.query] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(ex.query)"
                  >
                    <q-tooltip>
                      {{ copied[ex.query] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ ex.desc }}</div>
              </template>
            </div>
          </section>

          <div
            v-if="!filteredAlwaysFields.length && !filteredAlwaysExamples.length"
            class="shc-empty"
          >
            {{ $t('search_help_no_results') }}
          </div>
        </q-tab-panel>

        <q-tab-panel v-if="isFulltextEnabled" name="fulltext" class="q-pa-md">
          <section v-if="filteredFulltextFields.length" class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_calc_fields') }}
            </div>
            <div class="shc-fieldlist">
              <code
                v-for="f in filteredFulltextFields"
                :key="f"
                class="shc-code"
              >{{ f }}</code>
              <code v-if="!search" class="shc-code shc-code--muted">… any extracted field</code>
            </div>
          </section>

          <section v-if="filteredFulltextExamples.length" class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_tab_fulltext') }}
            </div>
            <div class="shc-grid">
              <template v-for="ex in filteredFulltextExamples" :key="ex.query">
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-grid__code">{{ ex.query }}</code>
                  <q-btn
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[ex.query] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(ex.query)"
                  >
                    <q-tooltip>
                      {{ copied[ex.query] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ ex.desc }}</div>
              </template>
            </div>
          </section>

          <div
            v-if="!filteredFulltextFields.length && !filteredFulltextExamples.length"
            class="shc-empty"
          >
            {{ $t('search_help_no_results') }}
          </div>
        </q-tab-panel>

        <q-tab-panel name="shortcuts" class="q-pa-md">
          <section class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_shortcuts_title') }}
            </div>
            <div v-if="filteredShortcuts.length" class="shc-shortcut-grid">
              <div class="shc-shortcut-grid__head">{{ $t('search_help_shortcut_col_shortcut') }}</div>
              <div class="shc-shortcut-grid__head">{{ $t('search_help_shortcut_col_equivalent') }}</div>
              <div class="shc-shortcut-grid__head">{{ $t('search_help_shortcut_col_description') }}</div>
              <template v-for="s in filteredShortcuts" :key="s.shortcut">
                <code class="shc-code">{{ s.shortcut }}</code>
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-code--muted">{{ s.equivalent }}</code>
                  <!-- Two rows have no single-query equivalent: the
                       sort directive (shown as `—`) and the multi-
                       example field-prefix demo (`A / B / C`). Both
                       would just copy garbage — hide the button. -->
                  <q-btn
                    v-if="s.equivalent && s.equivalent !== '—' && !s.equivalent.includes(' / ')"
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[s.equivalent] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(s.equivalent)"
                  >
                    <q-tooltip>
                      {{ copied[s.equivalent] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ s.desc }}</div>
              </template>
            </div>
            <div v-else class="shc-empty">
              {{ $t('search_help_no_results') }}
            </div>
          </section>
        </q-tab-panel>

        <q-tab-panel v-if="isVectorEnabled" name="vector" class="q-pa-md">
          <section class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_vector_title') }}
            </div>
            <div class="shc-para">{{ $t('search_help_vector_body') }}</div>
            <div v-if="filteredVectorExamples.length" class="shc-grid">
              <template v-for="ex in filteredVectorExamples" :key="ex.query">
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-grid__code">{{ ex.query }}</code>
                  <q-btn
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[ex.query] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(ex.query)"
                  >
                    <q-tooltip>
                      {{ copied[ex.query] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ ex.desc }}</div>
              </template>
            </div>
            <div v-else class="shc-empty">
              {{ $t('search_help_no_results') }}
            </div>
          </section>
        </q-tab-panel>

        <!-- OCR panel — searches the OCR/AI text companion index
             (fulltext_text_v1: ai_text, pages[].pageText,
             customPageText). Use `ocr:` to find words that appear
             inside the document body (everything the OCR engine
             extracted), not just the structured metadata. Mirrors
             the Vector panel shape so the visual rhythm matches. -->
        <q-tab-panel v-if="isFulltextEnabled" name="ocr" class="q-pa-md">
          <section class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_ocr_title') }}
            </div>
            <div class="shc-para">{{ $t('search_help_ocr_body') }}</div>
            <div v-if="filteredOcrExamples.length" class="shc-grid">
              <template v-for="ex in filteredOcrExamples" :key="ex.query">
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-grid__code">{{ ex.query }}</code>
                  <q-btn
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[ex.query] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(ex.query)"
                  >
                    <q-tooltip>
                      {{ copied[ex.query] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ ex.desc }}</div>
              </template>
            </div>
            <div v-else class="shc-empty">
              {{ $t('search_help_no_results') }}
            </div>
          </section>
        </q-tab-panel>

        <!-- AI panel — natural-language queries routed through the LLM
             ai_query_parser. Mirrors the Vector panel shape but the
             examples are filter-extraction-style ("invoices from Ruiz
             over 1000") rather than similarity-style ("frozen food"). -->
        <q-tab-panel v-if="isFulltextEnabled" name="ai" class="q-pa-md">
          <section class="shc-section">
            <div class="shc-section__title">
              {{ $t('search_help_ai_title') }}
            </div>
            <div class="shc-para">{{ $t('search_help_ai_body') }}</div>
            <div v-if="filteredAiExamples.length" class="shc-grid">
              <template v-for="ex in filteredAiExamples" :key="ex.query">
                <div class="shc-grid__code-wrap">
                  <code class="shc-code shc-grid__code">{{ ex.query }}</code>
                  <q-btn
                    flat
                    dense
                    round
                    size="xs"
                    class="shc-copy-btn"
                    :icon="copied[ex.query] ? 'check' : 'content_copy'"
                    :aria-label="$t('copy_to_clipboard')"
                    @click="copyQuery(ex.query)"
                  >
                    <q-tooltip>
                      {{ copied[ex.query] ? $t('copied') : $t('copy_to_clipboard') }}
                    </q-tooltip>
                  </q-btn>
                </div>
                <div class="shc-grid__desc">{{ ex.desc }}</div>
              </template>
            </div>
            <div v-else class="shc-empty">
              {{ $t('search_help_no_results') }}
            </div>
          </section>
        </q-tab-panel>
        </q-tab-panels>
      </div>

      <q-separator />
      <div class="shc-capabilities" data-test="shc-capabilities">
        <span class="shc-capabilities__label">
          {{ $t('search_help_workspace_capabilities') }}
        </span>
        <span class="shc-capabilities__item">
          <q-icon
            :name="isFulltextEnabled ? 'check_circle_outline' : 'block'"
            :class="isFulltextEnabled ? 'shc-capabilities__check' : 'shc-capabilities__cross'"
            size="14px"
          />
          Fulltext
        </span>
        <span class="shc-capabilities__sep">·</span>
        <span class="shc-capabilities__item">
          <q-icon
            :name="isVectorEnabled ? 'check_circle_outline' : 'block'"
            :class="isVectorEnabled ? 'shc-capabilities__check' : 'shc-capabilities__cross'"
            size="14px"
          />
          Vector
        </span>
        <q-space />
        <router-link
          v-if="isOrgAdmin"
          to="/settings/fulltext"
          class="shc-capabilities__link"
        >
          {{ $t('search_help_open_settings') }}
        </router-link>
      </div>
      <q-separator />
      <q-card-actions align="right">
        <q-btn flat :label="$t('close')" v-close-popup />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent, ref, computed, watch } from 'vue';
import { storeToRefs } from 'pinia';
import { i18n } from 'src/boot/i18n';
import { useSettingStore } from 'src/store/main';
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { supportsCapability, type CapabilityRequirement } from './search-help-capability';

type Example = { query: string; desc: string; requires?: CapabilityRequirement };
type Shortcut = {
  shortcut: string;
  equivalent: string;
  desc: string;
  requires?: CapabilityRequirement;
};
type Operator = { sym: string; name: string; desc: string; example: string };

export default defineComponent({
  name: 'SearchHelpDialog',
  props: {
    modelValue: { type: Boolean, default: false },
  },
  emits: ['update:modelValue'],
  setup() {
    const settings_store = useSettingStore();
    const { org_based_settings } = storeToRefs(settings_store);
    const auth_token_store = useAuthTokenStore();
    const isOrgAdmin = computed(() => auth_token_store.isAdmin());

    const tab = ref<
      'always' | 'fulltext' | 'shortcuts' | 'vector' | 'ocr' | 'ai'
    >('always');
    const search = ref('');

    const isTruthy = (val: unknown): boolean => {
      const s = String(val ?? '').toLowerCase().trim();
      return s === 'true' || s === '1' || s === 'yes' || s === 'on';
    };

    const isFulltextEnabled = computed(() =>
      isTruthy(org_based_settings.value?.OPENSEARCH_ENABLED),
    );
    // Vector is a sub-setting of Fulltext — see quick-search.vue's
    // isVectorEnabled for the full rationale. The dialog's own computed
    // mirrors that gate so the vector tab disappears when the parent
    // capability is off, regardless of the raw OPENSEARCH_VECTOR_* flags.
    const isVectorEnabled = computed(() => {
      if (!isFulltextEnabled.value) return false;
      const s = org_based_settings.value || {};
      return (
        isTruthy(s.OPENSEARCH_VECTOR_DOCUMENTS) ||
        isTruthy(s.OPENSEARCH_VECTOR_INVOICES) ||
        isTruthy(s.OPENSEARCH_VECTOR_ATTACHMENTS)
      );
    });

    const supports = (requires?: 'fulltext' | 'vector') =>
      supportsCapability(requires, {
        fulltext: isFulltextEnabled.value,
        vector: isVectorEnabled.value,
      });

    watch(
      () => [isFulltextEnabled.value, isVectorEnabled.value, tab.value] as const,
      ([ft, vec, current]) => {
        if (current === 'fulltext' && !ft) tab.value = 'always';
        if (current === 'vector' && !vec) tab.value = 'always';
        if (current === 'ocr' && !ft) tab.value = 'always';
        if (current === 'ai' && !ft) tab.value = 'always';
      },
      { immediate: true },
    );

    // Operators — the fundamental grammar. Kept as a flat catalogue
    // so the search filter (below) can match against any field.
    const operators = computed<Operator[]>(() => [
      { sym: '=', name: i18n.t('search_help_op_exact_name'), desc: i18n.t('search_help_op_exact_desc'), example: 'status=finished' },
      { sym: ':', name: i18n.t('search_help_op_contains_name'), desc: i18n.t('search_help_op_contains_desc'), example: 'filename:rechnung' },
      { sym: '>', name: i18n.t('search_help_op_gt_name'), desc: i18n.t('search_help_op_gt_desc'), example: 'total_amount>5000' },
      { sym: '<', name: i18n.t('search_help_op_lt_name'), desc: i18n.t('search_help_op_lt_desc'), example: 'pages<5' },
      { sym: '>=', name: i18n.t('search_help_op_gte_name'), desc: i18n.t('search_help_op_gte_desc'), example: 'invoice_due_date>=today()' },
      { sym: '<=', name: i18n.t('search_help_op_lte_name'), desc: i18n.t('search_help_op_lte_desc'), example: 'invoice_due_date<=today()+7' },
      { sym: '!=', name: i18n.t('search_help_op_neq_name'), desc: i18n.t('search_help_op_neq_desc'), example: 'status!=finished' },
      { sym: '" "', name: i18n.t('search_help_op_quote_name'), desc: i18n.t('search_help_op_quote_desc'), example: 'filename="invoice"' },
      { sym: 'AND / OR', name: i18n.t('search_help_op_combine_name'), desc: i18n.t('search_help_op_combine_desc'), example: 'status=error OR status=open' },
      { sym: '( )', name: i18n.t('search_help_op_group_name'), desc: i18n.t('search_help_op_group_desc'), example: '(status=a OR status=b) AND filename:X' },
    ]);

    // Standard / fulltext field chips — rendered as pills in the tabs.
    const alwaysFields = [
      'id',
      'filename',
      'invoice_id',
      'purchase_order',
      'status',
      'doc_type',
      'assigned_to',
      'created_on',
      'last_modified_on',
    ];
    const fulltextFields = [
      'invoice_due_date',
      'discount_due_date',
      'ap_assignment_code',
      'total_amount',
      'tax_amount',
      'net_amount',
      'currency',
      'vendor_id',
    ];

    // Examples. The previous `imported_on between today()-30 and today()`
    // entry was removed — the backend doesn't accept that combination
    // and shipping it as an advertised example set up users for failure.
    const alwaysExamples = computed<Example[]>(() => [
      { query: 'id=069e22da-ada6-7106-8000-c496f9541dbc', desc: i18n.t('search_help_example_id') },
      { query: 'invoice_id=INV-2026-03-00284', desc: i18n.t('search_help_example_invoice_id') },
      { query: 'invoice_id=INV-1 OR invoice_id=INV-2', desc: i18n.t('search_help_example_or') },
      { query: 'imported_on>=today()-30', desc: i18n.t('search_help_example_relative_date') },
    ]);

    const fulltextExamples = computed<Example[]>(() => [
      { query: 'purchase_order:"PO 42"', desc: i18n.t('search_help_example_phrase'), requires: 'fulltext' },
      { query: 'total_amount>5000', desc: i18n.t('search_help_example_amount'), requires: 'fulltext' },
      { query: 'invoice_due_date>=2026-04-21', desc: i18n.t('search_help_example_date'), requires: 'fulltext' },
      { query: 'ap_assignment_code=VEND8821', desc: i18n.t('search_help_example_ap'), requires: 'fulltext' },
      { query: 'status=finished AND total_amount>5000', desc: i18n.t('search_help_example_and'), requires: 'fulltext' },
      { query: 'ap_assignment_code!=""', desc: i18n.t('search_help_example_not_empty'), requires: 'fulltext' },
      { query: 'ap_assignment_code=""', desc: i18n.t('search_help_example_empty'), requires: 'fulltext' },
      { query: 'invoice_due_date>=today() AND invoice_due_date<=today()+7', desc: i18n.t('search_help_example_due_this_week'), requires: 'fulltext' },
      { query: 'invoice_due_date between 2026-01-01, 2026-04-30', desc: i18n.t('search_help_example_between_dates'), requires: 'fulltext' },
      { query: 'total_amount between 1000, 5000', desc: i18n.t('search_help_example_between_amounts'), requires: 'fulltext' },
    ]);

    const shortcuts = computed<Shortcut[]>(() => [
      { shortcut: 'total_amount gt 5000', equivalent: 'total_amount>5000', desc: i18n.t('search_help_shortcut_operator_aliases'), requires: 'fulltext' },
      { shortcut: 'due_date > today', equivalent: 'due_date>today()', desc: i18n.t('search_help_shortcut_bare_date'), requires: 'fulltext' },
      { shortcut: 'imported_on this_week', equivalent: 'imported_on>=today()-7 AND imported_on<=today()', desc: i18n.t('search_help_shortcut_period') },
      { shortcut: 'ap_assignment_code is empty', equivalent: 'ap_assignment_code=""', desc: i18n.t('search_help_shortcut_presence'), requires: 'fulltext' },
      { shortcut: 'status:open', equivalent: 'status=ready_for_validation', desc: i18n.t('search_help_shortcut_status') },
      { shortcut: 'total_amount not between 100, 200', equivalent: 'total_amount<100 OR total_amount>200', desc: i18n.t('search_help_shortcut_not_between'), requires: 'fulltext' },
      { shortcut: 'status in (finished, error)', equivalent: 'status=finished OR status=error', desc: i18n.t('search_help_shortcut_in_list') },
      { shortcut: 'not status=finished', equivalent: 'status!=finished', desc: i18n.t('search_help_shortcut_negation') },
      { shortcut: 'filename contains rechnung', equivalent: 'filename:rechnung', desc: i18n.t('search_help_shortcut_contains') },
      { shortcut: 'total_amount > 5k', equivalent: 'total_amount>5000', desc: i18n.t('search_help_shortcut_currency'), requires: 'fulltext' },
      { shortcut: 'overdue', equivalent: 'invoice_due_date<today() AND status!=finished', desc: i18n.t('search_help_shortcut_overdue'), requires: 'fulltext' },
      { shortcut: '#INV-1234', equivalent: 'invoice_id:INV-1234', desc: i18n.t('search_help_shortcut_field_prefixes') },
      { shortcut: '@User', equivalent: 'assigned_to:User', desc: i18n.t('search_help_shortcut_field_prefixes') },
      { shortcut: '$5000+', equivalent: 'total_amount>=5000', desc: i18n.t('search_help_shortcut_field_prefixes_money'), requires: 'fulltext' },
    ]);

    const vectorExamples = computed<Example[]>(() => [
      { query: 'vector: frozen food invoices from Ruiz', desc: i18n.t('search_help_vector_example_1'), requires: 'vector' },
      { query: 'vector: shipping delays with Hamburg port', desc: i18n.t('search_help_vector_example_2'), requires: 'vector' },
      { query: 'vector: invoices about office supplies', desc: i18n.t('search_help_vector_example_3'), requires: 'vector' },
    ]);

    // OCR queries hit the fulltext_text_v1 companion index that holds
    // ai_text + pages[].pageText/customPageText — i.e. everything the
    // OCR engine extracted from the document body. Capability is
    // 'fulltext' because the companion only exists alongside the
    // documents index, NOT 'vector' (no embeddings involved).
    const ocrExamples = computed<Example[]>(() => [
      { query: 'ocr: Versandkosten', desc: i18n.t('search_help_ocr_example_1'), requires: 'fulltext' },
      { query: 'ocr: "purchase order PO-12345"', desc: i18n.t('search_help_ocr_example_2'), requires: 'fulltext' },
      { query: 'ocr: Hamburg AND doc_type=INVOICE', desc: i18n.t('search_help_ocr_example_3'), requires: 'fulltext' },
      { query: 'ocr: IBAN', desc: i18n.t('search_help_ocr_example_4'), requires: 'fulltext' },
    ]);

    // AI queries go through fulltextsearch's LLM parser — filter-
    // extraction style, not kNN similarity. Capability requirement
    // is 'fulltext', NOT 'vector'.
    const aiExamples = computed<Example[]>(() => [
      { query: 'ai: invoices from Ruiz over 1000 last quarter', desc: i18n.t('search_help_ai_example_1'), requires: 'fulltext' },
      { query: 'ai: overdue invoices waiting on approval', desc: i18n.t('search_help_ai_example_2'), requires: 'fulltext' },
      { query: 'ai: shipping documents from Hamburg last month', desc: i18n.t('search_help_ai_example_3'), requires: 'fulltext' },
    ]);

    // ── Search filtering ───────────────────────────────────────────
    // A single query threads through every list. Matching is a plain
    // case-insensitive substring check — good enough at this catalogue
    // size, and avoids surprising fuzzy misses.
    const normalisedQuery = computed(() =>
      (search.value || '').toLowerCase().trim(),
    );

    const matches = (...parts: (string | undefined)[]): boolean => {
      const q = normalisedQuery.value;
      if (!q) return true;
      return parts.some((p) => !!p && p.toLowerCase().includes(q));
    };

    const filteredOperators = computed(() =>
      operators.value.filter((o) => matches(o.sym, o.name, o.desc, o.example)),
    );
    const filteredAlwaysFields = computed(() =>
      alwaysFields.filter((f) => matches(f)),
    );
    const filteredFulltextFields = computed(() =>
      fulltextFields.filter((f) => matches(f)),
    );
    const filteredAlwaysExamples = computed(() =>
      alwaysExamples.value.filter((e) => matches(e.query, e.desc)),
    );
    const filteredFulltextExamples = computed(() =>
      fulltextExamples.value
        .filter((e) => supports(e.requires))
        .filter((e) => matches(e.query, e.desc)),
    );
    const filteredShortcuts = computed(() =>
      shortcuts.value
        .filter((s) => supports(s.requires))
        .filter((s) => matches(s.shortcut, s.equivalent, s.desc)),
    );
    const filteredVectorExamples = computed(() =>
      vectorExamples.value
        .filter((e) => supports(e.requires))
        .filter((e) => matches(e.query, e.desc)),
    );
    const filteredOcrExamples = computed(() =>
      ocrExamples.value
        .filter((e) => supports(e.requires))
        .filter((e) => matches(e.query, e.desc)),
    );
    const filteredAiExamples = computed(() =>
      aiExamples.value
        .filter((e) => supports(e.requires))
        .filter((e) => matches(e.query, e.desc)),
    );

    // Per-snippet "just copied" flag, keyed by the query string. Cleared
    // after a short delay so the icon reverts from check → content_copy;
    // plain object + reactive tracking is enough here (no Set/Map needed).
    const copied = ref<Record<string, boolean>>({});
    const copyQuery = async (query: string) => {
      try {
        await navigator.clipboard.writeText(query);
      } catch {
        // Clipboard API unavailable (non-secure context, permissions).
        // Fall back to a temp textarea so the help dialog still works
        // on http://localhost-less previews and older browsers.
        const ta = document.createElement('textarea');
        ta.value = query;
        ta.style.position = 'fixed';
        ta.style.opacity = '0';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
      }
      copied.value = { ...copied.value, [query]: true };
      setTimeout(() => {
        const next = { ...copied.value };
        delete next[query];
        copied.value = next;
      }, 1200);
    };

    return {
      tab,
      search,
      isFulltextEnabled,
      isVectorEnabled,
      isOrgAdmin,
      filteredOperators,
      filteredAlwaysFields,
      filteredFulltextFields,
      filteredAlwaysExamples,
      filteredFulltextExamples,
      filteredShortcuts,
      filteredVectorExamples,
      filteredOcrExamples,
      filteredAiExamples,
      copied,
      copyQuery,
    };
  },
});
</script>

