import { ref, computed, Ref } from 'vue';
import { storeToRefs } from 'pinia';
import { FIELD_CATALOG, FieldMeta } from './searchQueryParser';
import { useDocStatusDropdownStore } from 'src/store/Dropdown/doc_status.store';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import { useGroupDropdownStore } from 'src/store/Dropdown/groups.store';
import { useSettingStore } from 'src/store/Settings/setting.store';
import { useDocTypeFieldsStore } from 'src/store/Settings/doc_type_fields.store';
import { useFieldValuesSettingsStore } from 'src/store/Settings/field_values.store';
import { CONSTANTS, group_permission_activated } from 'src/constants';
import { toBoolPreference } from 'src/utils/preferenceBool';
import { i18n } from 'src/boot/i18n';

export interface ValueOption {
  value: string;
  label: string;
  // assigned_to groups — the UI shows "GROUP" instead of the UUID. Named
  // isGroup (not `kind`) to avoid clashing with the autocomplete row-type
  // `kind` ('value' | 'operator' | …) in useQuickSearchAutocomplete.
  isGroup?: boolean;
}

function groupFilterEnabled(): boolean {
  try {
    return toBoolPreference(useSettingStore().org_based_settings?.[group_permission_activated]);
  } catch {
    return false;
  }
}

function pushUniqueOptions(
  seen: Set<string>,
  out: ValueOption[],
  source: { value: string; label: string }[] | null | undefined,
  isGroup = false,
): void {
  for (const item of source ?? []) {
    const key = String(item.value ?? '');
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push({
      value: item.value,
      label: item.label,
      ...(isGroup ? { isGroup: true } : {}),
    });
  }
}

function seedGroupDropdown() {
  const groupStore = useGroupDropdownStore();
  // Guard on the store's own load flags, not group_list.length: getGroups()
  // clears group_list at the start of the fetch, so a length check refires it
  // on every keystroke while the first request is still in flight.
  if (!groupStore.groups_loaded && !groupStore.groups_loading) {
    void groupStore.getGroups();
  }
  return groupStore;
}

