// Invoice sub-type value picker. The backend stores the canonical English
// value ("Cost Invoice" / "Purchase Invoice"), but the dashboard renders it
// through the same i18n keys docTypeLable.displayDocType() uses
// (cost_invoice → "Kostenrechnung", purchase_invoice → "Einkaufsrechnung").
// Mirror the PO_MATCH_STATUS_OPTIONS labelKey pattern so the dropdown shows
// the localized label while the chip ships the canonical value — and so
// matchValueInOptions() maps a typed localized label back to the canonical
// value (search-by-what-you-see). Intentionally non-exhaustive: rarer stored
// values (edoc variants, "Project Invoice", …) aren't pickable here and
// render as their raw canonical string — the filter still works if typed.
const INVOICE_SUB_TYPE_OPTIONS: { value: string; labelKey: string }[] = [
  { value: 'Cost Invoice', labelKey: 'cost_invoice' },
  { value: 'Purchase Invoice', labelKey: 'purchase_invoice' },
];

// Resolve a {value, labelKey} static source to ValueOption[] at render time.
// i18n.t runs per computed-eval so labels track the active locale (a
// module-level precompute would freeze them at import). Shared by the
// po_match_status and invoice_sub_type pickers below.
const localizeOptions = (
  opts: { value: string; labelKey: string }[],
): ValueOption[] =>
  opts.map((o) => ({ value: o.value, label: i18n.t(o.labelKey) }));

// DOCB-13124: find the LOV list name an enum field is bound to, the same
// `list_of_values` the validation form reads off the field config. The
// configs are keyed by doc type → field groups → rows → fields; the first
// matching field that names a list wins (a field uses one list across types).
const resolveLovListName = (
  fieldsDocTypeList: Record<string, any> | undefined,
  fieldName: string,
): string => {
  for (const groups of Object.values(fieldsDocTypeList ?? {})) {
    if (!Array.isArray(groups)) continue;
    for (const group of groups) {
      const rows = (group as any)?.rows;
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (!Array.isArray(row)) continue;
        for (const field of row) {
          if (field?.field_name === fieldName && field?.list_of_values) {
            return String(field.list_of_values);
          }
        }
      }
    }
  }
  return '';
};

// Lazily fetch a LOV list's values once. The field-values store keys lists by
// name; `getValuesForList` fills the slot's `lov_items` map. Guard on whether
// `lov_items` is already present (not merely on the name being known): a name
// registered by `getLists()` carries list metadata but NO `lov_items`, so a
// name-presence guard would skip the fetch forever AND leave a slot whose
// select-list read throws on `Object.entries(undefined)`. Keying off
// `lov_items` both triggers the fetch in that case and stops it refiring once
// the values are seeded (the caller reads this from a per-keystroke computed).
const seedLovListOnce = (lovStore: any, listName: string): void => {
  if (!listName) return;
  const slot = lovStore.list_of_values?.[listName];
  if (slot && slot.lov_items !== undefined) return;
  try {
    lovStore.addNameToLovList(listName);
    void lovStore.getValuesForList(listName);
  } catch (err) {
    logError(err);
  }
};

// LOV items ship value/label as arrays of per-org/per-language translations:
//   { value: [{ translated_value, language, is_default, org_id }, …], label: […] }
// The `value` is what documents are stored with — language-independent and
// shared across orgs — so we take the canonical (default / English) entry. The
// `label` is what the user sees, so we take the entry whose `language` matches
// the selected UI locale (the all-zeros "default" org applies to all orgs, so
// language — not org_id — is what distinguishes e.g. de "PI Invoice").
const LOV_SYSTEM_ORG = '00000000-0000-0000-0000-000000000000';

const hasText = (t: any): boolean =>
  !!t && typeof t.translated_value === 'string' && t.translated_value.length > 0;

const primaryLang = (lang: any): string =>
  String(lang ?? '')
    .toLowerCase()
    .split(/[-_]/)[0];

// Canonical value documents store with — language-independent. The all-zeros
// system-default org holds it (shared across orgs); fall back to English, then
// any default, then first.
const pickCanonicalValue = (translations: any): string => {
  const list = Array.isArray(translations) ? translations : [];
  const found =
    list.find((t: any) => hasText(t) && t.org_id === LOV_SYSTEM_ORG) ??
    list.find((t: any) => hasText(t) && primaryLang(t.language) === 'en') ??
    list.find((t: any) => hasText(t) && t.is_default) ??
    list.find(hasText);
  return found?.translated_value ?? '';
};

// Display label in the selected language: language match → default → first.
const pickLocalizedLabel = (translations: any, locale: string): string => {
  const list = Array.isArray(translations) ? translations : [];
  const want = primaryLang(locale);
  const found =
    list.find((t: any) => hasText(t) && primaryLang(t.language) === want) ??
    list.find((t: any) => hasText(t) && t.is_default) ??
    list.find(hasText);
  return found?.translated_value ?? '';
};

// Map a LOV list's raw `lov_items` map to {canonical value, localized label}.
const mapLovItemsToOptions = (
  lovItems: any,
  locale: string,
): ValueOption[] =>
  Object.values(lovItems ?? {})
    .map((item: any) => {
      const value = pickCanonicalValue(item?.value);
      return { value, label: pickLocalizedLabel(item?.label, locale) || value };
    })
    .filter((o) => o.value);

const PRIORITY: ValueOption[] = [1, 2, 3, 4, 5].map((n) => ({
  value: String(n),
  label: String(n),
}));

const CURRENCY_SHORT: ValueOption[] = [
  'EUR',
  'USD',
  'GBP',
  'CHF',
  'JPY',
  'CAD',
  'AUD',
  'SEK',
  'NOK',
  'DKK',
  'PLN',
].map((c) => ({ value: c, label: c }));

const RELATIVE_DATES: ValueOption[] = [
  { value: 'today()', label: 'today' },
  { value: 'today()-1', label: 'yesterday' },
  { value: 'today()+1', label: 'tomorrow' },
  { value: 'today()-7', label: '7 days ago' },
  { value: 'today()-30', label: '30 days ago' },
  { value: 'today()+7', label: 'in 7 days' },
  { value: 'today()+30', label: 'in 30 days' },
];

// Fields whose typed/pasted display label must be normalised to a
// canonical backend value (user id, sub-org id, status code, …) before
// serialisation — i.e. every field that has a value source below. Keep in
// sync with the branches in `useFieldValueSource`. Consumers (e.g. the
// paste handler in QuickSearchBox) use this to AVOID short-circuiting the
// `tryCommit → normaliseValue` path for these fields.
const VALUE_SOURCE_FIELDS: ReadonlySet<string> = new Set([
  'status',
  'doc_type',
  'invoice_sub_type',
  'assigned_to',
  'created_by',
  'last_saved_by',
  'sub_org_name',
  'priority',
  'currency',
  'po_match_status',
]);

export function fieldHasValueSource(field: string): boolean {
  // Parser accepts field names case-insensitively, so lowercase first.
  const lower = field.toLowerCase();
  if (VALUE_SOURCE_FIELDS.has(lower)) return true;
  // Date fields offer relative-date options (today(), yesterday, …).
  const meta = FIELD_CATALOG.find((f) => f.name === lower);
  return meta?.valueType === 'date';
}

export function useFieldValueSource(field: string): {
  options: Ref<ValueOption[]>;
  loading: Ref<boolean>;
} {
  const loading = ref(false);
  const meta = FIELD_CATALOG.find((f) => f.name === field) as
    | FieldMeta
    | undefined;

  // Store-backed: status
  if (field === 'status') {
    const statusStore = useDocStatusDropdownStore();
    const { status_list } = storeToRefs(statusStore);
    // Seed the store lazily on first request. Other components call
    // getStatusesList() in their own mount, but the chip dropdown
    // shouldn't depend on any particular page being mounted first.
    if (!status_list.value || status_list.value.length === 0) {
      // CONSTANTS.all === 'All' (capitalised), not 'all'; passing a
      // bare lowercase string silently produces an empty list.
      statusStore.getStatusesList(CONSTANTS.all);
    }
    return {
      options: computed<ValueOption[]>(() =>
        (status_list.value ?? []).map((s: any) => ({
          value: s.value,
          label: s.label,
        })),
      ),
      loading: ref(false),
    };
  }

  // Store-backed: doc_type
  if (field === 'doc_type') {
    const dropdown = useDropdownStore();
    const { doc_type_list } = storeToRefs(dropdown);
    return {
      options: computed<ValueOption[]>(() =>
        (doc_type_list.value ?? []).map((d: any) => ({
          value: d.value,
          label: d.label,
        })),
      ),
      loading: ref(false),
    };
  }

  // Store-backed: user fields
  if (
    field === 'assigned_to' ||
    field === 'created_by' ||
    field === 'last_saved_by'
  ) {
    const dropdown = useDropdownStore();
    const { usersList } = storeToRefs(dropdown);
    // DOCB-11199 follow-up: auto-seed the users list the same way
    // `status` does above. Without this, a chip re-commit path
    // (tryCommit → normaliseValue → matchValueInOptions) couldn't
    // resolve a display label when the user arrived via a persisted
    // raw_query like `assigned_to=2` without first going through
    // the @-autocomplete that side-loads the dropdown.
    if (!usersList.value || usersList.value.length === 0) {
      // prepareUsersDropdown is async (fetches /users) but we don't
      // need to await it here — the computed below reads the store
      // reactively, so the label resolves on the next tick after
      // the fetch lands.
      void dropdown.prepareUsersDropdown();
    }

    // DOCB-12459: only `assigned_to` can target a group; `created_by` /
    // `last_saved_by` have no group column. Gated by GROUP_PERMISSION_ACTIVATED
    // so orgs without groups see users only. Group ids are UUIDs, so they never
    // collide with integer user ids in the dedupe below; the backend routes
    // `assigned_to=<uuid>` to d.assigned_to_group.
    const withGroups = field === 'assigned_to' && groupFilterEnabled();
    const groupList = withGroups
      ? storeToRefs(seedGroupDropdown()).group_list
      : ref([] as ValueOption[]);

    return {
      // Dedupe by id. prepareUsersDropdown pushes one entry per
      // userStore.allUsers iteration; if that source ever yields the
      // same user twice (observed in practice — see "David Rohany
      // 1711" appearing twice in the @-search dropdown), we would
      // surface the duplicate verbatim to the user. A Set on the
      // stringified value is cheap and keeps the first-seen row.
      options: computed<ValueOption[]>(() => {
        const seen = new Set<string>();
        const out: ValueOption[] = [];
        pushUniqueOptions(seen, out, usersList.value);
        pushUniqueOptions(seen, out, groupList.value, true);
        return out;
      }),
      loading: ref(false),
    };
  }

  // Store-backed: sub_org_name
  if (field === 'sub_org_name') {
    const dropdown = useDropdownStore();
    const { subOrgList } = storeToRefs(dropdown);
    // DPT-252: lazy-load on first use. This list used to be eager-warmed by
    // import-multi-invoice.vue's mounted() hook (an 11KB call on every
    // dashboard boot); that warm was removed, so self-load here — mirroring
    // the assigned_to branch above. getSubOrgsList() is idempotent (guards on
    // subOrgList.length), so the computed below resolves once the fetch lands.
    if (!subOrgList.value || subOrgList.value.length === 0) {
      void dropdown.getSubOrgsList();
    }
    return {
      options: computed<ValueOption[]>(() =>
        (subOrgList.value ?? []).map((s: any) => ({
          value: s.value,
          label: s.label,
        })),
      ),
      loading: ref(false),
    };
  }

  // Store-backed: invoice_sub_type (DOCB-13124). The selectable sub types are
  // customer-configured as a List of Values — different orgs define different
  // / more sub types — so the built-in pair below is only a fallback. Mirror
  // the validation form (FormElementEnumInput): resolve the field's LOV list
  // name from the doc-type field config and read that list via the
  // field-values store. Because we read the SAME list the form writes from,
  // each option's `value` matches what is stored on the document, so filtering
  // by a picked sub type works (search-by-what-you-see).
  if (field === 'invoice_sub_type') {
    const docTypeFields = useDocTypeFieldsStore();
    const lovStore = useFieldValuesSettingsStore();
    const dropdown = useDropdownStore();
    // Seed the per-doc-type field configs so the LOV list name is resolvable.
    if (
      !docTypeFields.processing &&
      Object.keys(docTypeFields.fields_doc_type_list ?? {}).length === 0
    ) {
      void docTypeFields.getAllDocTypeFields();
    }
    return {
      options: computed<ValueOption[]>(() => {
        let result: ValueOption[] = [];
        try {
          const listName = resolveLovListName(
            docTypeFields.fields_doc_type_list,
            'invoice_sub_type',
          );
          if (listName) {
            seedLovListOnce(lovStore, listName);
            result = mapLovItemsToOptions(
              lovStore.list_of_values?.[listName]?.lov_items,
              dropdown.getSelectedLanguage(),
            );
          }
        } catch (err) {
          // A malformed/partly-seeded LOV slot must never break the value
          // dropdown — fall through to the built-in pair below.
          logError(err);
        }
        // Always keep the dropdown populated — never throw, never empty.
        return result.length
          ? result
          : localizeOptions(INVOICE_SUB_TYPE_OPTIONS);
      }),
      loading: ref(false),
    };
  }

  // Static sources
  const options = computed<ValueOption[]>(() => {
    if (field === 'priority') return PRIORITY;
    if (field === 'currency') return CURRENCY_SHORT;
    if (field === 'po_match_status') {
      return localizeOptions(PO_MATCH_STATUS_OPTIONS);
    }
    if (meta?.valueType === 'date') return RELATIVE_DATES;
    return [];
  });
  return { options, loading };
}
