<template>
  <div
    ref="rootRef"
    class="qs-box"
    :class="{ 'qs-box--focus': focused }"
    data-test="qs-box"
    @click="focusEditor"
  >
    <!-- Prepend slot — an icon shown before the editor content
         (capability indicator, search icon, etc.). Renders fixed-size
         so the chip row stays vertically centred. -->
    <div v-if="$slots.prepend" class="qs-box__prepend" @click.stop>
      <slot name="prepend" />
    </div>

    <!-- Editor content + placeholder share the same flex slot so the
         placeholder text starts right after the caret (not underneath
         it). Placeholder is only rendered when the editor is empty.
