    <div ref="editorSlotRef" class="qs-editor-slot">
      <!-- Wrapper around the TipTap editor. The fillable `search-input`
           test hook lives on the inner ProseMirror contenteditable (set
           via `editorProps.attributes` in initEditor) — NOT here — so
           Playwright `.fill()` / `.type()` target a real editable element
           instead of this non-fillable wrapper div. -->
      <editor-content
        :editor="editor"
        class="qs-editor-content"
        data-test="qs-editor-content"
      />
      <span
        v-if="!hasContent && placeholder"
        class="qs-placeholder"
        aria-hidden="true"
        >{{ placeholder }}</span
      >
    </div>

    <!-- DRFS-534: "Press Enter to search" affordance. Visible whenever
         the user has unapplied changes and either no autocomplete is
         active, or the dropdown has no highlighted suggestion (in which
         case Enter falls through to fire instead of picking). Rendered
         as a ghost button so it reads as clickable; clicking it fires
         the same submit path as pressing Enter. -->
    <q-btn
      v-if="showPendingFireIcon"
      flat
      dense
      round
      size="sm"
      icon="keyboard_return"
      class="qs-box__pending-fire"
      aria-label="Press Enter to search"
      data-test="qs-pending-fire"
      @click.stop="submitFromIcon"
    >
      <q-tooltip anchor="bottom middle" self="top middle">
        Press Enter to search
      </q-tooltip>
    </q-btn>

    <!-- Append slot — inline toolbar buttons (copy, filters, help, …)
         rendered at the right edge of the input. Click events stopped
         from focusing the editor so buttons work without stealing the
         caret. -->
    <div v-if="$slots.append" class="qs-box__append" @click.stop>
      <slot name="append" />
    </div>

    <!-- Invisible marker positioned at the current caret DOMRect so the
         autocomplete dropdown follows what the user is actually typing
         (instead of anchoring to the whole box and appearing far from
         the caret). Coordinates are refreshed from ProseMirror's
         `view.coordsAtPos(from)` on every selection/content update.
         The ghost-text child overrides the parent's `visibility:hidden`
         so the suffix renders at the caret without affecting the q-menu
         anchor geometry below it. -->
    <div ref="caretAnchorRef" class="qs-caret-anchor" aria-hidden="true">
      <!-- Google-style ghost-text suffix. Shows the completion the
           highlighted suggestion would provide on TAB; rendered in a
           lighter colour so it reads as a "shadow" of the canonical
           field/value name. `pointer-events: none` so it never blocks
           clicks on the editor or chips, and `aria-hidden` because the
           dropdown's highlighted row already announces the suggestion
           to assistive tech. The trailing "↹" key-glyph reinforces
           that TAB is the trigger (parallels Google search hints). -->
      <span v-if="ghostText" class="qs-ghost-text">
        <span class="qs-ghost-text__suffix">{{ ghostText }}</span>
        <span class="qs-ghost-text__hint" aria-hidden="true">↹ Tab</span>
      </span>
    </div>

    <!-- Autocomplete dropdown anchored to the editor-slot wrapper so
         the dropdown's LEFT edge starts exactly where the input text
         begins (right after the prepend icon area). Stays put as the
         caret moves. Ghost-text suffix inside `.qs-caret-anchor` still
         follows the caret for the Google-style preview. -->
    <FieldAutocomplete
      v-if="editorSlotRef"
      :anchor-el="editorSlotRef"
      :show-menu="acOpen"
      :mode="acMode"
      :field="acField"
      :operator="acOp"
      :query="acQuery"
      :highlighted="highlighted"
      :is-fulltext-enabled="isFulltextEnabled"
      :is-vector-enabled="isVectorEnabled"
      :connectors="connectorSuggestions"
      :value-items="valueItems"
      @pick="onAutocompletePick"
      @update:show-menu="acOpen = $event"
    />
  </div>
</template>

<script lang="ts">
import {
  defineComponent,
  ref,
  computed,
  getCurrentInstance,
  shallowRef,
  nextTick,
} from 'vue';
import { Editor, EditorContent, Extension } from '@tiptap/vue-3';
import Document from '@tiptap/extension-document';
import Paragraph from '@tiptap/extension-paragraph';
import Text from '@tiptap/extension-text';
import { i18n } from 'src/boot/i18n';
import {
