  promoteBareKeyword,
  tokenise,
  isMultiTokenStringField,
  normaliseSmartQuotes,
  FIELD_CATALOG,
  VECTOR_PREFIX_CAPTURE_RE,
  customFieldsToFieldMetas,
  stripGroupByDirective,
  extractGroupBy,
} from './searchQueryParser';
import { shouldCommit } from './quickSearchTokens';
import {
