  fieldHasValueSource,
} from './useFieldValueSource';
import { matchValueInOptions } from './matchValueInOptions';
import FieldAutocomplete from './FieldAutocomplete.vue';
import { useDocTypeFieldsStore } from 'src/store/Settings/doc_type_fields.store';
import { createChipNode } from './tiptap/ChipNode';
import ChipNodeView from './tiptap/ChipNodeView.vue';
import { createParenNode } from './tiptap/ParenNode';
import ParenNodeView from './tiptap/ParenNodeView.vue';
import { createConnectorNode } from './tiptap/ConnectorNode';
import ConnectorNodeView from './tiptap/ConnectorNodeView.vue';
import { SyntaxHighlight } from './tiptap/SyntaxHighlight';
