import { useUserStore } from 'src/store/User/user_details.store';

// ── Helpers ───────────────────────────────────────────────────────────────────

function labelFor(field: string): string {
  const meta = FIELD_CATALOG.find((f) => f.name === field);
  if (meta) {
    try {
      if (meta.labelKey) return i18n.t(meta.labelKey);
      return i18n.t(meta.descriptionKey);
    } catch {
      return field;
    }
  }
  return field;
}

type ChipCategory =
  | 'standard'
  | 'extended'
  | 'fulltext'
  | 'vector'
  | 'ocr'
  | 'ai';

function categoryOf(field: string): ChipCategory {
  return FIELD_CATALOG.find((f) => f.name === field)?.category ?? 'standard';
}

function stripOuterQuotes(value: string): string {
  const quoted =
    (value.startsWith('"') && value.endsWith('"')) ||
    (value.startsWith("'") && value.endsWith("'"));
  return quoted ? value.slice(1, -1) : value;
}

// Resolve a pasted chip's colour category from the static catalog OR the
// hydrated custom doc-type fields. `categoryOf` alone falls back to
// `standard`, which would mis-route a custom FULLTEXT field that carries
// no `is_fulltext` flag (OBO-46 / Codex review).
function resolvePasteChipCategory(field: string): ChipCategory | undefined {
  const fieldLc = field.toLowerCase();
  const fromCatalog = FIELD_CATALOG.find((f) => f.name === fieldLc)?.category;
  if (fromCatalog) return fromCatalog;
  try {
    return customFieldsToFieldMetas(
      useDocTypeFieldsStore().getAllUniqueFieldsWithDocTypes,
    ).find((f) => f.name.toLowerCase() === fieldLc)?.category;
  } catch {
    return undefined;
  }
}

/** Walk TipTap document and serialize to a query string.
 *
 *  Connectors (AND/OR) are their own atomic nodes in document order,
 *  so no pending-prev-chip trickery needed — we just emit each node
 *  in place and let `joinQueryParts` decide spacing around parens.
 */
/** Quote a chip value when it contains whitespace so the parser
 *  treats it as a single token. Empty values become `""` so presence
 *  chips keep their explicit form (see 2026-04-28 presence-chip bug).
 *  Numeric / id / date strings pass through unquoted to keep the raw
 *  query compact. Embedded `"` characters are not supported in chip
 *  values — `unquoteIfNeeded` only strips outer quotes, so escaping
 *  here would break the round-trip. */
function quoteValueIfNeeded(value: string, quoted = false): string {
  if (value === '') return '""';
  // `quoted` carries the user's explicit `field="value"` intent (anchored
  // start/end match) — always re-emit quotes so it survives the round-trip,
  // even for single-word values that wouldn't otherwise be quoted.
  if (quoted || /\s/.test(value)) return `"${value}"`;
  return value;
}

/** Bug-2026-05-25 #80 (Codex v15 [high]): single source of truth for
 *  serialising one chip's (field, op, value) back to canonical query
 *  text.  Both the full-document serialiser (`editorDocToQueryString`)
 *  and the edit-mode chip-expander (Backspace/ArrowLeft) MUST format a
 *  chip identically — otherwise a `not between` chip serialised one way
 *  but expanded the other corrupts the query on edit
 *  (`imported_onnot between2026-05-21..2026-05-24`).  BETWEEN variants
 *  emit their keyword form with proper spacing + `and` separator; every
 *  other op is the glued `field${op}${value}` shape. */
function chipToQueryText(
  field: string,
  op: string,
  value: string,
  quoted = false,
): string {
  if (op === 'between' || op === 'not between') {
    const [start, end] = String(value).split('..');
    if (start && end) {
      return `${field} ${op} ${start} and ${end}`;
    }
  }
  return `${field}${op}${quoteValueIfNeeded(value, quoted)}`;
}

function editorDocToQueryString(editor: Editor): string {
  const parts: string[] = [];
  editor.state.doc.descendants((node) => {
    if (node.type.name === 'chip') {
      const { field, op, value, quoted } = node.attrs as {
        field: string;
        op: string;
        value: string;
        quoted?: boolean;
      };
      // Directive chip: serialised as natural-language `group by <field>
      // [bucket]` so parseSearchQuery's extractGroupBy lifts it back into
      // `groupByOverride` instead of pushing it through the predicate
      // stream (where the backend would reject the unknown `group_by`
      // field name).
      if (field === 'group_by') {
        const [gbField, bucket] = value.split('|');
        parts.push(`group by ${gbField}${bucket ? ' ' + bucket : ''}`);
        return;
      }
      // Bug-2026-05-25 #70/#80: BETWEEN + NOT-BETWEEN + presence +
      // plain ops all route through the shared `chipToQueryText`
      // formatter so the full-document serialiser and the edit-mode
      // expander stay byte-identical.  Presence chips (`!= ""` /
      // `= ""`) keep their explicit quoted empty-string form via
      // `quoteValueIfNeeded` inside the helper (2026-04-28 bug).
      parts.push(chipToQueryText(field, op, value, quoted));
    } else if (node.type.name === 'connector') {
      const kind = (node.attrs as { kind?: string }).kind ?? 'AND';
      parts.push(kind);
    } else if (node.type.name === 'paren') {
      const side = (node.attrs as { side?: string }).side;
      parts.push(side === 'close' ? ')' : '(');
    } else if (node.type.name === 'text' && node.text) {
      const t = node.text.trim();
      if (t) parts.push(t);
    }
  });
  return joinQueryParts(parts);
}

// Join parts with spaces EXCEPT around parens: `(foo` stays `(foo`
// and `foo)` stays `foo)`. Keeps the raw string compact and matches
// how the user typed it.
function joinQueryParts(parts: string[]): string {
  let out = '';
  for (let i = 0; i < parts.length; i++) {
    const p = parts[i];
    if (i === 0) {
      out = p;
      continue;
    }
    const prev = parts[i - 1];
    const noSpaceBefore = p === ')';
    const noSpaceAfter = prev === '(';
    if (noSpaceBefore || noSpaceAfter) {
      out += p;
    } else {
      out += ' ' + p;
    }
  }
  return out.trim();
}

/** Get the plain text content that precedes the caret (within the paragraph). */
function textBeforeCaret(editor: Editor): string {
  const { selection, doc } = editor.state;
  const { from } = selection;
  let text = '';
  // Walk back from the selection start accumulating text until we hit a non-text node.
  doc.nodesBetween(0, from, (node, pos) => {
    if (node.type.name === 'text') {
      const textNode = node.text ?? '';
      const visibleChars = Math.max(0, Math.min(textNode.length, from - pos));
      text += textNode.slice(0, visibleChars);
    } else if (
      node.type.name === 'chip' ||
      node.type.name === 'connector' ||
      node.type.name === 'paren'
    )
      text = ''; // reset at every atomic node boundary
  });
  return text;
}

function commitRange(
  editor: Editor,
  trigger: string | null,
): { text: string; from: number; to: number } {
  if (trigger === 'Enter') return textInCurrentSegment(editor);
  const text = textBeforeCaret(editor);
  const caret = editor.state.selection.from;
  return { text, from: caret - text.length, to: caret };
}

function textInCurrentSegment(editor: Editor): {
  text: string;
  from: number;
  to: number;
} {
  const { from, to } = currentSegmentBounds(editor);
  return { text: collectTextBetween(editor, from, to), from, to };
}

function currentSegmentBounds(editor: Editor): { from: number; to: number } {
  const { doc, selection } = editor.state;
  const caret = selection.from;
  // Stay INSIDE the caret's textblock. Defaulting to the whole doc
  // (0 .. content.size) made the replace range span the paragraph's
  // open/close tokens, so deleting it forced ProseMirror to recreate
  // the block and a stray empty paragraph survived — the "extra line"
  // Hanna reported on DOCB-12360.
  const $caret = doc.resolve(caret);
  let from = $caret.start();
  let to = $caret.end();
  doc.nodesBetween(from, to, (node, pos) => {
    if (!isAtomicNode(node)) return;
    const nodeEnd = pos + node.nodeSize;
    if (nodeEnd <= caret && nodeEnd > from) from = nodeEnd;
    if (pos >= caret && pos < to) to = pos;
  });
  return { from, to };
}

function collectTextBetween(editor: Editor, from: number, to: number): string {
  let text = '';
  editor.state.doc.nodesBetween(from, to, (node, pos) => {
    if (node.type.name !== 'text') return;
    const nodeText = node.text ?? '';
    const start = Math.max(0, from - pos);
    const end = Math.min(nodeText.length, to - pos);
    text += nodeText.slice(start, end);
  });
  return text;
}

function isAtomicNode(node: { type: { name: string } }): boolean {
  const name = node.type.name;
  return name === 'chip' || name === 'connector' || name === 'paren';
}

/** Insert a chip node replacing the given text range.
 *  `value` is the canonical form that round-trips to the backend
 *  (e.g. user_id "u_42"). `label` is the optional display form shown
 *  in the chip UI (e.g. "Amier Khan") — stored alongside the value so
 *  the rendered chip stays human-readable while the query string stays
 *  backend-correct.
 *
 *  When a connector is supplied, we insert a sibling connector NODE
 *  right before the chip (atomic, toggleable button). This is the
 *  single place that "AND/OR before a chip" is realised in the doc —
 *  the chip itself no longer carries a connector attribute.
 */
function insertChip(
  editor: Editor,
  from: number,
  to: number,
  field: string,
  op: string,
  value: string,
  connector: 'AND' | 'OR' | undefined,
  label?: string,
  // Bug 2026-05-05: when the user picks a field from a SPECIFIC
  // dropdown section (e.g. an extended field listed both under
  // EXTRACTED and FULLTEXT), the chip's CSS color must follow that
  // section choice, not just the field's static FIELD_CATALOG entry.
  // Allowing the caller to pass an explicit category honours the
  // user's intent — falls back to the catalog lookup when omitted
  // (typed-in chips, paste rehydration, raw_query restore).
  category?: 'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai',
  quoted?: boolean,
) {
  const content: any[] = [];
  if (connector) {
    content.push({ type: 'connector', attrs: { kind: connector } });
  }
  content.push({
    type: 'chip',
    attrs: {
      field,
      op,
      value,
      label,
      category: category ?? categoryOf(field),
      quoted: quoted ?? false,
    },
  });
  const docSize = editor.state.doc.content.size;
  const safeFrom = Math.max(0, Math.min(from, docSize));
  const safeTo = Math.max(safeFrom, Math.min(to, docSize));
  editor
    .chain()
    .focus()
    .deleteRange({ from: safeFrom, to: safeTo })
    .insertContentAt(safeFrom, content)
    .run();
}

/** Determine whether the document contains at least one chip node. */
function hasChips(editor: Editor): boolean {
  let found = false;
  editor.state.doc.descendants((node) => {
    if (node.type.name === 'chip') {
      found = true;
      return false;
    }
  });
  return found;
}

// ── Extension: SmartCommit + BackspaceExpand + KeyboardSubmit ─────────────────

function createSearchExtension(
  onCommit: (trigger: string) => boolean,
  onExpand: () => boolean,
  onSubmit: () => void,
  onAcKeydown: (key: string) => boolean,
) {
  return Extension.create({
    name: 'searchBehaviours',
    addKeyboardShortcuts() {
      return {
        Enter: () => {
          // DRFS-534: autocomplete pick wins; otherwise commit any
          // typed predicate to a chip AND fire submit. Commit success
          // no longer suppresses the fire — Enter always submits unless
          // it was consumed by the dropdown.
          if (onAcKeydown('Enter')) return true;
          onCommit('Enter');
          onSubmit();
          return true;
        },
        Tab: () => {
          if (onAcKeydown('Tab')) return true;
          return onCommit('Tab');
        },
        Backspace: () => onExpand(),
        ArrowLeft: () => onExpand(),
        ArrowDown: () => onAcKeydown('ArrowDown'),
        ArrowUp: () => onAcKeydown('ArrowUp'),
        Escape: () => onAcKeydown('Escape'),
      };
    },
  });
}

export default defineComponent({
  name: 'QuickSearchBox',
  components: { EditorContent, FieldAutocomplete },

  props: {
    initialQuery: { type: String, default: '' },
    isFulltextEnabled: { type: Boolean, default: true },
    isVectorEnabled: { type: Boolean, default: true },
    placeholder: { type: String, default: '' },
  },

  emits: ['parsed', 'submit'],

  setup(props) {
    // Composables and TipTap state live in setup; everything else is
    // moved to data / computed / watch / mounted / methods below so
    // the component reads as canonical Options API.
    const editor = shallowRef<Editor | null>(null);
    const rootRef = ref<HTMLElement | null>(null);
    const editorSlotRef = ref<HTMLElement | null>(null);
    const caretAnchorRef = ref<HTMLElement | null>(null);
    const inst = getCurrentInstance();

    // The autocomplete composable's reactive state is created here
    // (ref()/computed() must run inside setup). Callbacks defer to
    // component methods via the instance proxy so chip-commit /
    // emitParsed live as Options API methods.
    const ac = useQuickSearchAutocomplete({
      editor,
      isFulltextEnabled: computed(() => props.isFulltextEnabled),
      isVectorEnabled: computed(() => props.isVectorEnabled),
      onValuePick: ({
        typedText,
        from,
        textStart,
        explicitConnector,
        field,
        op,
        payload,
        category,
      }) => {
        if (!editor.value) return false;
        insertChip(
          editor.value,
          textStart,
          from,
          field,
          op,
          payload.value,
          explicitConnector,
          payload.label,
          category,
        );
        (inst?.proxy as any)?.emitParsed?.();
        return true;
      },
      getUserId: () => {
        try {
          return useUserStore().getUserId() ?? null;
        } catch {
          return null;
        }
      },
      getLocale: () => {
        try {
          return i18n.getLanguage?.() ?? 'en';
        } catch {
          return 'en';
        }
      },
      translate: (key: string) => i18n.t(key),
      getCustomFields: () => {
        try {
          return customFieldsToFieldMetas(
            useDocTypeFieldsStore().getAllUniqueFieldsWithDocTypes,
          );
        } catch {
          return [];
        }
      },
    });

    return {
      editor,
      rootRef,
      editorSlotRef,
      caretAnchorRef,
      // Spread the composable's reactive refs at the top level so
      // Vue auto-unwraps them when accessed through `this` in methods
      // and via interpolation in the template.
      acOpen: ac.acOpen,
      acHasSuggestions: ac.acHasSuggestions,
      acMode: ac.acMode,
      acField: ac.acField,
      acOp: ac.acOp,
      acQuery: ac.acQuery,
      highlighted: ac.highlighted,
      // DOCB-12249-followup: surfaces whether the user has explicitly
      // arrowed into the suggestion list. The default highlight (set by
      // the watcher in useQuickSearchAutocomplete) leaves this false —
      // so we can distinguish "ENTER will submit" (default highlight)
      // from "ENTER will pick" (user-navigated).
      userNavigated: ac.userNavigated,
      connectorSuggestions: ac.connectorSuggestions,
      // Ghost-text suffix surfaced at the caret as a visual cue that
      // pressing TAB will complete the typed prefix with the highlighted
      // suggestion (Google-style autocomplete). Empty when no highlight
      // exists or when the highlighted item's canonical form doesn't
      // extend the typed query (e.g. translated label match where the
      // field's `name` doesn't share a prefix with the user input).
      ghostText: ac.ghostText,
      // Internal handle for methods that need the composable's
      // non-reactive members (currentList, openFieldList, onPick,
      // handleKeydown, updateFromContent, textBeforeCaret).
      acHandle: ac,
      // Re-exported for unit tests.
      labelFor,
    };
  },

  data() {
    return {
      focused: false,
      hasContent: false,
      // DRFS-534: tracks whether the user has touched the editor since
      // the last Enter-fire. Drives the "Press Enter to search"
      // affordance. Set true by `onUpdate` (only fires on user input —
      // programmatic content swaps use `setContent(_, false)` to opt
      // out). Cleared when Enter actually fires `@submit`.
      dirtySinceSubmit: false,
    };
  },

  computed: {
    valueItems(): Array<{
      value: string;
      label: string;
      isGroup?: boolean;
    }> | null {
      const ac = (this as any).acHandle;
      if (!ac) return null;
      return ac.acMode.value === 'value'
        ? ac.currentList.value.map((o: any) => ({
            value: o.value,
            label: o.label,
            isGroup: o.isGroup,
          }))
        : null;
    },

    // DRFS-534 + DOCB-12249-followup: gate the Enter affordance.
    // Visible whenever the user has touched the editor since the last
    // fire — including the empty state right after they clear the
    // input. Suppressed only when ENTER would actually pick a
    // suggestion (i.e. the user has explicitly arrowed into the list),
    // because then the icon would be a lie. A *default* highlight on
    // `filename` from typing `Doku` does NOT suppress the icon: ENTER
    // still falls through to submit/fulltext per the DRFS-534 guard,
    // so the affordance correctly tells the user "press Enter to fire".
    showPendingFireIcon(): boolean {
      if (!(this as any).dirtySinceSubmit) return false;
      const acOpen = Boolean((this as any).acOpen);
      const willEnterPick =
        acOpen &&
        (this as any).highlighted != null &&
        (this as any).userNavigated === true;
      return !willEnterPick;
    },
  },

  mounted() {
    this.initEditor((this as any).initialQuery);
    document.addEventListener('reset_filters', this.onReset as EventListener);
    document.addEventListener(
      'load_saved_filter',
      this.onLoadSavedFilter as EventListener,
    );
    nextTick(() => this.emitParsed());
  },

  beforeUnmount() {
    document.removeEventListener(
      'reset_filters',
      this.onReset as EventListener,
    );
    document.removeEventListener(
      'load_saved_filter',
      this.onLoadSavedFilter as EventListener,
    );
    (this.editor as Editor | null)?.destroy();
  },

  methods: {
    // ── emitParsed ──────────────────────────────────────────────────
    // Walk the TipTap doc, serialise to a raw query, parse it once
    // through the canonical parser, and emit the result. Carries
    // per-chip category overrides so the dashboard's wire-routing
    // can honour the section the user picked from.
    // DRFS-534: clicking the "Press Enter" affordance mirrors the
    // keyboard path — clear the dirty flag and emit submit so the host
    // runs the same validation + apply pipeline as a real Enter key.
    submitFromIcon() {
      this.dirtySinceSubmit = false;
      this.$emit('submit');
    },

    emitParsed() {
      const ed = this.editor as Editor | null;
      if (!ed) return;
      const raw = editorDocToQueryString(ed);
      const parsed = promoteBareKeyword(parseSearchQuery(raw), {
        vectorEnabled: this.isVectorEnabled,
        fulltextEnabled: this.isFulltextEnabled,
      });
      const overrides = new Map<
        string,
        'standard' | 'extended' | 'fulltext' | 'vector' | 'ocr' | 'ai'
      >();
      ed.state.doc.descendants((node) => {
        if (node.type.name !== 'chip') return;
        const { field, category } = node.attrs as {
          field?: string;
          category?:
            | 'standard'
            | 'extended'
            | 'fulltext'
            | 'vector'
            | 'ocr'
            | 'ai';
        };
        if (field && category) overrides.set(field, category);
      });
      if (overrides.size > 0) (parsed as any).chipCategoryOverrides = overrides;
      this.$emit('parsed', parsed);
    },

    // ── Composable bridges ──────────────────────────────────────────
    handleAcKeydown(key: string): boolean {
      return (this as any).acHandle.handleKeydown(key);
    },

    updateAutocomplete(content: string) {
      (this as any).acHandle.updateFromContent(content);
    },

    onAutocompletePick(payload: any) {
      const ac = (this as any).acHandle;
      ac.onPick(payload);
      // Presence preset / smart filter inserts a complete predicate
      // → kick tryCommit so it becomes a chip in the same gesture.
      if (payload?.kind === 'preset' || payload?.kind === 'smart-filter') {
        this.tryCommit('Tab');
      }
      this.emitParsed();
    },

    // ── Value normalisation ─────────────────────────────────────────
    // Case-insensitively match the typed value against the field's
    // canonical option list (status / doc_type / users / sub-orgs /
    // priority / currency). Returns the normalised value AND the
    // matched display label so the chip can render `Amier` instead
    // of the raw user_id.
    normaliseValue(
      field: string,
      value: string,
    ): { value: string; label?: string } {
      const { options } = useFieldValueSource(field);
      return matchValueInOptions(value, options.value ?? []);
    },

    // ── tryCommit ───────────────────────────────────────────────────
    // Inspect text-before-caret and replace it with a chip when the
    // shouldCommit predicate fires. Handles AND/OR connector prefix,
    // vector / AI semantic chips, custom doc-type fields, multi-
    // predicate `in (...)` / `between` / `overdue` shortcut splits,
    // and per-section category preservation.
    tryCommit(trigger: string | null): boolean {
      const ed = this.editor as Editor | null;
      if (!ed) return false;
      const {
        text: typedText,
        from: replaceFrom,
        to: replaceTo,
      } = commitRange(ed, trigger);

      let remaining = typedText;
      let explicitConnector: 'AND' | 'OR' | undefined;
      // Accept a leading connector in any supported language (AND/OR,
      // UND/ODER, ET/OU …) and fold it to canonical — DOCB-13123.
      const leadingConnector = matchLeadingConnector(remaining);
      if (leadingConnector) {
        explicitConnector = leadingConnector.connector;
        remaining = leadingConnector.rest;
      }

      if (
        (trigger === 'Enter' || trigger === 'Tab') &&
        hasDanglingQuote(remaining)
      ) {
        remaining = `${remaining}"`;
      }

      if (trigger === 'Enter' || trigger === 'Tab') {
        const vecMatch = VECTOR_PREFIX_CAPTURE_RE.exec(remaining);
        if (vecMatch) {
          const prefix = `${vecMatch[1].toLowerCase()}:`;
          const value = vecMatch[2].trim();
          const category = prefix === 'ocr:' ? 'ocr' : 'vector';
          if (value) {
            insertChip(
              ed,
              replaceFrom,
              replaceTo,
              prefix,
              '' as any,
              value,
              explicitConnector,
              undefined,
              category,
            );
            this.emitParsed();
            return true;
          }
        }
      }

      const customFieldNames = new Set<string>();
      try {
        for (const f of customFieldsToFieldMetas(
          useDocTypeFieldsStore().getAllUniqueFieldsWithDocTypes,
        )) {
          customFieldNames.add(f.name.toLowerCase());
        }
      } catch {
        /* store not yet hydrated */
      }
      const r = shouldCommit(remaining.trim(), trigger, customFieldNames);
      if (!r.commit || !r.chip) {
        // 2026-05-18 user-rule fix: bare text on Enter MUST stay as a
        // plain fulltext keyword across all fields. The previous
        // DOCB-12063 behaviour auto-synthesised a chip — `vector:` on
        // vector-enabled orgs (the visible "Semantic Search" chip
        // symptom) and `filename:` everywhere else. Both broke the
        // user-stated rule:
        //
        //   "ohne ein extra ist immer auf alles felder"
        //     bare text searches across all fields = fulltext keyword,
        //     never field-scoped.
        //   "vector ist nur wenn man nach vector oder semantic sucht
        //    sonst nie"
        //     vector kicks in via the explicit `vector:` / `semantic:`
        //     prefix branch above (lines 632-657), not here.
        //
        // tryCommit now declines for bare text → tryCommit returns
        // false → the caller's default Enter handler fires emitParsed
        // → parseSearchQuery picks up the bare text as `keyword`
        // → computeQuickSearchSlots ships `raw_query=<text>` with
        //    `is_fulltext=true, is_vector=false`.
        //
        // No chip is inserted; the editor keeps the typed text as
        // plain text — visually distinguishable from chipped
        // predicates and matching the user's mental model
        // ("just words to search for, no field constraint").
        return false;
      }

      const { value: canonicalValue, label: canonicalLabel } =
        this.normaliseValue(r.chip.field, r.chip.value);

      const ac = (this as any).acHandle;
      const pickedCategory =
        ac.acCategory.value && r.chip.field === ac.acField.value
          ? ac.acCategory.value
          : undefined;
      insertChip(
        ed,
        replaceFrom,
        replaceTo,
        r.chip.field,
        r.chip.op,
        canonicalValue,
        explicitConnector,
        canonicalLabel,
        pickedCategory,
        r.chip.quoted,
      );

      if (r.remainder) {
        const pos = ed.state.selection.from;
        ed.chain().focus().insertContentAt(pos, r.remainder).run();
      }
      this.emitParsed();
      return true;
    },

    // ── tryExpand ───────────────────────────────────────────────────
    // Backspace / ArrowLeft when the caret sits immediately after a
    // chip and there's no typed text — expand the chip back to text
    // form so the user can edit it.
    tryExpand(): boolean {
      const ed = this.editor as Editor | null;
      if (!ed) return false;
      const { selection, doc } = ed.state;
      const { from, to } = selection;

      if (from !== to) return false;
      const textBefore = textBeforeCaret(ed);
      if (textBefore.length > 0) return false;

      let chipPos: number | null = null;
      let chipNodeSize = 0;
      let chipAttrs: any = null;
      doc.nodesBetween(0, from, (node, pos) => {
        if (node.type.name === 'chip') {
          chipPos = pos;
          chipNodeSize = node.nodeSize;
          chipAttrs = node.attrs;
        }
      });
      if (chipPos === null || chipAttrs === null) return false;
      if (chipPos + chipNodeSize !== from) return false;

      // Bug-2026-05-25 #80 (Codex v15 [high]): use the SAME formatter
      // as `editorDocToQueryString` so a `not between` chip expands to
      // canonical `field not between A and B` text on Backspace/
      // ArrowLeft instead of the corrupt glued `field${op}${value}`
      // form that silently dropped the negated range.
      const text = chipToQueryText(
        chipAttrs.field,
        chipAttrs.op,
        chipAttrs.value,
        chipAttrs.quoted,
      );
      ed.chain()
        .focus()
        .deleteRange({ from: chipPos, to: chipPos + chipNodeSize })
        .insertContentAt(chipPos, text)
        .setTextSelection(chipPos + text.length)
        .run();
      this.emitParsed();
      return true;
    },

    // ── buildDocContent ─────────────────────────────────────────────
    // Convert a raw query string into TipTap paragraph content nodes.
    // Connectors are emitted as atomic `connector` nodes in document
    // order so paren grouping and explicit AND/OR placement survive
    // the round-trip.
    buildDocContent(raw: string): any[] {
      if (!raw.trim()) return [];
      const vecMatch = VECTOR_PREFIX_CAPTURE_RE.exec(raw.trim());
      if (vecMatch && vecMatch[2].trim()) {
        const prefix = `${vecMatch[1].toLowerCase()}:`;
        const category = prefix === 'ocr:' ? 'ocr' : 'vector';
        // DOCB-12249 (Codex Round 2): this prefix-capture path runs
        // BEFORE parseSearchQuery, so it never sees the parser's
        // groupByOverride extraction. Peel the directive off the
        // captured value so `vector:foo group by X` renders as a
        // vector chip + a group_by chip — matches the structured-
        // predicate path UX.
        const vecGb = extractGroupBy(vecMatch[2].trim());
        // DOCB-12249 (Codex Round 3 MEDIUM): when the entire captured
        // value WAS the directive (e.g. `vector:group by foo`),
        // `extractGroupBy()` returns `stripped: ''`. Emitting an empty
        // semantic chip would render as `vector:""` — a useless quoted
        // empty-string. Skip the prefix chip in that case and let the
        // directive stand alone.
        const vecOut: any[] = [];
        if (vecGb.stripped) {
          vecOut.push({
            type: 'chip',
            attrs: {
              field: prefix,
              op: '',
              value: vecGb.stripped,
              category,
            },
          });
        }
        if (vecGb.groupByOverride) {
          vecOut.push({
            type: 'chip',
            attrs: {
              field: 'group_by',
              op: ':',
              value: vecGb.groupByOverride.bucket
                ? `${vecGb.groupByOverride.field}|${vecGb.groupByOverride.bucket}`
                : vecGb.groupByOverride.field,
            },
          });
        }
        return vecOut;
      }
      // Bug-2026-05-25 #81 (Codex v15 [medium]): the old top-level
      // BETWEEN shortcut here ran a raw regex BEFORE `parseSearchQuery`
      // and built a chip for ANY word-shaped field — bypassing
      // `isSupportedSearchField`.  So free text / typos like
      // `contracts between 2024 and 2025` rendered as a structured
      // standard chip, diverging the UI semantics from the parser +
      // backend.  The predicate-gated look-ahead in the token loop
      // below now handles supported top-level BETWEEN correctly
      // (expandBetween only expands SUPPORTED fields, so `predsMatch`
      // fails for unknown fields and they fall through to text),
      // making this ungated shortcut a stale bypass.  Removed.
      const parsed = promoteBareKeyword(parseSearchQuery(raw), {
        vectorEnabled: this.isVectorEnabled,
        fulltextEnabled: this.isFulltextEnabled,
      });
      // DOCB-12249 (Codex review HIGH #6): the group-by directive is a
      // parser-extracted artefact — it never reaches the
      // `parsed.predicates` stream, but its raw `group by <field>
      // [bucket]` tokens are still present in the input. To render the
      // editor's directive chip on rehydrate AND avoid leftover
      // `group`/`by`/`<field>` text nodes, peel the directive out here:
      // strip it from the source the tokeniser runs on (so the token
      // loop below doesn't see the directive words) and append a single
      // `group_by` chip node at the end. Mirrors the
      // `queryStringToTokens()` convention in quickSearchTokens.ts.
      const groupByDirectiveNode = parsed.groupByOverride
        ? {
            type: 'chip',
            attrs: {
              field: 'group_by',
              op: ':',
              value: parsed.groupByOverride.bucket
                ? `${parsed.groupByOverride.field}|${parsed.groupByOverride.bucket}`
                : parsed.groupByOverride.field,
            },
          }
        : null;
      const rawForTokenise = groupByDirectiveNode
        ? stripGroupByDirective(raw)
        : raw;
      // Directive-only query (no predicates, no keyword) → return the
      // single chip directly. The token loop below would emit zero
      // chip nodes for an empty `rawForTokenise`, leaving the directive
      // orphaned.
      if (
        groupByDirectiveNode &&
        !rawForTokenise.trim() &&
        parsed.predicates.length === 0 &&
        !parsed.keyword
      ) {
        return [groupByDirectiveNode];
      }
      // Bare-text promotion fallback: when promoteBareKeyword synthesised
      // a filename/vector chip from a bare-text input, the raw string has
      // no predicate-looking tokens for the loop below to match against.
      // Emit the synthesised chip directly so the editor renders a single
      // chip instead of plain text. Mirrors the UUID and `vector:` prefix
      // branches above.
      const bareTextPromotion =
        parsed.predicates.length === 1 &&
        parsed.predicates[0].field === 'filename' &&
        parsed.predicates[0].operator === ':' &&
        !/^\s*filename\s*[:=]/i.test(raw);
      if (bareTextPromotion) {
        // DOCB-12249: append the directive chip when present so a
        // bare-text + group-by combination like `"foo group by bar"`
        // doesn't silently drop the directive.
        const out: any[] = [
          {
            type: 'chip',
            attrs: {
              field: 'filename',
              op: ':',
              value: parsed.predicates[0].value,
              category: categoryOf('filename'),
            },
          },
        ];
        if (groupByDirectiveNode) out.push(groupByDirectiveNode);
        return out;
      }
      if (
        parsed.isVectorMode &&
        parsed.keyword &&
        !VECTOR_PREFIX_CAPTURE_RE.test(raw.trim())
      ) {
        // DOCB-12249: same rule for the vector-mode promotion path.
        const out: any[] = [
          {
            type: 'chip',
            attrs: {
              field: 'vector:',
              op: '',
              value: parsed.keyword,
              category: 'vector',
            },
          },
        ];
        if (groupByDirectiveNode) out.push(groupByDirectiveNode);
        return out;
      }
      const preds = [...parsed.predicates];
      const collapsed = rawForTokenise.replace(
        /\s*(>=|<=|!=|>|<|=|:)\s*/g,
        '$1',
      );
      const tokens = tokenise(collapsed);
      const nodes: any[] = [];
      let chipIdx = 0;
      const PREFIX_TOKEN_RE = /^[@#$]/;
      const FIELD_NAME_RE = /^[a-zA-Z_][a-zA-Z0-9_]*$/;
      const UUID_RE_LOCAL =
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      // Bug-2026-05-25 #63 (Codex v13 [high]): rehydrate BETWEEN /
      // NOT-BETWEEN inside compound contexts.  Pre-#63 only the
      // top-level single-`between` shortcut above caught them; any
      // saved query like `status=approved AND imported_on between A
      // and B` slipped into the token loop, where the multi-word
      // pattern `imported_on / between / A / and / B` matches none of
      // the per-token chip rules and the two parser-expanded
      // predicates went unrendered, dropping the entire range.
      //
      // The loop now uses indexed iteration with a 4-or-5-token
      // look-ahead.  When we see `<field> between <A> and <B>` (or
      // the negated form) AND the parser-expanded predicate pair at
      // `chipIdx` matches the expected (>= / <=) or (< / >) shape,
      // emit ONE between/not-between chip and consume both
      // predicates so subsequent emissions stay in sync.
      // Bug-2026-05-25 #89/#90/#91 (Codex v17 [high]): the token loop
      // must VERIFY that each predicate-like token actually aligns with
      // the parser's predicate at `chipIdx` before consuming it, and
      // must fold a unary `NOT <field><op><value>` into the parser's
      // INVERTED predicate (`expandNegationPrefix`) rather than emitting
      // a stray `NOT` text + positive chip (double negation).
      const PREDICATE_FULL_RE =
        /^([a-zA-Z_][a-zA-Z0-9_]*)(>=|<=|!=|=|:|>|<)([\s\S]*)$/;
      // Mirror of `NOT_OP_INVERSION` in searchQueryParser.expandNegationPrefix.
      const NOT_OP_INVERSION: Record<string, string> = {
        '=': '!=',
        ':': '!=',
        '!=': '=',
        '>': '<=',
        '>=': '<',
        '<': '>=',
        '<=': '>',
      };
      const stripOuterQuotes = (v: string): string => {
        if (
          v.length >= 2 &&
          ((v[0] === '"' && v[v.length - 1] === '"') ||
            (v[0] === "'" && v[v.length - 1] === "'"))
        ) {
          return v.slice(1, -1);
        }
        return v;
      };
      const parsePredTok = (
        t: string,
      ): { field: string; op: string; value: string } | null => {
        const m = t.match(PREDICATE_FULL_RE);
        if (!m) return null;
        return {
          field: m[1].toLowerCase(),
          op: m[2],
          value: stripOuterQuotes(m[3]),
        };
      };
      // Does the predicate token align with `preds[chipIdx]` (optionally
      // with the operator inverted to match `not field<op>value`)?
      const alignsWithChip = (
        pt: { field: string; op: string; value: string } | null,
        invert: boolean,
      ): boolean => {
        const p = preds[chipIdx];
        if (!p || !pt) return false;
        const op = invert ? NOT_OP_INVERSION[pt.op] || pt.op : pt.op;
        return (
          p.field === pt.field && p.operator === op && p.value === pt.value
        );
      };
      const pushPredChip = (): void => {
        const p = preds[chipIdx];
        chipIdx += 1;
        nodes.push({
          type: 'chip',
          attrs: {
            field: p.field,
            op: p.operator,
            value: p.value,
            category: categoryOf(p.field),
            quoted: p.quoted ?? false,
          },
        });
      };
      // BETWEEN look-ahead. `fieldIdx` = field-token index, `betweenIdx`
      // = `between`-keyword index.  Returns the NEXT loop index on a
      // confirmed match (after emitting one chip + advancing chipIdx by
      // 2), or -1 — the caller only advances the real cursor on success
      // (Bug #91: never mutate `i` mid-lookahead).
      const tryBetween = (
        fieldIdx: number,
        betweenIdx: number,
        negated: boolean,
        positiveShape: boolean,
      ): number => {
        const j = betweenIdx;
        // The value pair can land in four shapes (whitespace-only
        // tokeniser × `,`/` and ` separators):
        //   1. `<A> AND <B>`  → j+1,j+2,j+3   2. `<A> , <B>` → j+1,j+2,j+3
        //   3. `<A>, <B>`     → j+1,j+2       4. `<A>,<B>`   → j+1 (combined)
        let start: string | null = null;
        let end: string | null = null;
        let consumed = 0;
        const innerCommaMatch =
          j + 1 < tokens.length
            ? tokens[j + 1].match(/^([^,\s]+),([^,\s]+)$/)
            : null;
        if (innerCommaMatch) {
          start = innerCommaMatch[1];
          end = innerCommaMatch[2];
          consumed = 2;
        } else if (
          j + 3 < tokens.length &&
          (tokens[j + 2].toUpperCase() === 'AND' || tokens[j + 2] === ',')
        ) {
          start = tokens[j + 1];
          end = tokens[j + 3];
          consumed = 4;
        } else if (
          j + 2 < tokens.length &&
          tokens[j + 1].endsWith(',') &&
          tokens[j + 1].length > 1
        ) {
          start = tokens[j + 1].slice(0, -1);
          end = tokens[j + 2];
          consumed = 3;
        }
        if (start === null || end === null) return -1;
        const fld = tokens[fieldIdx].toLowerCase();
        const p0 = preds[chipIdx];
        const p1 = preds[chipIdx + 1];
        // `field NOT between` → expandNotBetween → preds (<, >).
        // `NOT field between` / `field between` → expandBetween →
        // preds (>=, <=) (the unary NOT lives in the keyword, not the
        // per-predicate op).
        const expectedFirstOp = positiveShape ? '>=' : '<';
        const expectedSecondOp = positiveShape ? '<=' : '>';
        const predsMatch =
          p0 &&
          p1 &&
          p0.field === fld &&
          p1.field === fld &&
          p0.operator === expectedFirstOp &&
          p1.operator === expectedSecondOp;
        if (!predsMatch) return -1;
        nodes.push({
          type: 'chip',
          attrs: {
            field: fld,
            op: negated ? 'not between' : 'between',
            value: `${start}..${end}`,
            label: `${start} – ${end}`,
            category: categoryOf(fld),
          },
        });
        chipIdx += 2;
        return j + consumed;
      };

      let i = 0;
      while (i < tokens.length) {
        const tok = tokens[i];
        if (tok === '(') {
          nodes.push({ type: 'paren', attrs: { side: 'open' } });
          i += 1;
          continue;
        }
        if (tok === ')') {
          nodes.push({ type: 'paren', attrs: { side: 'close' } });
          i += 1;
          continue;
        }
        const upper = tok.toUpperCase();
        // A connector token in any supported language becomes a canonical
        // AND/OR connector node — DOCB-13123.
        const connectorKind = canonicalConnectorWord(tok);
        if (connectorKind) {
          nodes.push({ type: 'connector', attrs: { kind: connectorKind } });
          i += 1;
          continue;
        }

        if (upper === 'NOT') {
          const next = i + 1 < tokens.length ? tokens[i + 1] : undefined;
          // (a) Bug #72/#91: `NOT <field> between …` → not-between chip.
          // Validate via candidate indices; only advance `i` on success.
          if (
            next !== undefined &&
            FIELD_NAME_RE.test(next) &&
            i + 2 < tokens.length &&
            tokens[i + 2].toLowerCase() === 'between'
          ) {
            const ni = tryBetween(i + 1, i + 2, true, true);
            if (ni >= 0) {
              i = ni;
              continue;
            }
          }
          // (b) Bug #90: `NOT <field><op><value>` was rewritten by
          // `expandNegationPrefix` into an INVERTED predicate.  Fold the
          // NOT into that single chip instead of emitting a stray `NOT`
          // text + positive chip (which double-negates).
          if (next !== undefined) {
            const pt = parsePredTok(next);
            if (pt && alignsWithChip(pt, true)) {
              pushPredChip();
              i += 2; // consume NOT + the predicate token
              continue;
            }
          }
          // Standalone / parenthesised NOT (e.g. `NOT (…)`) → inline
          // text IN POSITION (Bug #87) so the round-trip is faithful.
          nodes.push({ type: 'text', text: tok });
          i += 1;
          continue;
        }

        // `field between …` or `field NOT between …`.
        if (FIELD_NAME_RE.test(tok)) {
          let negated = false;
          let betweenIdx = i + 1;
          if (i + 1 < tokens.length && tokens[i + 1].toLowerCase() === 'not') {
            negated = true;
            betweenIdx = i + 2;
          }
          if (
            betweenIdx < tokens.length &&
            tokens[betweenIdx].toLowerCase() === 'between'
          ) {
            const ni = tryBetween(i, betweenIdx, negated, !negated);
            if (ni >= 0) {
              i = ni;
              continue;
            }
          }
        }

        // Glued `field<op>value` predicate token.
        const pt = parsePredTok(tok);
        if (pt) {
          // Bug #89: only consume `preds[chipIdx]` when the token
          // ACTUALLY aligns with it.  An unsupported predicate-like
          // token (parser left it in keyword) must NOT steal the next
          // real predicate — emit it as inline text and keep chipIdx.
          if (alignsWithChip(pt, false)) {
            pushPredChip();
            i += 1;
            continue;
          }
          nodes.push({ type: 'text', text: tok });
          i += 1;
          continue;
        }

        // Prefix (@/#/$) or UUID tokens: the parser SYNTHESISES these
        // predicates (no `field<op>value` to verify), so trust chipIdx
        // ordering as before.
        if (PREFIX_TOKEN_RE.test(tok) || UUID_RE_LOCAL.test(tok)) {
          if (preds[chipIdx]) {
            pushPredChip();
            i += 1;
            continue;
          }
        }

        // Residual free text → inline text IN POSITION (Bug #87/#88).
        nodes.push({ type: 'text', text: tok });
        i += 1;
      }
      // Bug-2026-05-25 #87/#88: NO global `parsed.keyword` trailing
      // append — all residual free-text / `NOT` tokens are emitted
      // inline in token order above.
      //
      // DOCB-12249: append the directive chip last so it always lives at
      // the end of the document — mirrors how the user types it (and how
      // `getRawQuery()` serialises it back via the ChipNode branch in
      // QuickSearchBox.serialiseToString).
      if (groupByDirectiveNode) {
        nodes.push(groupByDirectiveNode);
      }
      return nodes;
    },

    // ── initEditor ──────────────────────────────────────────────────
    // Build TipTap extensions and instantiate the Editor. Run from
    // mounted() — relies on `this` being available so the extension
    // shortcuts can call back into Options API methods.
    initEditor(content = '') {
      const existing = this.editor as Editor | null;
      if (existing) existing.destroy();

      const ChipNode = createChipNode(ChipNodeView);
      const ParenNode = createParenNode(ParenNodeView);
      const ConnectorNode = createConnectorNode(ConnectorNodeView);
      const SearchBehaviours = createSearchExtension(
        (trigger: string) => this.tryCommit(trigger),
        () => this.tryExpand(),
        () => {
          // DRFS-534: Enter fires the query unconditionally. Clear the
          // dirty flag so the Enter affordance hides until the next
          // user edit. The host (`onChipSubmit`) gates on validation
          // errors and skips the actual apply when invalid.
          this.dirtySinceSubmit = false;
          this.$emit('submit');
        },
        (key: string) => this.handleAcKeydown(key),
      );
      const SpaceCommit = Extension.create({
        name: 'spaceCommit',
        addKeyboardShortcuts: () => ({
          ' ': () => {
            if (this.handleAcKeydown(' ')) return true;
            return this.tryCommit(' ');
          },
        }),
        priority: 200,
      } as any);

      const e = new Editor({
        extensions: [
          Document,
          Paragraph,
          Text,
          ChipNode,
          ParenNode,
          ConnectorNode,
          SyntaxHighlight,
          AutoQuoteOnEquals,
          SpaceCommit,
          SearchBehaviours,
        ],
        autofocus: false,
        content: content
          ? {
              type: 'doc',
              content: [
                { type: 'paragraph', content: this.buildDocContent(content) },
              ],
            }
          : { type: 'doc', content: [{ type: 'paragraph' }] },
        editorProps: {
          // `data-test="search-input"` is applied to the actual
          // ProseMirror contenteditable element here so Playwright can
          // locate and fill the real editable (the outer
          // `.qs-editor-content` wrapper carries no fillable input).
          attributes: {
            class: 'qs-editor',
            spellcheck: 'false',
            'data-test': 'search-input',
          },
          handlePaste: (_view: any, event: any) => {
            const rawClip = event.clipboardData?.getData('text/plain') ?? '';
            if (!rawClip) return false;

            // Two fast paths build a verbatim-value chip for a free-text
            // string field so a value with spaces is kept WHOLE instead of
            // being fragmented by the whitespace tokeniser: OBO-46 (prefix
            // already in the box) and DOCB-12360 (prefix pasted as part of
            // the clip). Everything else falls through to the unchanged
            // paste path below, so no existing paste semantics change.
            const clip = normaliseSmartQuotes(rawClip).trim();

            // Build a chip DIRECTLY from a field/op + verbatim value,
            // replacing [from, to]. Bypasses parseSearchQuery/buildDocContent
            // so the operator-collapsing tokeniser never mangles the value
            // (e.g. `Invoice: 2026` → `Invoice:2026`) and a value with
            // spaces is kept whole. Preserves the field name's CASE —
            // custom EAV fields are case-sensitive on the backend (Codex
            // review). Returns false (no commit) for an empty value so the
            // caller falls through to the normal paste path.
            const commitVerbatimChip = (
              field: string,
              op: string,
              value: string,
              from: number,
              to: number,
            ): boolean => {
              if (!value) return false;
              event.preventDefault();
              insertChip(
                e,
                from,
                to,
                field,
                op,
                value,
                undefined,
                undefined,
                resolvePasteChipCategory(field) ?? categoryOf(field),
              );
              this.emitParsed();
              return true;
            };

            // OBO-46 — the box already holds a bare `supplier_name:` prefix
            // and the user pastes a copied value with spaces ("Acme Corp
            // Ltd"). The whitespace tokeniser would otherwise fragment the
            // value into a chip capturing only the first word. Restricted to
            // free-text string fields (NOT value-source fields like
            // assigned_to, whose labels must be normalised on Enter).
            const rawBefore = textBeforeCaret(e); // excludes committed chips
            const prefixMatch = rawBefore.match(
              /(?:^|\s|\()([a-zA-Z_][a-zA-Z0-9_]*)\s*(>=|<=|!=|=|:|>|<)\s*$/,
            );
            if (
              prefixMatch &&
              isMultiTokenStringField(prefixMatch[1]) &&
              !fieldHasValueSource(prefixMatch[1]) &&
              clip.length > 0
            ) {
              // Replace exactly the `field<op>` prefix run (keep any text
              // typed before it); leading boundary char is not part of it.
              // Replace through the selection END so a non-collapsed
              // selection's old value is removed, not left after the chip.
              const lead = /^[\s(]/.test(prefixMatch[0]) ? 1 : 0;
              const prefixLen = prefixMatch[0].length - lead;
              const { from, to } = e.state.selection;
              const start = Math.max(0, from - prefixLen);
              if (
                commitVerbatimChip(
                  prefixMatch[1],
                  prefixMatch[2],
                  stripOuterQuotes(clip),
                  start,
                  to,
                )
              ) {
                return true;
              }
            }

            // DOCB-12360 — the user pastes a COMPLETE `field<op>value` query
            // whose value has spaces (e.g.
            // `supplier_name=IVET FACTORY GROUP S.R.O.`). Same fragmentation
            // problem as OBO-46, but here the prefix lives in the CLIP, not
            // the box. Skip quoted values (parseSearchQuery handles those
            // correctly) and anything carrying boolean/grouping syntax so
            // genuine multi-predicate pastes still flow through the parser.
            const wholeMatch = clip.match(
              /^([a-zA-Z_][a-zA-Z0-9_]*)\s*(>=|<=|!=|=|:|>|<)\s*(\S.*)$/,
            );
            if (
              wholeMatch &&
              isMultiTokenStringField(wholeMatch[1]) &&
              !fieldHasValueSource(wholeMatch[1]) &&
              /\s/.test(wholeMatch[3]) &&
              !/[()]/.test(wholeMatch[3]) &&
              !/\b(?:AND|OR)\b/i.test(wholeMatch[3]) &&
              !wholeMatch[3].startsWith('"') &&
              !wholeMatch[3].startsWith("'")
            ) {
              const { from, to } = e.state.selection;
              if (
                commitVerbatimChip(
                  wholeMatch[1],
                  wholeMatch[2],
                  wholeMatch[3].trim(),
                  from,
                  to,
                )
              ) {
                return true;
              }
            }

            // ── Unchanged paste path for everything else ────────────────
            const parsed = promoteBareKeyword(parseSearchQuery(rawClip), {
              vectorEnabled: this.isVectorEnabled,
              fulltextEnabled: this.isFulltextEnabled,
            });
            if (parsed.predicates.length === 0 && !parsed.isVectorMode) {
              return false;
            }
            event.preventDefault();
            const nodes = this.buildDocContent(rawClip);
            const { from, to } = e.state.selection;
            e.chain()
              .focus()
              .deleteRange({ from, to })
              .insertContentAt(from, nodes)
              .run();
            this.emitParsed();
            return true;
          },
        },
        onUpdate: () => {
          const wasContentful = this.hasContent;
          this.hasContent = !e.isEmpty;
          // DRFS-534: TipTap fires onUpdate only for user-driven edits
          // (programmatic setRawQuery/onReset/onLoadSavedFilter use
          // `setContent(_, false)` to suppress this callback). Mark the
          // editor dirty so the "Press Enter to search" affordance
          // appears until the user actually fires.
          this.dirtySinceSubmit = true;
          const typedText = (this as any).acHandle.textBeforeCaret(e);
          this.updateAutocomplete(typedText);
          this.emitParsed();
          this.updateCaretAnchor();
          // DOCB-12063: clearing the box (chip "x", select-all + delete,
          // backspace to empty) is unambiguous intent to reset the
          // filter — fire submit so the host re-applies. Symmetric to
          // the explicit-Enter path; programmatic clears are already
          // suppressed because they pass `emitUpdate: false` and never
          // reach this callback.
          if (wasContentful && !this.hasContent) {
            this.dirtySinceSubmit = false;
            this.$emit('submit');
          }
        },
        onSelectionUpdate: () => {
          this.updateCaretAnchor();
        },
        onFocus: () => {
          this.focused = true;
          this.updateCaretAnchor();
        },
        onBlur: () => {
          this.focused = false;
        },
        onCreate: () => {
          // ProseMirror occasionally grabs focus on mount; release it
          // so the dashboard doesn't open with the caret blinking in
          // the search bar.
          const el = document.activeElement as HTMLElement | null;
          if (
            el &&
            el.classList.contains('ProseMirror') &&
            el.closest('.qs-box')
          ) {
            el.blur();
          }
        },
      });
      (this as any).editor = e;
      this.hasContent = !e.isEmpty;
    },

    // ── Click on padding/border focuses the editor ──────────────────
    focusEditor(e: MouseEvent) {
      const ed = this.editor as Editor | null;
      if (!ed) return;
      const target = e.target as HTMLElement | null;
      if (target && target.closest('.qs-editor')) return;
      if (target && target.closest('.qs-chip')) return;
      ed.chain().focus('end').run();
    },

    // ── Caret-following anchor for the autocomplete dropdown ────────
    // Move the invisible 1×1 marker to the caret's DOMRect so the
    // q-menu opens directly under the character the user is editing.
    updateCaretAnchor() {
      const ed = this.editor as Editor | null;
      // DOCB-13124: keep the ghost/Tab-badge gate in sync with the caret —
      // runs on every onUpdate / onSelectionUpdate / onFocus so the inline
      // completion only shows while the caret is at the end of the input.
      if (ed) (this as any).acHandle.syncCaretAtEnd(ed);
      const anchor = this.caretAnchorRef as HTMLElement | null;
      const host = this.rootRef as HTMLElement | null;
      if (!ed || !anchor || !host) return;
      try {
        const pos = ed.state.selection.from;
        const coords = ed.view.coordsAtPos(pos);
        const hostRect = host.getBoundingClientRect();
        // hostRect is the border-box (outer edge of border). The
        // containing block for `position: absolute` children of a
        // `position: relative` parent is the *padding edge* — i.e.
        // INSIDE the border. Subtract the border widths so anchor
        // sits exactly at the caret's screen coordinates instead of
        // (border-width) pixels offset to the bottom-right. Without
        // this correction the ghost-text suffix visibly clears the
        // caret by 1-2 px (and several px on hi-dpi where physical
        // border can render as 2 logical pixels).
        const hostStyle = getComputedStyle(host);
        const borderLeft = parseFloat(hostStyle.borderLeftWidth) || 0;
        const borderTop = parseFloat(hostStyle.borderTopWidth) || 0;
        anchor.style.left = `${coords.left - hostRect.left - borderLeft}px`;
        anchor.style.top = `${coords.bottom - hostRect.top - borderTop}px`;
        // Cap the ghost-text width to the room remaining between the
        // caret and the editor-content right edge. Without this the
        // ghost suffix can overrun the append-toolbar (copy/filters/
        // help buttons) on narrow layouts — Codex review LOW.
        // A small safety pad (16px) keeps the ellipsis from sitting
        // flush against the border.
        const editorEl = host.querySelector(
          '.qs-editor-content',
        ) as HTMLElement | null;
        if (editorEl) {
          const editorRect = editorEl.getBoundingClientRect();
          const available = Math.max(40, editorRect.right - coords.left - 16);
          anchor.style.setProperty('--qs-ghost-max-width', `${available}px`);
        }
      } catch {
        /* doc not laid out yet — next tick will retry */
      }
    },

    // ── Reset / load-saved-filter ───────────────────────────────────
    // DRFS-534: programmatic content swaps pass `false` as the second
    // arg to `setContent`/`clearContent` so TipTap suppresses
    // `onUpdate` and the dirty flag stays clean.
    onReset() {
      const ed = this.editor as Editor | null;
      ed?.commands.clearContent(false);
      this.hasContent = false;
      this.dirtySinceSubmit = false;
      this.emitParsed();
    },

    onLoadSavedFilter(ev: Event) {
      const raw: string = (ev as CustomEvent).detail?.raw ?? '';
      const ed = this.editor as Editor | null;
      if (!ed) return;
      const content = this.buildDocContent(raw);
      ed.commands.setContent(
        {
          type: 'doc',
          content: [{ type: 'paragraph', content }],
        },
        { emitUpdate: false },
      );
      this.hasContent = !ed.isEmpty;
      this.dirtySinceSubmit = false;
      this.emitParsed();
    },

    // ── Imperative API for parents (raw-view toggle, drill-down) ───
    getRawQuery(): string {
      const ed = this.editor as Editor | null;
      if (!ed) return '';
      return editorDocToQueryString(ed);
    },

    setRawQuery(raw: string): void {
      const ed = this.editor as Editor | null;
      if (!ed) return;
      const content = this.buildDocContent(raw);
      ed.commands.setContent(
        {
          type: 'doc',
          content: [{ type: 'paragraph', content }],
        },
        { emitUpdate: false },
      );
      this.hasContent = !ed.isEmpty;
      this.dirtySinceSubmit = false;
      this.emitParsed();
    },

    // DRFS-581: bolt-icon click handler. Focus the chip editor and
    // open the field-mode autocomplete with an empty query so smart
    // filters and the full field list become discoverable without
    // the user having to type a character first.
    openSearch(): void {
      const ed = this.editor as Editor | null;
      if (!ed) return;
      ed.chain().focus('end').run();
      (this as any).acHandle.openFieldList();
    },
  },
});
</script>

