export type AssigneeKind = 'user' | 'group';

export interface AssigneeOption {
  value: string | number;
  label: string;
  kind: AssigneeKind;
}

export interface AssigneePartition {
  userIds: string;
  groupIds: string;
  userList: AssigneeOption[];
  groupList: AssigneeOption[];
}

export function buildAssigneeOptions(
  usersMap: Map<any, any>,
  groups: any[],
  includeGroups: boolean,
): AssigneeOption[] {
  const options: AssigneeOption[] = [];

  usersMap.forEach((user, id) => {
    options.push({
      value: id,
      label: `${user.first_name ?? ''} ${user.last_name ?? ''}`.trim(),
      kind: 'user',
    });
  });

  if (includeGroups) {
    for (const group of groups ?? []) {
      options.push({
        value: group.group_id,
        label: group.group_name,
        kind: 'group',
      });
    }
  }

  return options;
}

export function partitionAssignees(
  selected: AssigneeOption[],
): AssigneePartition {
  const userList = selected.filter((option) => option.kind === 'user');
  const groupList = selected.filter((option) => option.kind === 'group');

  return {
    userIds: userList.map((option) => option.value).join(','),
    groupIds: groupList.map((option) => option.value).join(','),
    userList,
    groupList,
  };
}
