<template>
  <q-resize-observer @resize="elementLoadedEvent" :debounce="0" />
  <SearchHelpDialog v-model="showHelpDialog" />

  <!-- Search row: editor (with inline toolbar) + view-mode toggle.
       Capability icon, copy, tune-filters, and help buttons now live
       inside the input as prepend/append content so the toolbar row
       stays compact and the input itself can grow wider. -->
  <div
    class="row no-wrap items-center search-invoices"
    data-test="quick-search"
  >
    <div class="col qs-editor-slot">
      <QuickSearchBox
        v-show="!showRaw"
        ref="quickSearchBoxRef"
        :initial-query="initialQuery"
        :is-fulltext-enabled="isFulltextEnabled"
        :is-vector-enabled="isVectorEnabled"
        :placeholder="searchPlaceholder"
        @parsed="onParsed"
        @submit="onChipSubmit"
        class="qs-editor-slot__editor"
      >
        <template #prepend>
          <q-icon
            :name="capabilityIcon"
            size="18px"
            class="search-capability-icon search-capability-icon--clickable"
            :class="capabilityIconClass"
            data-test="qs-capability-icon"
            @mouseenter="refreshIndexSyncStatus()"
            @click.stop="openSearchPicker"
          >
            <SearchCapabilityTooltip
              :is-fulltext-enabled="isFulltextEnabled"
              :is-vector-enabled="isVectorEnabled"
            />
          </q-icon>
          <ValidationErrorIndicator :errors="displayedValidationErrors" />
        </template>
        <template #append>
          <q-chip
            v-if="needsFulltextButMissing"
            dense
            square
            size="sm"
            color="orange-2"
            text-color="orange-9"
            icon="warning"
            class="qs-fulltext-warning"
          >
            {{ $t('search_warn_requires_fulltext') }}
            <q-tooltip>{{
              $t('search_warn_requires_fulltext_hint')
            }}</q-tooltip>
          </q-chip>
          <QuickSearchToolbar
            :show-raw="showRaw"
            :raw-query-text="rawQueryText"
            :user-settings="user_settings"
            :can-leave-raw-view="canLeaveRawView"
            :on-set-view-mode="setViewMode"
            :on-copy-raw-query="copyRawQuery"
            :on-show-help="() => (showHelpDialog = true)"
            :on-filter-show="onFilterShow"
            :on-filter-hide="onFilterHide"
            :on-reset-filters="resetFilters"
            :on-apply-filters="applyFilters"
            :index-sync-percent="indexSyncPercent"
            :index-sync-documents-line="indexSyncDocumentsLine"
            :index-sync-vector-line="indexSyncVectorLine"
          />
        </template>
      </QuickSearchBox>
      <RawQueryEditor
        v-if="showRaw"
        v-model="rawQueryText"
        :placeholder="$t('search_raw_placeholder')"
        class="qs-editor-slot__editor"
        @apply="applyRaw"
      >
        <template #prepend>
          <q-icon
            :name="capabilityIcon"
            size="18px"
            class="search-capability-icon"
            :class="capabilityIconClass"
            data-test="qs-capability-icon-raw"
            @mouseenter="refreshIndexSyncStatus()"
          >
            <SearchCapabilityTooltip
              :is-fulltext-enabled="isFulltextEnabled"
              :is-vector-enabled="isVectorEnabled"
            />
          </q-icon>
          <ValidationErrorIndicator :errors="displayedValidationErrors" />
        </template>
        <template #append>
          <q-chip
            v-if="needsFulltextButMissing"
            dense
            square
            size="sm"
            color="orange-2"
            text-color="orange-9"
            icon="warning"
            class="qs-fulltext-warning"
          >
            {{ $t('search_warn_requires_fulltext') }}
            <q-tooltip>{{
              $t('search_warn_requires_fulltext_hint')
            }}</q-tooltip>
          </q-chip>
          <QuickSearchToolbar
            :show-raw="showRaw"
            :raw-query-text="rawQueryText"
            :user-settings="user_settings"
            :can-leave-raw-view="canLeaveRawView"
            :on-set-view-mode="setViewMode"
            :on-copy-raw-query="copyRawQuery"
            :on-show-help="() => (showHelpDialog = true)"
            :on-filter-show="onFilterShow"
            :on-filter-hide="onFilterHide"
            :on-reset-filters="resetFilters"
            :on-apply-filters="applyFilters"
            :index-sync-percent="indexSyncPercent"
            :index-sync-documents-line="indexSyncDocumentsLine"
            :index-sync-vector-line="indexSyncVectorLine"
          />
        </template>
      </RawQueryEditor>
    </div>
  </div>
</template>

<script lang="ts">
import { Notify } from 'quasar';
import { storeToRefs } from 'pinia';
import {
  defineComponent,
  ref,
  computed,
  onMounted,
  onBeforeUnmount,
  nextTick,
  watch,
} from 'vue';
import { i18n } from 'src/boot/i18n';
// import TimeFilter from 'src/pages/Dashboard/advancedSettings/time-filter.vue';
import { group_permission_activated } from 'src/constants';
import {
  useSettingStore,
  useColumnFilterStore,
  useDashboardStore,
} from 'src/store/main';
import {
  ParsedSearch,
  FIELD_CATALOG,
  stripGroupByDirective,
} from 'src/pages/Dashboard/Filters/searchQueryParser';
import { computeQuickSearchSlots } from 'src/pages/Dashboard/Filters/computeQuickSearchSlots';
import QuickSearchBox from 'src/pages/Dashboard/Filters/QuickSearchBox.vue';
import RawQueryEditor from 'src/pages/Dashboard/Filters/RawQueryEditor.vue';
import QuickSearchToolbar from 'src/pages/Dashboard/Filters/QuickSearchToolbar.vue';
import SearchHelpDialog from 'src/pages/Dashboard/Filters/SearchHelpDialog.vue';
import ValidationErrorIndicator from 'src/pages/Dashboard/Filters/ValidationErrorIndicator.vue';
import SearchCapabilityTooltip from 'src/pages/Dashboard/Filters/SearchCapabilityTooltip.vue';
import {
  formatDocumentsLine,
  formatVectorLine,
} from 'src/pages/Dashboard/Filters/search-help-capability';
import FulltextSettingsApiService, {
  DocumentStatsResponse,
} from 'src/services/settings/FulltextSettingsApiService';
import { useReindexProgress } from 'src/composables/useReindexProgress';
import {
  validateQuery,
  ValidationError,
} from 'src/pages/Dashboard/Filters/validateQuery';
import {
  shouldMarkDirty,
  shouldGateBareTextTooShort,
} from 'src/pages/Dashboard/Filters/quickSearchApplyGate';
// import PaginationSettings from 'src/pages/Dashboard/advancedSettings/pagination-settings.vue';

// Empty parsed default — used by `data()` for the initial lastParsed
// shape and by `applyIfSignatureChanged` resets.
const EMPTY_PARSED: ParsedSearch = {
  predicates: [],
  keyword: '',
  requiresFulltext: false,
  isVectorMode: false,
  isAiMode: false,
  isOcrMode: false,
};

const INDEX_SYNC_CACHE_MS = 30_000;

export default defineComponent({
  mixins: [],
  props: {},
  components: {
    SearchHelpDialog,
    QuickSearchBox,
    RawQueryEditor,
    QuickSearchToolbar,
    ValidationErrorIndicator,
    SearchCapabilityTooltip,
  },

  setup() {
    // Pinia stores and the API service must be acquired with composable
    // syntax. Everything else (refs / computeds / watchers / lifecycle
    // hooks / methods) lives in Options API blocks below.
    const columnFilterStore = useColumnFilterStore();
    const { quickFilterMap, tempFilterMap } = storeToRefs(columnFilterStore);

    // DRFS-583 — chip-editor edits must surface the
    // "Save dashboard changes" badge, same as any other filter
    // mutation. Pulled here so applyIfSignatureChanged can flip
    // dashboard_updated when the user types a new query.
    const dashboardStore = useDashboardStore();
    const { checkForDashboardUpdates } = dashboardStore;

    const settingsStore = useSettingStore();
    const { user_settings, org_based_settings } = storeToRefs(settingsStore);

    const fulltextSettingsApi = new FulltextSettingsApiService();

    // 2026-05-05: connect the SSE-driven docStats stream from the
    // /settings/fulltext machinery so the dashboard's Sync-% badge
    // updates LIVE without a mouseenter trigger. Reuses the same
    // composable Settings → Fulltext already drives — single source
    // of truth for index-coverage state app-wide.
    //
    // The SSE backend pushes idle heartbeats every 30s when nothing
    // is reindexing, so an idle dashboard still gets a steady stream
    // of "stats unchanged" pings; mid-reindex it pushes per-batch
    // updates. lifecycle: started in mounted() if Fulltext is on,
    // closed in beforeUnmount() via cleanup.
    //
    // silent: true → the dashboard subscribes only for the badge state.
    // The "Indexing complete: N indexed, M failed" toast belongs to the
    // /settings/fulltext page where the user clicked Reindex; firing it
    // on every passive document upload spam-toasts the dashboard.
    const reindex = useReindexProgress(fulltextSettingsApi, { silent: true });

    return {
      columnFilterStore,
      quickFilterMap,
      tempFilterMap,
      checkForDashboardUpdates,
      user_settings,
      org_based_settings,
      fulltextSettingsApi,
      // SSE-driven realtime stats (replaces the old mouseenter pull)
      docStatsSSE: reindex.docStats,
      startSSEStream: reindex.startStatusStream,
      sseCleanup: reindex.cleanup,
    };
  },

  data() {
    return {
      // ── Index sync status ─────────────────────────────────────────
      documentIndexStats: null as DocumentStatsResponse['stats'] | null,
      indexSyncLoading: false,
      indexSyncError: false,
      indexSyncLoadedAt: 0,

      // ── Hydration / chip-owned slot tracking ──────────────────────
      initialQuery: '',
      hasHydrated: false,
      lastParsed: { ...EMPTY_PARSED } as ParsedSearch,
      chipOwnedKeys: new Set<string>(),
      lastEmittedGroupBy: null as {
        field: string;
        bucket?: 'day' | 'week' | 'month';
      } | null,

      // ── Help / Raw view ───────────────────────────────────────────
      showHelpDialog: false,
      showRaw: false,
      rawQueryText: '',
      rawDirty: false,

      // ── Validation ────────────────────────────────────────────────
      showErrors: false,
      serverValidationError: null as {
        message: string;
        rawSnapshot: string;
      } | null,

      // ── Apply gate ────────────────────────────────────────────────
      reset_pagination: false,
      lastAppliedSignature: '' as string,

      // Misc UI bookkeeping that the template relies on.
      showing: false,
      group_permission_activated,

      // Internal cleanup callback for the column-filter store
      // subscription opened in mounted(). Stored so beforeUnmount can
      // tear it down.
      _columnFilterUnsubscribe: null as null | (() => void),
    };
  },

  computed: {
    // When the Fulltext/OpenSearch module is active, dashboard keyword
    // search is delegated to OpenSearch and covers all extracted fields.
    // Otherwise it only matches on filename / doc_id / invoice_id /
    // purchase_order.
    isFulltextEnabled(): boolean {
      return this.isTruthy(
        (this.org_based_settings as any)?.OPENSEARCH_ENABLED,
      );
    },

    // Vector (semantic) search — enabled when any of the document-scope
    // OpenSearch vector indices is active.
    //
    // Vector is a SUB-SETTING of Fulltext: the OPENSEARCH_VECTOR_* flags
    // can only be toggled from inside the Fulltext settings page, so an
    // org with fulltext disabled has no way to manage vector. We treat
    // vector as effectively off in that state — the search bar shows
    // Standard mode, the autocomplete hides the vector group, and the
    // help dialog hides the vector tab. Once fulltext is enabled again,
    // the raw OPENSEARCH_VECTOR_* flags decide whether vector is on.
    isVectorEnabled(): boolean {
      if (!this.isFulltextEnabled) return false;
      const s = (this.org_based_settings as any) || {};
      return (
        this.isTruthy(s.OPENSEARCH_VECTOR_DOCUMENTS) ||
        this.isTruthy(s.OPENSEARCH_VECTOR_INVOICES) ||
        this.isTruthy(s.OPENSEARCH_VECTOR_ATTACHMENTS)
      );
    },

    // Comma-separated, locale-aware list of every STANDARD field from
    // the catalog. Auto-refreshes when FIELD_CATALOG hydrates from the
    // backend on app start.
    availableStandardFieldLabels(): string {
      return FIELD_CATALOG.filter((f) => f.category === 'standard')
        .map((f) =>
          f.labelKey
            ? this.tf(f.labelKey, f.displayName ?? f.name)
            : (f.displayName ?? f.name),
        )
        .filter((s): s is string => Boolean(s))
        .join(', ');
    },

    // Same shape as availableStandardFieldLabels but for EXTENDED-
    // category fields. Empty string when no extended fields exist;
    // the tooltip omits the row in that case.
    availableExtendedFieldLabels(): string {
      return FIELD_CATALOG.filter((f) => f.category === 'extended')
        .map((f) =>
          f.labelKey
            ? this.tf(f.labelKey, f.displayName ?? f.name)
            : (f.displayName ?? f.name),
        )
        .filter((s): s is string => Boolean(s))
        .join(', ');
    },

    // 2026-05-05: integer % shown as the inline sync badge next to the
    // help (?) button. Prefers the SSE-driven stats (live, updates
    // every snapshot the backend pushes) and falls back to the
    // legacy mouseenter-fetched stats if SSE hasn't connected yet.
    // Returns null when Fulltext is off OR no stats loaded — the
    // toolbar hides the badge in that case.
    indexSyncPercent(): number | null {
      if (!this.isFulltextEnabled) return null;
      const stats = (this.docStatsSSE as any) ?? this.documentIndexStats;
      if (!stats) return null;
      const total = stats.in_database ?? 0;
      if (total <= 0) return null;
      const indexed = stats.total_indexed ?? 0;
      return Math.max(0, Math.min(100, Math.round((indexed / total) * 100)));
    },

    indexSyncDocumentsLine(): string | null {
      if (!this.isFulltextEnabled) return null;
      const stats = (this.docStatsSSE as any) ?? this.documentIndexStats;
      if (!stats) return null;
      const total = stats.in_database ?? 0;
      if (total <= 0) return null;
      const indexed = stats.total_indexed ?? 0;
      return formatDocumentsLine(
        indexed,
        total,
        (n) => this.formatIndexNumber(n),
        (i, t, p) =>
          (i18n as any).t('fulltext_ring_documents_progress', {
            indexed: i,
            total: t,
            pending: p,
          }),
        (p) => (i18n as any).t('fulltext_ring_pending_suffix', { n: p }),
      );
    },

    indexSyncVectorLine(): string | null {
      if (!this.isFulltextEnabled) return null;
      const stats = (this.docStatsSSE as any) ?? this.documentIndexStats;
      if (!stats) return null;
      const total = stats.in_database ?? 0;
      if (total <= 0) return null;
      const embedded = stats.with_vector ?? 0;
      return formatVectorLine(
        this.isVectorEnabled,
        embedded,
        total,
        (n) => this.formatIndexNumber(n),
        (e, t, p) =>
          (i18n as any).t('fulltext_ring_vector_progress', {
            embedded: e,
            total: t,
            pending: p,
          }),
        (p) => (i18n as any).t('fulltext_ring_pending_suffix', { n: p }),
      );
    },

    searchPlaceholder(): string {
      return this.isFulltextEnabled
        ? (i18n as any).t('search_by_any_field')
        : (i18n as any).t('search_by_name_or_Id');
    },

    // Strict mapping: bolt + warning-orange ONLY when Fulltext routing
    // (OPENSEARCH_ENABLED) is on. Vector-only state gets its own symbol
    // and color so it's visually distinct from Fulltext. This keeps the
    // 1:1 contract with the time-filter hide gate in header.vue, which
    // is also keyed strictly on isFulltextEnabled.
    capabilityIcon(): string {
      if (this.isFulltextEnabled) return 'bolt';
      if (this.isVectorEnabled) return 'auto_awesome';
      return 'flash_off';
    },

    capabilityIconClass(): string {
      if (this.isFulltextEnabled && this.isVectorEnabled)
        return 'capability-full';
      if (this.isFulltextEnabled) return 'capability-fulltext-only';
      if (this.isVectorEnabled) return 'capability-vector-only';
      return 'capability-none';
    },

    needsFulltextButMissing(): boolean {
      return (
        (this.lastParsed as ParsedSearch).requiresFulltext &&
        !this.isFulltextEnabled
      );
    },

    liveValidationErrors(): ValidationError[] {
      return validateQuery(this.rawQueryText).errors;
    },

    canLeaveRawView(): boolean {
      return !this.showRaw || this.liveValidationErrors.length === 0;
    },

    displayedValidationErrors(): ValidationError[] {
      const list: ValidationError[] = [];
      if (this.showErrors) list.push(...this.liveValidationErrors);
      const srv = this.serverValidationError;
      if (srv && srv.rawSnapshot === this.rawQueryText) {
        list.push({ code: 'server_rejected', message: srv.message });
      }
      return list;
    },
  },

  watch: {
    isFulltextEnabled(enabled: boolean) {
      if (enabled) {
        // 2026-05-05: org settings load async — at mount() time
        // `isFulltextEnabled` may still be false because
        // `org_based_settings.OPENSEARCH_ENABLED` hasn't hydrated
        // yet. The watcher catches the flip-to-true and opens the
        // SSE stream the dashboard needs for the realtime sync-%
        // badge. The composable's startStatusStream is idempotent
        // (closes any existing stream first), so an extra call from
        // mounted() doesn't cause a duplicate connection.
        (this as any).startSSEStream?.();
        void this.refreshIndexSyncStatus(true);
        return;
      }
      this.documentIndexStats = null;
      this.indexSyncError = false;
      // Tear down the SSE EventSource when the org loses Fulltext
      // (or hadn't enabled it to begin with) so we're not pinging
      // a backend the workspace can't authenticate against anyway.
      (this as any).sseCleanup?.();
    },

    rawQueryText() {
      // Track whether the raw text has diverged from the committed
      // state so toggle-back knows whether to push the edits back into
      // the chip editor (avoids wiping a user's clean switch-back).
      if (this.showRaw) this.rawDirty = true;
    },

    // Hide the validation banner automatically once the query becomes
    // valid (or empty). Surfacing back is gated by explicit triggers
    // (Enter / view toggle / debounced apply) — see
    // triggerValidationDisplay.
    liveValidationErrors() {
      if (
        this.liveValidationErrors.length === 0 ||
        !this.rawQueryText ||
        !this.rawQueryText.trim()
      ) {
        this.showErrors = false;
      }
    },
  },

  mounted() {
    // DRFS-534: search now fires only on explicit Enter — no debounced
    // auto-apply. onChipSubmit / applyRaw call applyIfSignatureChanged
    // directly.
    window.addEventListener('resize', this.elementLoadedEvent);

    // 2026-05-05: open the SSE stream that drives the realtime
    // index-sync % badge. Only when Fulltext is enabled — otherwise
    // there's nothing to stream and we'd just open a doomed
    // connection. The composable handles its own polling fallback,
    // reconnects, and idle heartbeats.
    if ((this as any).isFulltextEnabled) {
      (this as any).startSSEStream();
    }

    // Bug-2026-04-25 Refresh-Table sync: re-render whatever is
    // currently in `quickFilterMap` so what-you-see equals what's
    // applied. See resyncVisibleStateOnRefresh.
    document.addEventListener(
      'dashboard_refresh_data',
      this.resyncVisibleStateOnRefresh,
    );

    // ── Index-sync status seed ────────────────────────────────────
    void this.refreshIndexSyncStatus(true);

    // ── Hydration from localStorage / store ───────────────────────
    // Re-seed the visible chip editor's scratchpad (tempFilterMap)
    // from the canonical filter state on every remount. Handles the
    // Dashboard ↔ /field_validation_v1 round-trip.
    if ((this.quickFilterMap as Map<string, unknown>).size > 0) {
      (this.tempFilterMap as any) = new Map(
        this.quickFilterMap as Map<string, unknown>,
      );
    }
    const raw = this.hydrateFromStore();
    if (raw) {
      this.initialQuery = raw;
      this.hasHydrated = true;
      // QuickSearchBox.mounted has already run with empty
      // initialQuery (Vue mounts children before parent). Dispatch
      // load_saved_filter so the editor's listener calls
      // setContent and the chip(s) become visible.
      nextTick(() => {
        document.dispatchEvent(
          new CustomEvent('load_saved_filter', { detail: { raw } }),
        );
      });
    }
    // Other components (status-filter, docTypeTabs) populate
    // quickFilterMap asynchronously after their own onMount. Watch
    // until the first chip-relevant slot appears, but ONLY re-seed
    // when the editor is still empty.
    this._columnFilterUnsubscribe = (this.columnFilterStore as any).$subscribe(
      () => {
        if (this.hasHydrated) return;
        const pm = document.querySelector(
          '.qs-box .ProseMirror',
        ) as HTMLElement | null;
        const editorHasContent =
          !!pm &&
          (pm.querySelector('.qs-chip') ||
            (pm.textContent ?? '').trim().length > 0);
        if (editorHasContent) {
          this.hasHydrated = true;
          this._columnFilterUnsubscribe?.();
          this._columnFilterUnsubscribe = null;
          return;
        }
        const raw2 = this.hydrateFromStore();
        if (!raw2) return;
        (this.tempFilterMap as any) = new Map(
          this.quickFilterMap as Map<string, unknown>,
        );
        this.hasHydrated = true;
        document.dispatchEvent(
          new CustomEvent('load_saved_filter', { detail: { raw: raw2 } }),
        );
        this._columnFilterUnsubscribe?.();
        this._columnFilterUnsubscribe = null;
      },
    );

    // External `load_saved_filter` events update both initialQuery
    // and the hydration flag so a subsequent store push doesn't
    // re-seed over the user-driven content.
    document.addEventListener('load_saved_filter', this.onLoadSavedFilterEv);

    // Group-by drill-down companion to dashboard.vue's
    // drillIntoBucket. The dashboard clears its selectedGroupBy
    // and dispatches this event; we append a `<field>="<value>"`
    // predicate via setRawQuery (in-place, not a remount).
    document.addEventListener(
      'quick_search_apply_predicate',
      this.onApplyPredicate,
    );

    // Server-side validation channel: dashboard.vue forwards 422/400
    // detail through this event so we can show the server message
    // inline instead of a toast.
    document.addEventListener(
      'quick_search_server_validation_error',
      this.onServerValidationError,
    );
  },

  beforeUnmount() {
    // Close the SSE EventSource opened in mounted() — otherwise the
    // browser keeps the long-poll alive after navigation away from
    // the dashboard and you accumulate one stream per page visit.
    (this as any).sseCleanup?.();

    document.removeEventListener(
      'dashboard_refresh_data',
      this.resyncVisibleStateOnRefresh,
    );
    document.removeEventListener('load_saved_filter', this.onLoadSavedFilterEv);
    document.removeEventListener(
      'quick_search_apply_predicate',
      this.onApplyPredicate,
    );
    document.removeEventListener(
      'quick_search_server_validation_error',
      this.onServerValidationError,
    );
    window.removeEventListener('resize', this.elementLoadedEvent);
    this._columnFilterUnsubscribe?.();
    this._columnFilterUnsubscribe = null;
  },

  methods: {
    elementLoadedEvent() {
      const event = new CustomEvent('load_saved_filter_badge', { detail: '' });
      document.dispatchEvent(event);
    },

    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
    },

    // Backend preferences may arrive as '1', 'true', 'True', true, etc.
    isTruthy(val: unknown): boolean {
      const s = String(val ?? '')
        .toLowerCase()
        .trim();
      return s === 'true' || s === '1' || s === 'yes' || s === 'on';
    },

    // Translate-with-fallback. Used in the capability tooltip and the
    // index-sync summary to keep strings rendering even when a Tolgee
    // key hasn't been pushed yet.
    tf(key: string, fallback: string): string {
      const translated = (i18n as any).t(key);
      return translated === key ? fallback : String(translated);
    },

    formatIndexNumber(value: number): string {
      return new Intl.NumberFormat().format(value);
    },

    async refreshIndexSyncStatus(force = false) {
      if (!this.isFulltextEnabled) {
        this.documentIndexStats = null;
        this.indexSyncError = false;
        return;
      }
      if (this.indexSyncLoading) return;
      if (
        !force &&
        this.documentIndexStats &&
        Date.now() - this.indexSyncLoadedAt < INDEX_SYNC_CACHE_MS
      ) {
        return;
      }
      this.indexSyncLoading = true;
      this.indexSyncError = false;
      try {
        const response = await (
          this.fulltextSettingsApi as any
        ).getDocumentStats();
        this.documentIndexStats = response.stats;
        this.indexSyncLoadedAt = Date.now();
      } catch {
        this.indexSyncError = true;
      } finally {
        this.indexSyncLoading = false;
      }
    },

    // Editor content is hydrated from `raw_query` only.
    //
    // URL wins over the store: if the user landed here with
    // `?raw_query=…`, that's the explicit intent (shared link /
    // bookmark / dashboard chip-link). Mirror it into the store so
    // the rest of the app sees a single source of truth.
    hydrateFromStore(): string {
      const urlRaw = this.readUrlRawQuery();
      if (urlRaw) {
        (this.quickFilterMap as Map<string, unknown>).set('raw_query', urlRaw);
        return urlRaw;
      }
      const raw = (this.quickFilterMap as Map<string, unknown>).get(
        'raw_query',
      ) as string | undefined;
      return raw ?? '';
    },

    onLoadSavedFilterEv(ev: any) {
      this.hasHydrated = true;
      const nextRaw = ev.detail?.raw ?? this.hydrateFromStore();
      this.initialQuery = nextRaw;
      this.rawQueryText = nextRaw;
      // DRFS-583 — `load_saved_filter` is dispatched by dashboard
      // switches and `resetViewToDefault`. Both rewrite the chip
      // content programmatically, which then re-fires @parsed →
      // applyIfSignatureChanged. Without resetting the signature
      // baseline, that first programmatic apply would diff against
      // the *previous* dashboard's signature and incorrectly mark
      // the freshly-loaded dashboard as dirty.
      this.lastAppliedSignature = '';
    },

    onApplyPredicate(ev: any) {
      const detail = ev?.detail as
        | { field: string; op: string; value: string }
        | undefined;
      if (!detail || !detail.field) return;
      const opStr = detail.op || '=';
      const valueLiteral = /[\s"]/.test(detail.value)
        ? `"${detail.value.replace(/"/g, '\\"')}"`
        : detail.value;
      const newPredicate = `${detail.field}${opStr}${valueLiteral}`;
      const ref = this.$refs.quickSearchBoxRef as any;
      const existing = ref?.getRawQuery?.() ?? '';
      // DOCB-12249 (Codex Round 3 LOW DRY): use the shared
      // stripGroupByDirective() helper instead of an inline copy of
      // GROUP_BY_SUFFIX_RE — one regex, one source of truth.
      const cleaned = stripGroupByDirective(String(existing));
      const merged = cleaned ? `${cleaned} AND ${newPredicate}` : newPredicate;
      ref?.setRawQuery?.(merged);
    },

    onServerValidationError(e: Event) {
      const detail = (e as CustomEvent).detail;
      const message = String(detail?.message ?? '').trim();
      if (!message) return;
      this.serverValidationError = {
        message,
        rawSnapshot: this.rawQueryText,
      };
    },

    // Banner only renders when explicitly triggered: pressing Enter,
    // attempting a view toggle, or when filters are actually applied.
    triggerValidationDisplay() {
      this.showErrors = true;
    },

    setRawQueryText(v: string) {
      this.rawQueryText = v;
    },

    async copyRawQuery() {
      if (!this.rawQueryText) return;
      try {
        await navigator.clipboard.writeText(this.rawQueryText);
        Notify.create({
          type: 'positive',
          message: (i18n as any).t('search_raw_copied'),
          timeout: 1500,
          position: 'top',
        });
      } catch {
        /* clipboard unavailable in insecure context */
      }
    },

    toggleRaw() {
      if (!this.showRaw) {
        const ref = this.$refs.quickSearchBoxRef as any;
        this.rawQueryText = ref?.getRawQuery?.() ?? '';
        this.rawDirty = false;
        this.showRaw = true;
      } else {
        this.applyRawIfDirty();
        this.showRaw = false;
      }
    },

    setViewMode(mode: 'standard' | 'raw') {
      const goRaw = mode === 'raw';
      if (goRaw === this.showRaw) return;
      if (!goRaw && this.liveValidationErrors.length > 0) {
        this.triggerValidationDisplay();
        return;
      }
      this.toggleRaw();
    },

    applyRawIfDirty() {
      this.rawDirty = false;
      const ref = this.$refs.quickSearchBoxRef as any;
      ref?.setRawQuery?.(this.rawQueryText);
      // DRFS-534: Enter in raw mode fires unconditionally — same
      // contract as the chip editor.
      this.forceApply();
    },

    applyRaw() {
      if (this.liveValidationErrors.length > 0) {
        this.triggerValidationDisplay();
        return;
      }
      this.applyRawIfDirty();
    },

    onParsed(parsed: ParsedSearch) {
      this.lastParsed = parsed;

      const ref = this.$refs.quickSearchBoxRef as any;
      const rawQuery = ref?.getRawQuery?.() ?? '';
      // DOCB-12249 (Hanna's comment #86606 follow-up): the FULL
      // user-typed query — including any trailing `group by <field>`
      // directive — is persisted into `quickFilterMap.raw_query` and
      // ultimately into LocalStorage. Without the directive in the
      // persisted string, a Dashboard ↔ /field_validation_v1
      // round-trip would rehydrate the chip editor without the
      // `Gruppieren nach :` chip even though `selectedGroupByState`
      // (Pinia) kept the table grouped. The HTTP wire strip is
      // performed exactly once in `makeQueryParamFromFilters()` via
      // `stripGroupByDirective()`; computeQuickSearchSlots treats
      // raw_query as opaque (only the `is_fulltext`/`is_vector` slot
      // routing inspects `parsed`), so passing the full query is safe.
      if (!this.showRaw) this.setRawQueryText(rawQuery);

      if (rawQuery.trim() && !validateQuery(rawQuery).valid) {
        return;
      }

      // 2026-05-07: previously this gated `onParsed` itself when the
      // autocomplete popover was open with suggestions — a leftover from
      // pre-DRFS-534 when typing fired a debounced apply and we wanted
      // to suppress half-finished predicates from reaching the backend.
      // DRFS-534 removed the auto-apply: search now fires only on
      // explicit Enter (forceApply). With no auto-apply to gate, this
      // early-return became dead code that actively broke Enter.
      //
      // Repro: type `test`. The autocomplete popover opens with
      // suggestions matching the prefix → shouldSkipApply returns true
      // → onParsed early-returns BEFORE the quickFilterMap.set('raw_query')
      // below → user presses Enter → forceApply reads stale (or empty)
      // raw_query → backend returns last-applied or all docs (the
      // "factura/sample leftover" symptom). Removing the gate lets
      // state always sync; Enter behaviour is unchanged because the
      // forceApply path doesn't read AC state at all.

      this.reset_pagination = false;

      const writtenSlots = new Set<string>();

      const hasDatePredicate = parsed.predicates.some((p) => {
        const meta = FIELD_CATALOG.find((f) => f.name === p.field);
        return meta?.valueType === 'date';
      });
      if (
        hasDatePredicate &&
        (this.quickFilterMap as Map<string, unknown>).has('filter')
      ) {
        (this.quickFilterMap as Map<string, unknown>).delete('filter');
        this.reset_pagination = true;
      }

      const slots = computeQuickSearchSlots(
        parsed,
        rawQuery,
        (name) =>
          parsed.chipCategoryOverrides?.get(name) ??
          FIELD_CATALOG.find((f) => f.name === name)?.category,
        {
          fulltextEnabled: this.isFulltextEnabled,
          vectorEnabled: this.isVectorEnabled,
        },
      );
      for (const [key, value] of Object.entries(slots)) {
        const prev = (this.quickFilterMap as Map<string, unknown>).get(key);
        if (prev !== value) this.reset_pagination = true;
        (this.quickFilterMap as Map<string, unknown>).set(key, String(value));
        writtenSlots.add(key);
      }

      const prevSlots = this.chipOwnedKeys;
      for (const key of prevSlots) {
        if (!writtenSlots.has(key)) {
          (this.quickFilterMap as Map<string, unknown>).delete(key);
          this.reset_pagination = true;
        }
      }
      this.chipOwnedKeys = writtenSlots;

      if (parsed.sortOverride) {
        (this.quickFilterMap as Map<string, unknown>).set(
          'order_by_field',
          parsed.sortOverride.field,
        );
        (this.quickFilterMap as Map<string, unknown>).set(
          'order_by_direction',
          parsed.sortOverride.direction,
        );
        this.reset_pagination = true;
      }

      const groupBy = parsed.groupByOverride ?? null;
      if (groupBy !== this.lastEmittedGroupBy) {
        this.lastEmittedGroupBy = groupBy;
        document.dispatchEvent(
          new CustomEvent('quick_search_group_by', { detail: groupBy }),
        );
        this.reset_pagination = true;
      }

      if (this.hasHydrated && rawQuery !== this.initialQuery) {
        this.checkForDashboardUpdates();
      }
    },

    // DRFS-581: bolt-icon click. Focus the chip editor and open the
    // field-mode autocomplete so the user can browse smart filters
    // and available fields without first having to type a character.
    openSearchPicker() {
      if (this.showRaw) return;
      ((this.$refs.quickSearchBoxRef as any) ?? null)?.openSearch?.();
    },

    // DRFS-581: chip-view Enter handler. QuickSearchBox emits @submit
    // only when no autocomplete suggestion intercepted the keystroke,
    // so reaching here means the user wants their typed query
    // searched right now.
    onChipSubmit() {
      if (this.liveValidationErrors.length > 0) {
        this.triggerValidationDisplay();
        return;
      }
      // DRFS-534: explicit user Enter — fire unconditionally, even if
      // the filter signature is unchanged from the previous fire.
      // `applyIfSignatureChanged` is reserved for programmatic resyncs
      // where the signature gate prevents redundant round-trips.
      this.forceApply();
    },

    computeFilterSignature(): string {
      const m = this.quickFilterMap as Map<string, unknown>;
      const keys = [
        'keyword',
        'filter_predicates',
        'filter_predicates_connector',
        'raw_query',
        'is_fulltext',
        'is_vector',
        'doc_type',
        'status',
        'status_list',
      ];
      const parts: string[] = [];
      for (const k of keys) {
        const v = m.get(k);
        parts.push(k + '=' + (v === undefined ? '' : JSON.stringify(v)));
      }
      return parts.join('|');
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', {
        detail: { reset_pagination: this.reset_pagination },
      });
      document.dispatchEvent(event);
    },

    applyIfSignatureChanged() {
      const sig = this.computeFilterSignature();
      if (sig === this.lastAppliedSignature) return;
      // Bare-text-too-short gate: the OS .trigram subfield's ngram
      // tokenizer (min_gram=3) drops short queries to zero tokens,
      // collapsing the multi_match to match_all — typing `po` returned
      // every doc in the org. Hold off the apply until the query is
      // either ≥ 3 chars per phrase OR contains structured operators.
      // Don't update lastAppliedSignature so the next keystroke that
      // crosses the 3-char floor still fires.
      if (shouldGateBareTextTooShort(this.rawQueryText)) {
        return;
      }
      const priorSignature = this.lastAppliedSignature;
      this.lastAppliedSignature = sig;
      if (this.liveValidationErrors.length > 0) {
        this.triggerValidationDisplay();
      }
      // DRFS-583 — typing in the chip editor / changing the raw_query
      // counts as a dashboard mutation, surface the "Save dashboard
      // changes" badge. The first apply after a load_saved_filter
      // (priorSignature === '') is a programmatic hydration, not user
      // input, so it must not flip the dirty flag. See shouldMarkDirty.
      if (shouldMarkDirty(priorSignature, sig)) {
        this.checkForDashboardUpdates();
      }
      this.triggerApplyFilters();
    },

    // DRFS-534: explicit-fire variant for the user pressing Enter. Skips
    // the signature equality short-circuit so re-pressing Enter on the
    // same query (or after clearing → retyping the same string) still
    // re-runs the search. Validation gating happens upstream.
    forceApply() {
      // Trigram-floor gate also applies to Enter-fire: a 2-char bare
      // text query like `po` collapses the OS multi_match to match_all
      // (every doc returns as a hit). Same reasoning as the gate inside
      // applyIfSignatureChanged — see shouldGateBareTextTooShort docs.
      if (shouldGateBareTextTooShort(this.rawQueryText)) {
        return;
      }
      const sig = this.computeFilterSignature();
      const priorSignature = this.lastAppliedSignature;
      this.lastAppliedSignature = sig;
      if (shouldMarkDirty(priorSignature, sig)) {
        this.checkForDashboardUpdates();
      }
      this.triggerApplyFilters();
    },

    applyFilters() {
      (this.quickFilterMap as any) = new Map(
        this.tempFilterMap as Map<string, unknown>,
      );
      this.reset_pagination = false;
      this.triggerApplyFilters();
    },

    resyncVisibleStateOnRefresh() {
      (this.tempFilterMap as any) = new Map(
        this.quickFilterMap as Map<string, unknown>,
      );
      this.lastAppliedSignature = '';
      this.applyIfSignatureChanged();
    },

    onFilterShow() {
      (this.tempFilterMap as any) = new Map(
        this.quickFilterMap as Map<string, unknown>,
      );
    },

    onFilterHide() {
      // Save is wired through applyFilters; nothing to do on hide.
    },

    // Read `?raw_query=…` from the URL when the dashboard is opened
    // via a shared link. URL params win over the store on first
    // mount (Bug-2026-05-05): a Slack-shared link must override any
    // previously-saved local filter, otherwise the recipient sees
    // the sender's filter clobbered by their own saved state.
    readUrlRawQuery(): string {
      try {
        const sp = new URLSearchParams(window.location.search);
        return sp.get('raw_query') ?? '';
      } catch {
        return '';
      }
    },
  },
});
</script>

<!--
  Unscoped layout fixes for the header row that wraps this component.
  Scoped styles can't reach sibling elements (TimeFilter, action
  buttons) so these rules live here instead of in header.vue to keep
  the search-related sizing all in one file.
-->
<style lang="scss">
// Equalise the TimeFilter's visible height with the search input and
// the outline action buttons so the row reads as a single row of
// consistent 38px controls — otherwise the q-btn-toggle's natural
// height is shorter and floats vertically off-centre in `items-center`.
.toggle_time.q-btn-group > .q-btn {
  min-height: 38px;
}
// Breathing room between the search column (which also contains the
// inline Standard/Raw toggle) and the external action buttons to its
// right. Without this the toggle sits flush against the first button.
.dashboard-search-box {
  margin-right: 16px;
}

// Disable programming-ligature substitutions everywhere the search
// surface renders monospace text — chip editor, raw editor, and the
// autocomplete's code rows. Fonts with ligature tables (FiraCode,
// JetBrains Mono, Cascadia, etc.) render `>=` as ≥, `<=` as ≤, and
// `!=` as ≠. Users can't type those glyphs — they type the two-char
// forms — so the UI has to show the ASCII the grammar actually
// accepts.
.qs-editor,
.qs-raw-editor-pm,
.text-mono,
.qs-ac-op,
.qs-ac-value-sub {
  font-variant-ligatures: none;
  font-feature-settings:
    'liga' 0,
    'clig' 0,
    'calt' 0;
}
</style>

<style lang="scss" scoped>
// Wrapper around the two switchable editors (chip + raw) so flex
// layout stays identical regardless of which view is active. Both
// inner editors stretch to fill this slot, so toggling doesn't
// re-flow the row width.
.qs-editor-slot {
  display: flex;
  position: relative;
}
.qs-editor-slot__editor {
  flex: 1;
  width: 100%;
}

// Single-icon capability indicator — replaces two full-size status
// chips. Colour signals state at a glance; tooltip carries the
// details that used to live on the chips themselves.
.search-capability-icon {
  cursor: default;
}
.search-capability-icon--clickable {
  cursor: pointer;
  transition:
    transform 80ms ease,
    opacity 80ms ease;
  &:hover {
    transform: scale(1.1);
    opacity: 1;
  }
  &:active {
    transform: scale(0.95);
  }
}
// Color contract:
//   orange (var(--warning))            = Fulltext routing on (OPENSEARCH_ENABLED).
//                                        Same color the time-filter-hide gate
//                                        in header.vue keys on, so the bolt
//                                        and the disappearing 30D/90D buttons
//                                        always agree.
//   info/secondary (var(--info))       = Vector-only (semantic embeddings on,
//                                        Fulltext routing off). Distinct
//                                        symbol (auto_awesome) and color so
//                                        users don't read it as Fulltext.
//   muted (var(--muted-foreground))    = neither active.
// History: an earlier iteration shared one warning-orange across both tiers
// (full or partial) to dodge a blue-as-primary readability issue. That made
// "Vector-only" look identical to "Fulltext on", which conflicted with the
// time-filter gate keyed strictly on OPENSEARCH_ENABLED. Now decoupled.
.capability-full,
.capability-fulltext-only {
  color: var(--warning);
}
.capability-vector-only {
  color: var(--info, var(--primary));
}
.capability-none {
  color: var(--muted-foreground);
  opacity: 0.7;
}
.qs-fulltext-warning {
  margin: 0 4px 0 0;
  white-space: nowrap;
}
.search-predicate-chip {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  height: 20px;
}
.search-invoices {
  // Grow to fill the available row width. Tune buttons now live inside
  // the input so the outer row only has the editor + the view-mode
  // toggle, freeing up horizontal space. Min-width stays low so the
  // input can shrink gracefully on narrow viewports; wrapping to its
  // own row above 1400px is handled by the parent-row media query.
  width: 100%;
  min-width: 320px;
  padding: 0;
  transition: width 0.3s;
  // &.search-active, &.q-field--focused {
  //   width: 600px;
  // }
  // &.search-in-active {
  //   width: 200px;
  // }
}
:deep(.q-menu.q-position-engine.scroll .q-item.q-item-type) {
  padding: 2px 16px !important;
  min-height: 38px !important;
}
:deep(.q-menu.q-position-engine.scroll .q-item.q-item-type .q-checkbox__inner) {
  font-size: 35px !important;
}
:deep(
  .q-menu.q-position-engine.scroll
    .q-item.q-item-type
