/**
 * TipTap custom inline node for a logical connector: AND or OR.
 *
 * Why a node (atomic), not a chip attribute or plain text:
 * - The old model stored `connector: 'AND'|'OR'` as an attribute on
 *   the NEXT chip. That falls apart for grouped queries — if the
 *   sequence is `chip AND ( chip OR chip )`, the AND belongs between
 *   the chip and the paren, not on the chip inside the group. There's
 *   no chip to attach it to without breaking document order.
 * - Plain text would work but leaves the user's typed "AND " stranded
 *   when they follow it with a `(` (the paren input rule atomizes the
 *   paren, the text stays — visible as a gap with loose "AND" text).
 * - As an atomic node, AND/OR flow in document order alongside chips
 *   and parens; serialization walks them in place; the NodeView renders
 *   a clickable toggle that flips the kind in one keystroke.
 *
 * Attribute: `kind: 'AND' | 'OR'`.
 * Input rule: typing `AND ` / `OR ` (case-insensitive) converts the
 * matched text to this node.
 */

import { Node, mergeAttributes, nodeInputRule } from '@tiptap/core';
import { VueNodeViewRenderer } from '@tiptap/vue-3';
import type { Component } from 'vue';
import { connectorInputRuleRegex } from '../searchConnectors';

export type ConnectorKind = 'AND' | 'OR';

export interface ConnectorAttrs {
  kind: ConnectorKind;
}

export function createConnectorNode(ConnectorNodeViewComponent: Component) {
  return Node.create<never>({
    name: 'connector',

    group: 'inline',
    inline: true,
    atom: true,
    selectable: true,
    draggable: false,

    addAttributes() {
      return {
        kind: { default: 'AND' },
      };
    },

    parseHTML() {
      return [
        {
          tag: 'span[data-connector]',
          getAttrs(el) {
            const dom = el as HTMLElement;
            const k = dom.getAttribute('data-kind');
            return { kind: k === 'OR' ? 'OR' : 'AND' };
          },
        },
      ];
    },

    renderHTML({ HTMLAttributes }) {
      return [
        'span',
        mergeAttributes(HTMLAttributes, { 'data-connector': '' }),
      ];
    },

    // DOCB-11199 follow-up: clipboard plain-text surrounds AND/OR
    // with spaces so `chip1 AND chip2` round-trips through the
    // parser without the connector fusing to a neighbouring value.
    renderText({ node }) {
      const kind = (node.attrs as { kind?: string }).kind ?? 'AND';
      return ` ${kind} `;
    },

    addNodeView() {
      return VueNodeViewRenderer(ConnectorNodeViewComponent as any);
    },

    // Case-insensitive: typing a connector word + space triggers the
    // conversion — in any supported language (AND/UND/ET → AND,
    // OR/ODER/OU → OR), DOCB-13123. The trailing space is consumed as
    // part of the match so the caret lands cleanly after the node, and a
    // word boundary keeps short words (et/ou) from firing inside a value.
    addInputRules() {
      return [
        nodeInputRule({
          find: connectorInputRuleRegex('AND'),
          type: this.type,
          getAttributes: { kind: 'AND' },
        }),
        nodeInputRule({
          find: connectorInputRuleRegex('OR'),
          type: this.type,
          getAttributes: { kind: 'OR' },
        }),
      ];
    },
  });
}
